/* chronicle data chunk: wd-01 | 世界史 前3000–前479（含前501后区间尾部希波战争） | 生成于 2026-09-21 */
window.__CHRONICLE_CHUNK = window.__CHRONICLE_CHUNK || {};
window.__CHRONICLE_CHUNK["wd-01"] = [
  { id: "world--b3000--s01", track: "world", year: -3000, yearApprox: true, dim: "science", weight: 5, title: "楔形文字成形于苏美尔", summary: "乌鲁克泥板由清点符号演变为可记录语言的书写系统。", detail: { background: "前四千纪末两河流域南部神庙仓库需登记牲畜、谷物与劳役，出现刻符泥板与封球记账法。", process: "约前3100年乌鲁克第四期出土上千块原始楔形泥板，符号偏象形且仅表词；前3000年前后书写改为横排左行，符号按苏美尔语取得音值，出现音节符、限定符与十进制位值数字。", impact: "文字使税册、条约、医学与文学可跨代累积，两河由此进入有文字可考的历史，符号体系后为埃兰、胡里安、赫梯与阿拉姆诸语借用改造。", figures: ["不可考的乌鲁克书吏"], place: "苏美尔乌鲁克（今伊拉克瓦尔卡）", state: "苏美尔城邦", sources: ["德国考古研究所乌鲁克发掘报告", "范德米尔洛普《古代近东：公元前3000—前323年》", "《剑桥古代史》第1卷第2分册"], tags: ["楔形文字", "乌鲁克", "书写起源"] }, related: [] },
  { id: "world--b3000--s02", track: "world", year: -3000, yearApprox: true, dim: "science", weight: 4, title: "埃及象形文字成熟", summary: "尼罗河谷发展出兼表意与表音的神圣雕刻书体。", detail: { background: "埃及在前四千纪末借用两河记账观念，结合本土王名圈与图像符号创造自有文字。", process: "阿拜多斯与萨卡拉出土的标签、象牙签与王名框显示，约前3100—前3000年已形成数百个符号的体系；圣书体用于纪念碑，其后派生出僧侣体与世俗体供日常书写。", impact: "象形文字支撑了埃及三千年的宗教、行政与天文记录，其单辅音符号对后世闪米特字母的起源问题长期被学界讨论。", figures: ["不可考的那尔迈时代书吏"], place: "上埃及阿拜多斯、孟菲斯（今埃及索哈杰以北）", state: "古埃及", sources: ["《剑桥古代史》第1卷", "加德尔尼《埃及象形文字入门》", "阿拜多斯王表铭文"], tags: ["象形文字", "书写起源", "尼罗河"] }, related: [] },
  { id: "world--b3000--p01", track: "world", year: -3000, yearApprox: true, dim: "politics", weight: 5, title: "上下埃及统一与早王朝", summary: "尼罗河谷与三角洲合并为一个王权国家，定都孟菲斯。", detail: { background: "前四千纪末上埃及希拉孔波利斯的王权借助灌溉与远程贸易扩张，与三角洲诸酋邦冲突。", process: "那尔迈调色板以王冠、红白双冠与连击敌酋的图像宣示统一；学界传统将其置于约前3100年，本数据集按不早于前3000年收录第一至第二王朝。", impact: "统一国家使法老得以集中征发劳役、组织灌溉与粮仓，成为人类最早的大一统官僚政体之一，为古王国金字塔工程提供制度前提。", figures: ["那尔迈", "美尼斯（传说人物）"], place: "上埃及希拉孔波利斯至三角洲（今埃及卢克索—开罗）", state: "古埃及", sources: ["大英博物馆那尔迈调色板馆藏说明", "《剑桥古代史》第1卷", "卡普塔《早期埃及》"], tags: ["早王朝", "国家统一", "法老"] }, related: [] },
  { id: "world--b3000--e01", track: "world", year: -3000, yearApprox: true, dim: "economy", weight: 4, title: "乌鲁克的城市革命", summary: "神庙经济组织灌溉、纺织与远距离贸易，人口急聚。", detail: { background: "冲积平原缺石缺木缺金属，神庙以再分配方式集中粮食与手工业品以换取外部原料。", process: "乌鲁克扩张至约100公顷，埃安娜台区以锥形马赛克装饰的会堂与仓库群，出土泥板显示按等份配给大麦、油脂与啤酒，并组织通向伊朗、安纳托利亚与埃及的贸易。", impact: "以神庙为枢纽的再分配经济成为苏美尔城邦的典型模式，也是城市、阶级与行政管理同步起源的考古证据。", figures: ["不可考的乌鲁克管理者"], place: "苏美尔乌鲁克（今伊拉克瓦尔卡）", state: "苏美尔城邦", sources: ["德国考古研究所乌鲁克发掘报告", "范德米尔洛普《古代近东：公元前3000—前323年》"], tags: ["城市革命", "神庙经济", "再分配"] }, related: [] },
  { id: "world--b3000--s03", track: "world", year: -3000, yearApprox: true, dim: "science", weight: 3, title: "快轮制陶与批量生产", summary: "陶轮使器皿壁厚均匀、可标准化计件生产。", detail: { background: "此前手工泥条盘筑产量低、器形不规整，难以支撑城市配给需求。", process: "两河与埃及遗址在前三千纪初普遍出现慢轮与快轮，器表留下平行旋纹；出土窑址与泥板记录显示按件计工的作坊分工。", impact: "标准器形便于以容量单位计粮、计油与计税，成为度量衡制度与手工业专业化的技术基础。", figures: ["不可考的轮制陶工"], place: "两河流域与尼罗河流域诸遗址", state: "苏美尔城邦", sources: ["《剑桥古代技术史》第1卷", "乌鲁克与阿拜多斯陶器类型学研究"], tags: ["陶轮", "手工业", "标准化"] }, related: [] },
  { id: "world--b3000--a01", track: "world", year: -3000, yearApprox: true, dim: "art", weight: 3, title: "纳尔迈调色板雕刻", summary: "双面石灰岩浮雕以图像宣告王权与统一叙事。", detail: { background: "早期国家需要用可视图像向识字率极低的群体宣示王权合法性。", process: "调色板一面为戴白冠的那尔迈持权击敌、鹞鹰赫拉荷系敌人鼻，另一面为戴红冠的阅兵行列与破坏中的城墙，顶部牛耳与双蛇标记具宗教含义。", impact: "它确立了法老姿态、王冠二分法与纪念性浮雕语汇，此后三千年埃及艺术程式由此定型。", figures: ["那尔迈"], place: "上埃及希拉孔波利斯（今埃及凯姆），藏开罗博物馆", state: "古埃及", sources: ["开罗博物馆馆藏记录", "《剑桥古代史》第1卷"], tags: ["调色板", "浮雕", "王权图像"] }, related: [] },
  { id: "world--b2950--p01", track: "world", year: -2950, yearApprox: true, dim: "politics", weight: 3, title: "第一王朝定都孟菲斯", summary: "白墙都城控扼谷地与三角洲接缝，王权制度化。", detail: { background: "统一后的王室需在南北之间建立枢纽，以控制灌溉与税粮转运。", process: "传统记载法老在三角洲顶点建「白墙」（因斯·赫特·克拉尼），即孟菲斯，并设王陵于阿拜多斯、行政中心于北方；塞格登等王名见于泥封与王表。", impact: "孟菲斯成为埃及长期首都，其「两土地」观念与王室丧葬制度构成国家认同的核心装置。", figures: ["阿哈", "登"], place: "孟菲斯（今埃及米特·拉希纳）", state: "古埃及", sources: ["《剑桥古代史》第1卷", "阿拜多斯第一王朝墓葬发掘报告"], tags: ["孟菲斯", "定都", "早王朝"] }, related: [] },
  { id: "world--b2900--i01", track: "world", year: -2900, yearApprox: true, dim: "institution", weight: 3, title: "苏美尔「恩」与「恩西」官职", summary: "城邦出现神权长官与总督两级行政职位。", detail: { background: "早期城邦由祭司会议与民众会共同决策，需专职官员管理灌溉与祭祀。", process: "泥板与王表显示乌鲁克等城有「恩」（祭司王）与「恩西」（城邦长官），后者负责运河、城墙与诉讼；拉格什文献中恩西兼掌神庙财产与徭役征发。", impact: "这两类职务是后世「卢伽尔」（王）与地方总督的前身，标志苏美尔政治由氏族会议向官僚治理过渡。", figures: ["不可考的恩西"], place: "苏美尔诸城邦（今伊拉克南部）", state: "苏美尔城邦", sources: ["克雷默《苏美尔：历史始于苏美尔》", "拉格什早期泥板文书"], tags: ["官制", "城邦", "苏美尔"] }, related: [] },
  { id: "world--b2900--s01", track: "world", year: -2900, yearApprox: true, dim: "science", weight: 3, title: "六十进制与算表泥板", summary: "苏美尔以60与10进制混合计田、计粮、计时。", detail: { background: "灌溉土方量与配给量计算需要可通分的整数体系。", process: "早王朝泥板已用 1、10、60、600、3600 五级单位表示面积与容量；后世巴比伦数学在此上发展出平方、倒数与二次方程算表。", impact: "60进制经希腊与伊斯兰传入欧洲，遗留于今日时的分秒与圆周360度，是古代计量影响最深的一例。", figures: ["不可考的书吏"], place: "两河流域南部", state: "苏美尔城邦", sources: ["诺伊格鲍尔《巴比伦数学与起源》，1935", "《剑桥古代技术史》第1卷"], tags: ["六十进制", "数学", "计量"] }, related: [] },
  { id: "world--b2900--d01", track: "world", year: -2900, yearApprox: true, dim: "disaster", weight: 3, title: "舒鲁帕克洪水沉积层", summary: "两河遗址的厚层淤泥成为大洪水传说考古线索。", detail: { background: "幼发拉底河春季融雪与暴雨可致下游城邑被淹，河床常迁移。", process: "马基在舒鲁帕克（今法拉）探到厚约2—3米无文物的洪水黏土层，年代约前2900，同期基什、乌鲁克亦有局部水泛层。", impact: "学界多视其为苏美尔洪水神话与《吉尔伽美什》乌特纳匹什提姆故事的自然原型之一，但非全流域同时事件。", figures: ["马基（考古学家）"], place: "苏美尔舒鲁帕克（今伊拉克法拉）", state: "苏美尔城邦", sources: ["魏登纳《苏美尔洪水层》（《近东研究杂志》1929）", "克雷默《历史始于苏美尔》"], tags: ["洪水", "考古层位", "神话原型"] }, related: [] },
  { id: "world--b2900--e01", track: "world", year: -2900, yearApprox: true, dim: "economy", weight: 3, title: "尼罗河水位计与王室粮仓", summary: "以水位观测预估产量，建立税赋与赈济的基础。", detail: { background: "埃及农业完全依赖每年七月至十月的泛滥，需预测水位以定税额。", process: "象岛、孟菲斯等地设「尼罗米特」刻度水位，王室在诸州建仓，泥封与账板记录入仓大麦数量与差役名籍。", impact: "水位—产量—税额的联动使国家得以丰年储粮、歉年减赋，构成法老「赈民」合法性的经济支点。", figures: ["不可考的仓库书吏"], place: "孟菲斯与象岛（今阿斯旺）", state: "古埃及", sources: ["《剑桥古代史》第1卷", "卡尔纳克与象岛尼罗米特铭文"], tags: ["尼罗河", "粮仓", "税制"] }, related: [] },
  { id: "world--b2850--s01", track: "world", year: -2850, yearApprox: true, dim: "science", weight: 4, title: "埃及太阳历确立", summary: "365日十二月的民用历与天狼星偕日升并行。", detail: { background: "泛滥周期与天狼星（索普代特）晨见基本同步，为定历提供天文锚。", process: "古王国通行民用历：三季（泛滥、播种、收获）各四月、每月30日加年末5日「闰日」，另设十天一旬的周制；其与回归年每4年差约1日。", impact: "该历经罗马儒略改革沿袭为今日公历骨架，是人类最持久的时间制度之一。", figures: ["不可考的神庙天文祭司"], place: "尼罗河流域（今埃及）", state: "古埃及", sources: ["帕克《古代埃及天文历法》（1978）", "《剑桥古代史》第1卷"], tags: ["太阳历", "天狼星", "历法"] }, related: [] },
  { id: "world--b2800--s01", track: "world", year: -2800, yearApprox: true, dim: "science", weight: 3, title: "失蜡法精密铸造", summary: "以蜡模换陶范，铸出空心铜像与复合器件。", detail: { background: "分范块铸难以做出镂空与弯曲部件，宗教器物对形制要求高。", process: "两河与埃及遗址出土带芯范痕迹的铜件、蜡质残留与铸造废料，年代约前四千纪末至前三千纪；其后该方法扩散至爱琴海与印度河。", impact: "失蜡法使雕塑、镜柄、武器与神器可整体成形，是古代冶金史上影响最远的工艺传播之一。", figures: ["不可考的铜匠"], place: "两河流域与尼罗河流域", state: "苏美尔城邦", sources: ["《剑桥古代技术史》第1卷", "大英博物馆古代冶金技术图录"], tags: ["失蜡法", "冶金", "工艺传播"] }, related: [] },
  { id: "world--b2800--i01", track: "world", year: -2800, yearApprox: true, dim: "institution", weight: 3, title: "印度河的砖模数与度量衡", summary: "哈拉帕诸城以固定砖比与标尺跨城统一工程。", detail: { background: "无宫殿王陵的印度河城市却呈现高度一致的规划，暗示共同规范。", process: "遗址标准砖长宽高比约4:2:1，出土燧石与贝壳尺、重量器以约13.6克为单位呈二进制级差（1、2、5、10、20、50、100、200），分布远达多尔维拉与美索不达米亚。", impact: "标准化度量支持跨城贸易、税赋与工程协作，是判定印度河存在统一行政体系的关键物证。", figures: ["不可考的测量匠"], place: "摩亨佐-达罗、哈拉帕、多尔维拉（今巴基斯坦与印度西部）", state: "印度河文明", sources: ["马凯《摩亨佐-达罗发掘报告》", "肯沃西《印度河文明》（2008）"], tags: ["度量衡", "砖模数", "哈拉帕"] }, related: [] },
  { id: "world--b2800--e01", track: "world", year: -2800, yearApprox: true, dim: "economy", weight: 3, title: "埃及州制与田亩税册", summary: "全国划入数十州，按田亩与牲畜清点征税。", detail: { background: "统一后需把村社纳入国家财政，王室遂定期清点土地与人口。", process: "纸草与石刻名单显示约40余「斯帕特」（州），每州遣「税监」；帕勒莫石碑记录每年或隔年的「计数」（人口与牲畜清点）与贡赋数额。", impact: "清点—登记—征调成为国家常规，为金字塔等巨型工程提供稳定的粮食与人力来源。", figures: ["不可考的税监"], place: "上下埃及诸州（今埃及尼罗河谷）", state: "古埃及", sources: ["《剑桥古代史》第1卷", "帕勒莫石碑（都灵、巴勒莫藏片）"], tags: ["州制", "税册", "清点"] }, related: [] },
  { id: "world--b2750--e01", track: "world", year: -2750, yearApprox: true, dim: "economy", weight: 3, title: "塞浦路斯铜与东地中海贸易", summary: "岛上富铜矿连爱琴海、安纳托利亚与埃及为一线。", detail: { background: "青铜生产需要铜与锡，东地中海最易开采的铜在塞浦路斯。", process: "前三千纪中叶起，克拉夫提等遗址出现大规模冶炼渣与进口陶，货物经黎凡特港与埃及三角洲中转，金属锭与贵金属、粮食、手工业品互换。", impact: "这条以金属为轴的贸易网奠定了此后两千年东地中海互相依存的经济格局，也放大了锡路中断时的系统性风险。", figures: ["不可考的航海商"], place: "塞浦路斯克拉夫提（今塞浦路斯岛）", state: "塞浦路斯诸聚落", sources: ["《剑桥古代史》第1卷", "东地中海青铜时代考古研究综述"], tags: ["铜贸易", "东地中海", "冶金经济"] }, related: [] },
  { id: "world--b2700--c01", track: "world", year: -2700, yearApprox: true, dim: "culture", weight: 3, title: "苏美尔王表的成文", summary: "以「王权自天而降」串联诸城与超长纪年。", detail: { background: "各城各自记王的名单需要整合为统一的历史叙事以服务霸权主张。", process: "现存抄本源于乌尔第三王朝至伊辛时期，但含更早传统：洪水前后两分，「某城为王，统治若干舍」，早期王在位以三万六千年计，末段转为可核对的历史王。", impact: "王表成为研究两河年代学的框架，也显示古代史学如何把政治合法性写成时间序列。", figures: ["不可考的王表编纂书吏"], place: "两河流域（抄本见于尼普尔、伊辛）", state: "苏美尔城邦", sources: ["克雷默《苏美尔王表》（1939）", "普里查德编《古代近东文献》"], tags: ["王表", "史学", "年代学"] }, related: [] },
  { id: "world--b2700--a01", track: "world", year: -2700, yearApprox: true, dim: "art", weight: 3, title: "巨石阵第一期环形工程", summary: "索尔兹伯里平原挖环形壕沟与56个奥布里洞。", detail: { background: "新石器晚期不列颠已有环形土堤与墓域传统，平原上葬礼与天文观测结合。", process: "碳十四测定的壕沟与「奥布里洞」属巨石阵第一阶段，约前3000—前2900年，本条按此段收录；其后二期立石、三期砂岩圈与三石塔渐次完成。", impact: "它证明在没有文字与金属工具的不列颠已能动员跨族群劳力，也成为研究史前社会层裂的关键遗址。", figures: ["不可考的史前工匠"], place: "不列颠索尔兹伯里平原（今英国威尔特郡）", state: "不列颠新石器社会", sources: ["英国遗产署巨石阵年代学综述", "帕克·皮尔逊《巨石阵》（2012）"], tags: ["巨石阵", "新石器", "公共工程"] }, related: [] },
  { id: "world--b2700--i01", track: "world", year: -2700, yearApprox: true, dim: "institution", weight: 3, title: "埃及维齐尔与双国库", summary: "宰相掌司法、仓库与工程，上下埃及各设财政。", detail: { background: "统一国家工程与税收激增，需要超越氏族贵族的专职行政首脑。", process: "古王国铭文出现「扎提」（维齐尔）头衔，负责王陵工程、法庭与档案；同时设「上下埃及国库」两大财政系统，由书吏分层管理。", impact: "这套以维齐尔—书吏—仓库为轴的官僚结构延续至托勒密时代，被视为人类最早成熟的文官制。", figures: ["梅图恩（维齐尔）"], place: "孟菲斯（今埃及米特·拉希纳）", state: "古埃及", sources: ["《剑桥古代史》第1卷", "梅图恩墓铭文释读"], tags: ["维齐尔", "官僚制", "古王国"] }, related: [] },
  { id: "world--b2680--a01", track: "world", year: -2680, yearApprox: true, dim: "art", weight: 5, title: "左塞尔阶梯金字塔落成", summary: "萨卡拉六级石构金字塔开巨型石造建筑先河。", detail: { background: "此前王陵为泥砖长形马斯塔巴墓，王权展示与永恒观念推动改用石材。", process: "第三王朝左塞尔在萨卡拉建六层阶梯塔，底约109×125米、高约60米，围以石灰岩围墙与假门庭院，属建筑群含祭司住宅与赛德节场。", impact: "它是已知最早的大型全石建筑，其模数化石材工艺与复合神庙布局直接影响此后吉萨金字塔群。", figures: ["左塞尔", "印和阗"], place: "萨卡拉（今埃及开罗南郊）", state: "古埃及", sources: ["《剑桥古代史》第1卷", "奎比尔《萨卡拉阶梯金字塔发掘报告》"], tags: ["阶梯金字塔", "石构建筑", "左塞尔"] }, related: [] },
  { id: "world--b2680--s01", track: "world", year: -2680, yearApprox: true, dim: "science", weight: 4, title: "巨石砌筑与贴面工艺", summary: "采石、运输、干砌与打磨形成成套石构技术。", detail: { background: "全石建筑要求解决开采、垂直运输与结构稳定三难题。", process: "图拉与阿斯旺采石场用木楔胀裂法取块，铜锯与石锤整形；斜坡道与木橇配合湿沙减阻，砌筑采用外倾芯体与石灰石贴面以分散荷载。", impact: "这套工艺使埃及掌握千年以上寿命的建筑形式，并输出至努比亚、黎凡特与爱琴海部分遗址。", figures: ["不可考的石匠监工"], place: "图拉采石场与萨卡拉工地（今埃及）", state: "古埃及", sources: ["《剑桥古代技术史》第1卷", "阿纳提《埃及建筑》"], tags: ["采石", "砌筑", "工程技术"] }, related: [] },
  { id: "world--b2680--f01", track: "world", year: -2680, yearApprox: true, dim: "figure", weight: 3, title: "印和阗：建筑师与医神", summary: "左塞尔宰相兼设计师，后神格化为智慧之神。", detail: { background: "古王国高级官员多兼祭司、法官与工程总监之职。", process: "萨卡拉一处石雕基座刻其姓名与数十个头衔；后世埃及人奉为医神与书吏守护神，希腊人以伊姆霍特斯之名比附阿斯克勒庇俄斯。", impact: "他是少数留下姓名的史前工程师，其神格化反映古埃及对技术专家的文化尊崇。", figures: ["印和阗", "左塞尔"], place: "萨卡拉与底比斯（今埃及）", state: "古埃及", sources: ["《剑桥古代史》第1卷", "底比斯格里夫纸草与雕像题记"], tags: ["印和阗", "建筑师", "神格化"] }, related: [] },
  { id: "world--b2650--s01", track: "world", year: -2650, yearApprox: true, dim: "science", weight: 4, title: "苏美尔犁与条播器", summary: "木犁配铜犁铧与漏斗，实现开沟播种一体。", detail: { background: "大麦小麦条播可省种并利于灌溉渠布设，人力撒播损耗大。", process: "泥板《农人手册》（约前2400年抄本含更早传统）规定耕前修渠、以牛拉犁三遍、犁后以「希姆亨」（漏斗犁）随行播种，并给公牛戴口衔防啄食。", impact: "条播使单位面积产量与可耕面积同步上升，是两河农业集约化与人口增长的技术前提。", figures: ["不可考的农人", "抄写《农人手册》的书吏"], place: "苏美尔与阿卡德农区（今伊拉克南部）", state: "苏美尔城邦", sources: ["法尔克斯《苏美尔农人手册》（1947）", "克雷默《历史始于苏美尔》"], tags: ["犁", "条播", "农书"] }, related: [] },
  { id: "world--b2650--e01", track: "world", year: -2650, yearApprox: true, dim: "economy", weight: 4, title: "灌溉扩张与土壤盐碱化", summary: "渠网推高产量，长期灌溉却使南部土地盐渍化。", detail: { background: "两河南部雨量不足，全靠运河输水；地下水位高、蒸发强。", process: "前两千纪泥板中小麦占比下降、大麦（耐盐）上升；学界据土壤样品与文献认为含盐量累积导致乌尔、尼普尔一带农业衰退，考古层亦见弃耕。", impact: "这被广泛视为生态压力削弱苏美尔经济、使政治重心北移阿卡德与巴比伦的结构性因素之一。", figures: ["不可考的渠监"], place: "苏美尔南部灌溉区（今伊拉克纳西里耶以北）", state: "苏美尔城邦", sources: ["亚当斯《苏美尔南部土地利用变迁》（1960）", "范德米尔洛普《古代近东》"], tags: ["灌溉", "盐碱化", "生态"] }, related: [] },
  { id: "world--b2620--s01", track: "world", year: -2620, yearApprox: true, dim: "science", weight: 5, title: "印度河城市的排水系统", summary: "摩亨佐-达罗以砖砌暗渠与住户厕浴排走污水。", detail: { background: "密集砖房与高人口需要处理生活用水与雨水，否则疫病易发。", process: "住宅多设浴台与渗井，废水经陶管或砖沟汇入街道下的拱顶主渠，渠道设检查井与沉泥坑，主渠通向城外排放点；下城另有垃圾倾倒与冲洗设施。", impact: "这在青铜时代世界独一无二，被视为城市规划与公共卫生观念的最早大规模实践。", figures: ["不可考的城市营造者"], place: "摩亨佐-达罗（今巴基斯坦信德省）", state: "印度河文明", sources: ["马凯《摩亨佐-达罗发掘报告》", "肯沃西《印度河文明》（2008）"], tags: ["排水", "城市规划", "公共卫生"] }, related: [] },
  { id: "world--b2620--e01", track: "world", year: -2620, yearApprox: true, dim: "economy", weight: 4, title: "哈拉帕的棉纺与粮仓", summary: "世界上最早的棉花纺织与大型公共仓储并见于此。", detail: { background: "印度河平原宜棉，港口与内河运道支持集散。", process: "摩亨佐-达罗出土带棉纤维痕迹的银罐与纺轮，拉基加希有约2000年前的棉籽；多尔维拉与哈拉帕的「粮仓」基座与装货平台显示集中储粮与翻晒制度。", impact: "棉纺织此后长期成为南亚对外的标志性商品，罗马与阿拉伯商人皆高价购入。", figures: ["不可考的纺工"], place: "摩亨佐-达罗、多尔维拉（今巴基斯坦古吉拉特与信德）", state: "印度河文明", sources: ["马凯《摩亨佐-达罗发掘报告》", "《印度史》第1卷（剑桥印度史分卷）"], tags: ["棉花", "纺织", "仓储"] }, related: [] },
  { id: "world--b2600--m01", track: "world", year: -2600, yearApprox: true, dim: "military", weight: 3, title: "拉格什与温马边界战争", summary: "为争夺古埃丁纳平原，两城进行早期记录之战。", detail: { background: "拉格什与温马相邻，同争灌溉渠系与牧场，界桩争端反复。", process: "恩内图姆与恩安纳图姆铭文追述温马王乌科（「篡改界桩者」）砍毁拉格什界桩，拉格什以步兵方阵获胜，此后百年间战争延续，史称「鸟巢之役」。", impact: "这是现存最早有双方铭文可考的城邦边界战争，反映灌溉农业社会中水土资源的决定性地位。", figures: ["恩安纳图姆", "乌科"], place: "拉格什与温马之间古埃丁纳平原（今伊拉克泰勒洛赫）", state: "苏美尔城邦", sources: ["普里查德编《古代近东文献》拉格什铭文", "克雷默《历史始于苏美尔》"], tags: ["边界战争", "拉格什", "铭文"] }, related: [] },
  { id: "world--b2600--p01", track: "world", year: -2600, yearApprox: true, dim: "politics", weight: 2, title: "基什与乌鲁克的霸权轮替", summary: "两城反复争夺苏美尔领导权，形成霸主传统。", detail: { background: "基什控扼幼发拉底与底格里斯间最窄处，谁得之可收过所之利。", process: "泥板与史诗传统记基什王恩美巴拉格西「下海」远征、其子阿伽与乌鲁克的吉尔伽美什冲突；考古显示基什在早王朝三期为最大城市之一。", impact: "「基什之王」成为霸权称号，后世萨尔贡与汉谟拉比沿用，体现苏美尔政治中的等级化城邦秩序。", figures: ["恩美巴拉格西", "阿伽", "吉尔伽美什（传说王）"], place: "基什与乌鲁克（今伊拉克塔拉比与瓦尔卡）", state: "苏美尔城邦", sources: ["《吉尔伽美什与阿伽》泥板（牛津大学藏）", "范德米尔洛普《古代近东》"], tags: ["霸权", "基什", "史诗"] }, related: [] },
  { id: "world--b2560--a01", track: "world", year: -2560, yearApprox: true, dim: "art", weight: 3, title: "卡夫拉金字塔与狮身人面像", summary: "吉萨第二高塔与其谷庙、巨石人像构成一体规划。", detail: { background: "第四王朝王室在吉萨高原连续建塔，共享采石场与堤道系统。", process: "卡夫拉塔原高约143米，顶端留贴面石灰岩；其堤道通谷庙，庙旁巨像以基岩就地雕成，学界多认为人像面部按王室肖像改造、年代归属仍有争议。", impact: "塔庙—堤道—河谷庙的三件套成为埃及丧葬建筑标准格局，巨像亦成王权与太阳神崇拜的象征符号。", figures: ["卡夫拉"], place: "吉萨高原（今埃及开罗郊外）", state: "古埃及", sources: ["《剑桥古代史》第1卷", "莱纳《吉萨的失落者》考古报告"], tags: ["吉萨", "狮身人面像", "丧葬建筑"] }, related: [] },
  { id: "world--b2560--s01", track: "world", year: -2560, yearApprox: true, dim: "science", weight: 5, title: "胡夫大金字塔的测量工程", summary: "约230万块石料按51度半坡度与正北定向建成。", detail: { background: "第四王朝集中全国粮仓与工匠村资源，为法老建造永恒居所。", process: "底边长约230米、原高约146米，四边方位偏差仅数角分；据考古推测以星象定北、以水槽或晨昏影定水平，斜坡道、木橇与湿沙运输配合，工期约20年。", impact: "其精度与规模成为古代工程测量技术的标杆，也是国家动员、后勤与计量能力的集中展示。", figures: ["胡夫", "赫米乌努（相传设计者）"], place: "吉萨（今埃及开罗郊外）", state: "古埃及", sources: ["《剑桥古代技术史》第1卷", "莱纳《探密金字塔》（1997）"], tags: ["大金字塔", "测量", "工程"] }, related: [] },
  { id: "world--b2560--e01", track: "world", year: -2560, yearApprox: true, dim: "economy", weight: 3, title: "金字塔工匠村的配给制", summary: "吉萨工地以面包、啤酒、鱼与牛骨按工班发放口粮。", detail: { background: "长年工程需养活数千常驻工匠，靠王室田庄与庄园贡赋供给。", process: "吉瓦瓦「失落者之城」出土面包房、鱼骨与牛肩胛骨记录，瓦迪·杰尔夫纸草记石灰岩由图拉经水路运至工地，按「工班—分队」组织，以日计口粮。", impact: "这批账料修正了「奴隶建造」的旧说，显示金字塔工程本质是国家主导的再分配经济运作。", figures: ["梅尔勒（运输队书吏）"], place: "吉瓦瓦与瓦迪·杰尔夫（今埃及开罗西南）", state: "古埃及", sources: ["莱纳《吉萨的失落者》", "《瓦迪·杰尔夫纸草》释读（2013）"], tags: ["徭役", "口粮配给", "工匠村"] }, related: [] },
  { id: "world--b2550--s01", track: "world", year: -2550, yearApprox: true, dim: "science", weight: 3, title: "印度河的犁耕稻麦农业", summary: "犁沟遗迹与稻田证据显示集约化耕作已成型。", detail: { background: "印度河平原兼具冬季小麦大麦与夏季稻，需不同水管理。", process: "卡兰班与洛索尔（古吉拉特）等遗址发现交叉犁沟、水稻小穗轴与灌溉渠，年代属印度河成熟期前段，约前2600—前2000年，本条按此区间收录。", impact: "稻麦两熟与犁耕为高密度城市人口提供口粮，并使牛耕与农具形制在此后数千年南亚基本定型。", figures: ["不可考的耕农"], place: "卡兰班、洛索尔（今印度拉贾斯坦与古吉拉特）", state: "印度河文明", sources: ["沙尔马《卡兰班发掘简报》", "印度考古调查局洛索尔报告"], tags: ["犁耕", "稻作", "农业"] }, related: [] },
  { id: "world--b2550--c01", track: "world", year: -2550, yearApprox: true, dim: "culture", weight: 3, title: "印度河印章与未解文字", summary: "方印刻短铭与神兽，至今未能释读其语言。", detail: { background: "印章用于封缄货物与身份标识，铭文平均仅四五符。", process: "已收集印章数千枚，多为滑石或皂石，正面刻独角兽、牛、瑜伽坐姿神等，背面有系钮；符号约400余个，铭文长度与结构使释读与语言归属至今无共识。", impact: "文字未破译限制了印度河政治与社会研究，也使其文明性质长期成为学界争论焦点。", figures: ["不可考的刻印匠"], place: "哈拉帕文化分布区（今巴基斯坦与印度西北）", state: "印度河文明", sources: ["帕波拉《印度河文字》（2015）", "肯沃西《印度河文明》"], tags: ["印章文字", "未破译", "哈拉帕"] }, related: [] },
  { id: "world--b2550--x01", track: "world", year: -2550, yearApprox: true, dim: "explore", weight: 3, title: "印度河船坞与海湾航路", summary: "洛索尔潮汐船坞连通南亚与波斯湾贸易。", detail: { background: "两河文献提到来自「麦勒哈」的玛瑙、象牙与乌木，一般认为指印度河地区。", process: "洛索尔（今印度古吉拉特）建有以石膏砌壁的梯形船坞与入港航道，年代约前2400—前1900，本条按成熟期收录；同时期出土印度河珠饰见于巴林（迪尔蒙）与乌尔。", impact: "该航路证明前两千纪已有跨海制度化贸易，为后世印度洋季风商网奠定节点与经验。", figures: ["不可考的领航者"], place: "洛索尔（今印度坎贝湾岸）", state: "印度河文明", sources: ["罗伊《洛索尔发掘报告》", "《剑桥印度史》第1卷"], tags: ["船坞", "海湾航路", "远程贸易"] }, related: [] },
  { id: "world--b2500--c01", track: "world", year: -2500, yearApprox: true, dim: "culture", weight: 3, title: "金字塔铭文与奥西里斯信仰", summary: "法老葬仪咒语刻于塔内壁，构成最早宗教文献。", detail: { background: "王权与奥西里斯复活神话结合，需要标准化的仪式文本。", process: "乌纳斯塔（约前2375）内壁首见完整「金字塔铭文」，但佩皮一世等更早塔中残句显示文本来源可上溯古王国中期，本条按早期形态收录；抄本含上升天梯、星辰引导等语。", impact: "这些咒语经棺文、亡灵书一路传承至托勒密时代，是埃及神学与来世观的根本文献。", figures: ["乌纳斯", "佩皮一世"], place: "萨卡拉与阿布斯伊尔（今埃及）", state: "古埃及", sources: ["普里查德编《古代近东文献》金字塔铭文选", "法赫尔巴赫《金字塔文本》"], tags: ["金字塔铭文", "奥西里斯", "来世观"] }, related: [] },
  { id: "world--b2500--s01", track: "world", year: -2500, yearApprox: true, dim: "science", weight: 3, title: "日本绳文陶器与定居采集", summary: "带绳纹压印的陶器支撑列岛半定居聚落生活。", detail: { background: "更新世末后气候变暖，本州与北海道森林海岸资源稳定，无需农业亦可定居。", process: "绳文早期至中期陶器以泥条盘筑、湿绳压纹为特征，出土深钵、土器与「板付」式炉址；三内丸山等遗址显示栗树管理、漆器与大型竖穴群。", impact: "这是世界罕见的「无农业定居」文明路径，其陶器类型学构成东亚年代学的重要标尺。", figures: ["不可考的绳文陶工"], place: "本州北部三内丸山等遗址（今日本青森县）", state: "日本绳文文化", sources: ["日本《绳文文化研究》系列报告", "索恩《日本前史》（1997）"], tags: ["绳文", "陶器", "半定居"] }, related: [] },
  { id: "world--b2500--a01", track: "world", year: -2500, yearApprox: true, dim: "art", weight: 4, title: "卡拉尔土墩礼仪中心", summary: "秘鲁苏佩河谷出现美洲最早的大型公共建筑。", detail: { background: "沿海渔捞与河谷棉、瓜类交换支撑定居，但无陶器与谷物主导。", process: "卡拉尔（今秘鲁利马以北）建六座平台土墩，最大底面积约170×170米、高约18米，配下沉式圆形广场、祭坛与焚烧区，年代约前2600—前2000。", impact: "它证明美洲在陶器与农业之前即已产生复杂社会与国家雏形，挑战旧有的文明演进时间表。", figures: ["沙佩（考古学家，1905年首报）"], place: "卡拉尔（今秘鲁上苏佩河谷）", state: "小北区文明", sources: ["哈斯勒等《卡拉尔》（2004）", "《科学》杂志卡拉尔碳十四测年论文"], tags: ["卡拉尔", "美洲文明", "礼仪建筑"] }, related: [] },
  { id: "world--b2500--i01", track: "world", year: -2500, yearApprox: true, dim: "institution", weight: 3, title: "埃兰城邦与线形埃兰文字", summary: "伊朗高原西南端形成与苏美尔并立的政治体。", detail: { background: "苏萨地处平原、安善居山地，两地合并构成埃兰二元王权。", process: "约前3100年苏萨出现原始埃兰文字，前2300—前2200年间「线形埃兰文字」通行，本条按此制度期收录；同时期埃兰诸王与两河城邦结盟或作战。", impact: "埃兰长期作为两河政治的第三方角色，其文字与行政制度影响波斯，是理解伊朗起源的关键一环。", figures: ["希姆提-兰什（传说中的安善与苏萨之王）"], place: "苏萨与安善（今伊朗胡齐斯坦与法尔斯）", state: "埃兰", sources: ["《剑桥伊朗史》第2卷", "达勒《原始埃兰文字》"], tags: ["埃兰", "线形文字", "苏萨"] }, related: [] },
  { id: "world--b2450--a01", track: "world", year: -2450, yearApprox: true, dim: "art", weight: 2, title: "乌尔王陵的里拉琴与镶嵌", summary: "牛首竖琴以金、青金石与贝壳展示丧葬工艺。", detail: { background: "第一王朝乌尔王陵以大量随葬与「殉葬坑」闻名，反映王室礼制。", process: "出土约前2600—前2400年的里拉琴，音箱嵌贝壳与石灰岩马赛克，牛首以金箔包裹、青金石眼与红石嵌；同时有「公羊在灌丛」金饰与滚筒印章。", impact: "这些器物确立了苏美尔宫廷工艺的水准标尺，也提供了研究早期乐器与声学形态的实物。", figures: ["吴利（考古学家）"], place: "乌尔王陵（今伊拉克泰勒穆盖耶尔）", state: "苏美尔城邦", sources: ["吴利《乌尔王陵发掘报告》（1934）", "大英博物馆乌尔藏品目录"], tags: ["里拉琴", "乌尔王陵", "镶嵌工艺"] }, related: [] },
  { id: "world--b2450--s01", track: "world", year: -2450, yearApprox: true, dim: "science", weight: 3, title: "滚筒印章与封泥凭证", summary: "以滚刻石印滚动成像，兼作签名与货物封识。", detail: { background: "长途贸易与仓库管理要求可核验且防伪的身份标记。", process: "前四千纪末出现于两河北部，前三千纪在苏美尔普及，石质与陶质印章刻神话与宴饮场景，滚动于湿泥留下连续图像；罐口、门闩与文书皆以封泥加印。", impact: "它是古代近东的「签名」技术，使契约、税单与货运责任可追溯，成为法律行政体系的重要组件。", figures: ["不可考的刻印匠"], place: "两河流域与叙利亚（今伊拉克、叙利亚）", state: "苏美尔城邦", sources: ["普里查德编《古代近东文献》", "大英博物馆滚筒印章图录"], tags: ["滚筒印章", "封泥", "凭证"] }, related: [] },
  { id: "world--b2400--s01", track: "world", year: -2400, yearApprox: true, dim: "science", weight: 5, title: "锡青铜合金成为主流", summary: "铜加锡冶炼使武器与工具硬度可批量控制。", detail: { background: "纯铜软而易钝，砷铜有毒且不稳定；含锡10%左右的合金兼具硬度与韧性。", process: "前3000年代后半期两河、埃及与爱琴海出土器物锡含量明显上升，锻打与退火工序标准化；贸易网为获取阿富汗与安纳托利亚锡矿而扩张。", impact: "青铜化重塑军事平衡、农业工具与远程贸易结构，学界多视其为前三千纪末最关键的产业革命。", figures: ["不可考的冶金匠"], place: "东地中海—两河—伊朗高原冶铸区", state: "苏美尔城邦", sources: ["《剑桥古代技术史》第1卷", "穆尔韦《青铜时代的冶金》"], tags: ["青铜", "合金", "冶金"] }, related: [] },
  { id: "world--b2400--p01", track: "world", year: -2400, yearApprox: true, dim: "politics", weight: 2, title: "埃兰与苏美尔的争战同盟", summary: "伊朗高原政权反复介入两河城邦政治。", detail: { background: "埃兰控制通往伊朗高原的山口与畜群，与苏美尔城邦利益冲突。", process: "铭文与年鉴记恩美沙拉及西乌姆时代埃兰军深入两河、被乌尔纳姆反击，乌尔第三王朝设「喜马舍基」防区抵御埃兰与古提人。", impact: "埃兰由此成为两河南部长期安全隐患，最终参与推翻乌尔第三王朝，改变古代近东权力版图。", figures: ["恩美沙拉", "乌尔纳姆"], place: "苏萨与两河南部（今伊朗与伊拉克）", state: "埃兰", sources: ["《剑桥伊朗史》第2卷", "乌尔第三王朝王室纪年表"], tags: ["埃兰", "外交", "战争"] }, related: [] },
  { id: "world--b2370--s01", track: "world", year: -2370, yearApprox: true, dim: "science", weight: 3, title: "安纳托利亚早期块炼铁", summary: "还原法炼出海绵铁，铁器由贵重礼器渐趋实用。", detail: { background: "铁的熔点高且需反复锻打去渣，技术门槛远高于铜。", process: "阿拉贾霍尤克与埃及、两河部分遗址出土约前3000—前2000年的块炼铁珠、匕首与礼物级铁器；赫梯诸国此后垄断技术，铭文以「好铁」记交易。", impact: "铁器在数百年后随青铜体系崩溃而普及，硬度与原料易得性彻底改变了农业与战争的成本结构。", figures: ["不可考的冶铁匠"], place: "安纳托利亚中部（今土耳其约兹加特）", state: "安纳托利亚诸城邦", sources: ["穆尔韦《铁器时代的起源》", "《剑桥古代史》第1卷"], tags: ["块炼铁", "赫梯", "冶金"] }, related: [] },
  { id: "world--b2350--p01", track: "world", year: -2350, yearApprox: true, dim: "politics", weight: 3, title: "卢加尔扎格西统一苏美尔", summary: "温马末代霸主短暂整合诸城，为阿卡德所取代。", detail: { background: "拉格什与温马百年边界战削弱南部诸城，祭司贵族与平民矛盾激化。", process: "卢加尔扎格西先灭阿达尔拉马、再克尼普尔，取「苏美尔之王」号并兴修运河；约前2334年（学界推定）在乌尔被萨尔贡击败，被剥发戴锁至尼普尔。", impact: "他的失败使苏美尔城邦体系首次被闪米特人的地域帝国取代，成为两河政治史上的分水岭。", figures: ["卢加尔扎格西", "萨尔贡"], place: "温马与尼普尔（今伊拉克）", state: "苏美尔城邦", sources: ["范德米尔洛普《萨尔贡与纳拉姆-辛：古代美索不达米亚文献》", "萨尔贡年名表"], tags: ["温马", "苏美尔霸权", "阿卡德征服"] }, related: [] },
  { id: "world--b2334--p01", track: "world", year: -2334, yearApprox: true, dim: "politics", weight: 5, title: "萨尔贡建立阿卡德王朝", summary: "闪米特人首次并两河与远疆为一统帝国。", detail: { background: "传说萨尔贡为尼普尔园丁之子，任杯膳官时夺权于基什王乌尔扎巴巴。", process: "约前2334年（学界推定年表）起，他连败卢加尔扎格西联盟，控制苏美尔、埃兰边缘、叙利亚与安纳托利亚部分，建都阿卡德，设常驻军「日在殿同食」五百四十人。", impact: "他创设的行省、统一度量与官方图像范式成为此后所有西亚帝国的模板，「万王之王」观念由此发端。", figures: ["萨尔贡", "卢加尔扎格西"], place: "阿卡德城与两河全境（今伊拉克巴格达以南）", state: "阿卡德帝国", sources: ["《萨尔贡出生神话》亚述抄本（《古代近东文献》）", "范德米尔洛普《萨尔贡与纳拉姆-辛》"], tags: ["阿卡德", "帝国", "萨尔贡"] }, related: [] },
  { id: "world--b2320--m01", track: "world", year: -2320, yearApprox: true, dim: "military", weight: 3, title: "萨尔贡东征埃兰与「银之地」", summary: "阿卡德军越扎格罗斯，收高原与矿路入其势力。", detail: { background: "埃兰支持苏美尔反阿卡德联盟，且控制金属下运的通道。", process: "萨尔贡铭文记其征帕拉苏姆、希马舍基与安善，击败埃兰军并焚其城；另记「三日行军至银之地」，以掠夺铜、银与石料充实王库。", impact: "此次东征把两河帝国的边界推到伊朗高原，形成此后波斯与塞琉古都要争夺的山口体系。", figures: ["萨尔贡", "埃兰王卢丁"], place: "埃兰与扎格罗斯山口（今伊朗胡齐斯坦）", state: "阿卡德帝国", sources: ["萨尔贡铭文与年名表（《古代近东文献》选译）", "《剑桥伊朗史》第2卷"], tags: ["东征", "埃兰", "金属路"] }, related: [] },
  { id: "world--b2300--e01", track: "world", year: -2300, yearApprox: true, dim: "economy", weight: 4, title: "帝国统一度量与仓储驿站", summary: "阿卡德改两河异构量制为一套国家标准。", detail: { background: "诸城各自量制使跨城纳税与军粮调拨困难。", process: "萨尔贡铭文言「以统一的王制秤量代替诸城各自度量」；考古显示以「米纳」（约504克）与「舍克尔」为核心的银本位与容量单位并行，并在各省设王室仓库与驿站，向神庙地产课征。", impact: "统一量制与仓储—驿站体系大幅降低交易与征税成本，成为帝国财政得以支撑长期征战的基础。", figures: ["萨尔贡"], place: "阿卡德帝国诸省（今伊拉克与叙利亚）", state: "阿卡德帝国", sources: ["范德米尔洛普《古代近东：公元前3000—前323年》", "《剑桥古代史》第1卷第2分册"], tags: ["度量衡", "财政", "驿站"] }, related: [] },
  { id: "world--b2300--i01", track: "world", year: -2300, yearApprox: true, dim: "institution", weight: 4, title: "阿卡德行省总督与常备军", summary: "以王任官员取代城邦自治，并设职业军人。", detail: { background: "城邦恩西与祭司集团易结成反叛同盟，需以外来代理人压制。", process: "阿卡德文献中「沙基那库姆」（军事总督）取代或监督旧恩西，接管神庙土地与徭役征发；另以常备军「日在殿同食」五百四十人为核心，战时征调民兵。", impact: "这套「中央派官+职业军」的模式是已知最早的行省制雏形，为大流士与罗马的省制提供先例。", figures: ["萨尔贡", "不可考的沙基那库姆"], place: "阿卡德帝国诸省（今伊拉克、叙利亚）", state: "阿卡德帝国", sources: ["《剑桥古代史》第1卷第2分册", "范德米尔洛普《古代近东》"], tags: ["行省制", "常备军", "帝国行政"] }, related: [] },
  { id: "world--b2270--p01", track: "world", year: -2270, yearApprox: true, dim: "politics", weight: 2, title: "里穆什与马尼什图苏的统治危机", summary: "阿卡德第二代诸王面临全国叛乱与远征镇压。", detail: { background: "萨尔贡以征服组建的帝国缺少制度化继承规则，王位更易即触发诸城抗税。", process: "里穆什铭文自述逐城击破乌尔、拉格什、卡扎卢等叛乱联盟，砍伐果树、掘毁水渠；马尼什图苏则远征南方海岸与「乌阿布拉姆」诸岛。", impact: "两位国王的镇压虽暂时保全帝国，却暴露了早期帝国对君主个人军力的依赖，为纳拉姆-辛时代的更大动荡埋下伏笔。", figures: ["里穆什", "马尼什图苏"], place: "阿卡德帝国南方诸城（今伊拉克南部）", state: "阿卡德帝国", sources: ["里穆什与马尼什图苏王室铭文（《古代近东文献》选译）", "范德米尔洛普《萨尔贡与纳拉姆-辛》"], tags: ["叛乱", "继承危机", "阿卡德"] }, related: [] },
  { id: "world--b2254--p01", track: "world", year: -2254, yearApprox: true, dim: "politics", weight: 4, title: "纳拉姆-辛自称四方之王", summary: "阿卡德国王自加神格，王权理论为之大变。", detail: { background: "纳拉姆-辛以铁腕平定萨尔贡之后最大规模叛乱，需要超越城邦神官体系的新合法性。", process: "他取「阿卡德之王」与「四方之王」号，自称「神纳拉姆-辛」，名前加神性限定符，并在文献中记录以沸水、火焚等极刑处置叛乱者。", impact: "君主在生前自居为神，是西亚政治神学的第一次重大转向，直接影响赫梯、埃及法老与波斯「王权神授」的传统。", figures: ["纳拉姆-辛"], place: "阿卡德城（今伊拉克巴格达附近）", state: "阿卡德帝国", sources: ["范德米尔洛普《萨尔贡与纳拉姆-辛》", "《剑桥古代史》第1卷第2分册"], tags: ["神化王权", "四方之王", "阿卡德"] }, related: [] },
  { id: "world--b2250--a01", track: "world", year: -2250, yearApprox: true, dim: "art", weight: 3, title: "纳拉姆-辛胜利石碑", summary: "斜构构图与神星光环成为帝国宣传图像的经典。", detail: { background: "阿卡德宫廷需要新的视觉语言表达征服与王者神性。", process: "闪长岩浮雕（碎块藏卢浮宫）表现纳拉姆-辛登高踏敌、士兵以投掷矛与斧攻城，其头部上方有六芒星符号，代表神格。", impact: "该作的对角线构图与等级化人物比例被赫梯、亚述与波斯艺术反复借用，是近东纪念性浮雕的原型之一。", figures: ["纳拉姆-辛"], place: "苏萨（被埃兰掠走），今法国卢浮宫藏", state: "阿卡德帝国", sources: ["卢浮宫阿卡德艺术馆藏图录", "《剑桥古代史》第1卷第2分册"], tags: ["胜利石碑", "浮雕", "政治宣传"] }, related: [] },
  { id: "world--b2250--s01", track: "world", year: -2250, yearApprox: true, dim: "science", weight: 3, title: "双语词表与书吏学校", summary: "阿卡德语与苏美尔语对照词表成型于教学体系。", detail: { background: "帝国官方语改为阿卡德语，但宗教与学术文献仍以苏美尔语书写，需系统转译。", process: "出土泥板含神名表、器物表与苏阿卡双语词列，属早期「法尔拉」式名单传统；抄写者与批注显示学生按「抄—背—校」的次序训练。", impact: "词表与校勘方法构成西亚语文学的起点，使两河学术可跨语言累积，也让苏美尔语作为学者语言存活两千年。", figures: ["不可考的书吏教师"], place: "尼普尔、法拉等学术城市（今伊拉克）", state: "阿卡德帝国", sources: ["廷尼《尼普尔的学校》（1996）", "普里查德编《古代近东文献》"], tags: ["词表", "书吏学校", "双语教学"] }, related: [] },
  { id: "world--b2245--f01", track: "world", year: -2245, yearApprox: true, dim: "figure", weight: 4, title: "恩胡安娜：最早署名作者", summary: "萨尔贡之女任月神庙大祭司，留下署名圣诗。", detail: { background: "王室以女性成员出任乌尔月神庙「恩图」祭司，作为控制南方的政治安排。", process: "她作《伊南娜颂》等圣诗并在结尾自署姓名与身份；其作品被后世抄写校订，序言自述因被排挤而离开圣所、终得复职。", impact: "她是有确切证据的最早署名文学作者，其文本也是研究苏阿卡德宗教、性别与王权关系的关键文献。", figures: ["恩胡安娜", "萨尔贡", "纳拉姆-辛"], place: "乌尔与阿卡德（今伊拉克南部）", state: "阿卡德帝国", sources: ["恩胡安娜作品抄本普里查德编《古代近东文献》与亚述学丛刊", "世界文学史古代分卷相关章节"], tags: ["恩胡安娜", "署名作者", "圣诗"] }, related: [] },
  { id: "world--b2200--d01", track: "world", year: -2200, yearApprox: true, dim: "disaster", weight: 5, title: "4.2千年事件与阿卡德崩溃", summary: "持续性干旱同时冲击两河、埃及与印度河文明。", detail: { background: "全新世中期末全球季风减弱，西亚降雨带南移，学界称4.2千年干旱事件。", process: "戈兰湖与阿拉伯海岩芯、沙漠粉尘记录显示约前2200—前1900年出现多年少雨；同期哈布尔农业带数百遗址被弃，尼罗河低水位、印度河城市萎缩与埃及第一中间期分裂并行发生。", impact: "该事件被视为阿卡德亡国、苏美尔复兴与游牧—半游牧人群（阿摩利人）进入两河的重要背景条件，是气候影响国家命运的典型例证。", figures: ["不可考的旱区农户"], place: "西亚—北非—南亚干旱带（今伊拉克、叙利亚、埃及、巴基斯坦）", state: "阿卡德帝国", sources: ["魏斯《4.2千年事件与古代近东》（《地质考古学》2018年综述）", "《剑桥古代史》第1卷第2分册"], tags: ["气候事件", "干旱", "文明崩溃"] }, related: [] },
  { id: "world--b2190--e01", track: "world", year: -2190, yearApprox: true, dim: "economy", weight: 3, title: "哈布尔农业带的废弃", summary: "帝国粮仓因干旱与战乱弃耕，牧道取代田畴。", detail: { background: "阿卡德在叙利亚北部开辟靠天然降雨农业的大垦区，以剩余谷物支撑南部军队。", process: "勘察显示约前2200年起数百聚落在一两代人内被弃，房屋保存完好；遗址序列中出现游牧帐篷式痕迹与墓地，河渠出现沙化与风成沉积。", impact: "这次土地利用反转使叙利亚人口向两河与黎凡特绿洲迁移，重塑前两千纪初西亚的族群与政治格局。", figures: ["不可考的垦户"], place: "叙利亚东北部哈布尔河流域", state: "阿卡德帝国", sources: ["魏斯《哈布尔农业带的形成与崩塌》（《科学》1997）", "哈布尔河流域勘察报告"], tags: ["弃耕", "半干旱农业", "族群迁移"] }, related: [] },
  { id: "world--b2154--p01", track: "world", year: -2154, yearApprox: true, dim: "politics", weight: 3, title: "古提人终结阿卡德王国", summary: "扎格罗斯山民进入两河，帝国秩序瓦解为小城割据。", detail: { background: "干旱削弱税基、军队欠饷，末代诸王已无法控制山区通道。", process: "传统年表记约前2154年（学界推定）古提人（「山中来民」）攻占阿卡德，「王权不知落于谁家」；此后两河出现古提总督与苏美尔小城并立的局面。", impact: "阿卡德解体使苏美尔诸城复兴，并促成乌尔第三王朝以「驱除古提」为号召重建集权，也留下大量以亡国为主题的文学。", figures: ["古提王提里坎", "纳拉姆-辛（传说被害）"], place: "阿卡德与苏美尔（今伊拉克）", state: "阿卡德帝国", sources: ["《古提王表》（《古代近东文献》选译）", "《剑桥古代史》第1卷第2分册"], tags: ["古提人", "王朝更替", "游牧入侵"] }, related: [] },
  { id: "world--b2140--c01", track: "world", year: -2140, yearApprox: true, dim: "culture", weight: 3, title: "《阿加德的诅咒》", summary: "以神罚叙事解释帝国崩溃的文学反思。", detail: { background: "乌尔第三王朝前后需要解释为何强大帝国会灭亡，并把责任归于王的不敬。", process: "泥板文本称纳拉姆-辛亵渎尼普尔恩利尔庙、拆其围墙，故恩利尔「不再受苏美尔祈求」，令古提人如「不讲之族」入国，田荒盐碱、雨水失时。", impact: "它确立了以神意—道德因果解释历史兴衰的两河史学范式，与《哀歌》体裁共同构成古代近东历史书写的重要源头。", figures: ["纳拉姆-辛（文学形象）"], place: "两河流域（抄本出于尼普尔、乌尔）", state: "苏美尔城邦", sources: ["克雷默《历史始于苏美尔》，1931 初版文本", "普里查德编《古代近东文献》"], tags: ["亡国文学", "神义论", "史学"] }, related: [] },
  { id: "world--b2130--i01", track: "world", year: -2130, yearApprox: true, dim: "institution", weight: 3, title: "古地亚的「社会改革」铭文", summary: "拉格什恩西自称抑制豪强、重建公平秤量。", detail: { background: "古提时期城邦内部贫富分化加剧，前朝官员与富商侵夺平民田屋。", process: "古地亚铭文列数「以前强者吞噬弱者」，宣称废除苛征、恢复尼纳吉拉神的「正当田亩与秤」，并重修诸神庙、减免徭役。", impact: "这段文本是现存最早以「社会正义」为纲的统治者自我标榜，其「改革—复旧」话语成为此后近东立国文书的固定套语。", figures: ["古地亚", "纳马赫萨尼（其妻）"], place: "拉格什与吉尔苏（今伊拉克泰勒洛赫）", state: "苏美尔城邦", sources: ["古地亚雕像铭文（《古代近东文献》选译）", "福斯特《古代近东文献》(古代近东文献第3版)"], tags: ["社会改革", "拉格什", "铭文"] }, related: [] },
  { id: "world--b2130--a01", track: "world", year: -2130, yearApprox: true, dim: "art", weight: 2, title: "古地亚圆像与计划板", summary: "闪长岩坐姿像头戴建模图板，凸显建筑师之王。", detail: { background: "极少的闪长岩原料需从遥远的阿曼或阿富汗输入，显示其贸易与财力。", process: "出土约三十件刻其名的像，多为坐姿、披苏美尔式羊毛袍，膝上置一块刻有神庙平面与立面「计划板」；部分像有「狮形」护身。", impact: "这批像把统治者表现为神庙的设计者与供养者，确立了「王—建筑师」的图像范式，并保存了唯一古代建筑图纸实物。", figures: ["古地亚"], place: "泰洛赫（古拉格什，今伊拉克）", state: "苏美尔城邦", sources: ["卢浮宫与伊斯坦布尔古代东方博物馆古地亚像图录", "《伊朗与古代近东艺术》（卢浮宫馆刊）"], tags: ["闪长岩像", "建筑图", "古地亚"] }, related: [] },
  { id: "world--b2112--p01", track: "world", year: -2112, yearApprox: true, dim: "politics", weight: 4, title: "乌尔纳姆建乌尔第三王朝", summary: "以南向集权重建苏美尔国家，自称三河之王。", detail: { background: "乌尔在乌鲁克末期的动荡中由乌尔纳姆及其兄乌勒泰勒基达掌权，背靠乌图太阳神庙经济。", process: "约前2112年（学界推定）起，乌尔纳姆逐古提、征服乌鲁克与拉格什，取「苏美尔与阿卡德之王」号，遣使诸城并恢复运河与关税秩序。", impact: "该王朝把苏美尔式官僚统治推到极限，其法律、档案与建筑成为两河治理技术的集大成，也是苏美尔政治的最后辉煌。", figures: ["乌尔纳姆", "乌勒泰勒基达"], place: "乌尔与苏美尔诸城（今伊拉克泰勒穆盖耶尔）", state: "乌尔第三王朝", sources: ["《剑桥古代史》第1卷第2分册", "乌尔纳姆王室铭文与纪年表"], tags: ["乌尔第三王朝", "苏美尔复兴", "集权"] }, related: [] },
  { id: "world--b2100--i01", track: "world", year: -2100, yearApprox: true, dim: "institution", weight: 5, title: "《乌尔纳姆法典》", summary: "现存最古老的成文法典，确立以银赔偿代替同态复仇。", detail: { background: "王朝初立需以统一规则取代诸城旧习并重整司法秩序。", process: "泥板残本含序言与约二十九条，条款多采「若某人……则赔若干舍克尔银」形式，涉及人身伤害、奴隶逃匿、婚姻与诬告；其后有《里特-伊什塔尔法典》与《埃什嫩那法典》。", impact: "它证明法典化立法早于汉谟拉比三百余年，「以赔偿替代复仇」的取向与「王为正义之源」的序言为后世近东法典奠定体例。", figures: ["乌尔纳姆"], place: "乌尔（抄本今存费城与伊斯坦布尔）", state: "乌尔第三王朝", sources: ["克拉默《乌尔纳姆法典》文本刊布与研究", "普里查德编《古代近东文献》 法典选译"], tags: ["法典", "赔偿制", "司法"] }, related: [] },
  { id: "world--b2100--s01", track: "world", year: -2100, yearApprox: true, dim: "science", weight: 4, title: "乌尔大塔庙的砖构技术", summary: "以模数泥砖、排水孔与外倾墙建成三层台庙。", detail: { background: "塔庙需在冲积平原上以无石材料建成高耸且耐雨的结构。", process: "乌尔大塔庙（乌尔纳姆始建）台基约64×46米，以泥砖分层砌筑，砖面留「绳眼」与通气孔排湿，外墙略向内倾；以三层递减平台象征登山之阶，配砖砌拱与排水沟。", impact: "其技术手册化的砌法为两河此后塔庙与城墙沿用，也留下了至今最高的泥砖建筑实例之一。", figures: ["乌尔纳姆", "舒尔吉"], place: "乌尔（今伊拉克泰勒穆盖耶尔）", state: "乌尔第三王朝", sources: ["吴利《乌尔发掘报告》", "《剑桥古代技术史》第1卷"], tags: ["塔庙", "泥砖", "结构工程"] }, related: [] },
  { id: "world--b2090--e01", track: "world", year: -2090, yearApprox: true, dim: "economy", weight: 2, title: "王家纺织作坊与乌尔第三王朝劳役经济", summary: "数千名织工与童工按定额计口给粮于国家作坊。", detail: { background: "纺织是王朝换取金属与木材的出口主业，需集中管理。", process: "德勒哈姆（乌姆盖耶尔周边）与乌尔档案记「乌拉-乌拉」等王室作坊，工人以数千计、含妇孺，按「拉（口粮）」日配大麦与油，逃亡记录亦见于泥板。", impact: "这类档案使乌尔第三王朝成为古代世界最接近「指令性再分配经济」的个案，也为其后王朝崩解时的社会离心提供了证据。", figures: ["普扎尔-马玛", "不可考的作坊监工"], place: "乌尔与德勒哈姆（今伊拉克南部）", state: "乌尔第三王朝", sources: ["德勒哈姆泥板档案刊本", "《剑桥古代史》第1卷第2分册"], tags: ["纺织作坊", "口粮制", "劳役"] }, related: [] },
  { id: "world--b2047--i01", track: "world", year: -2047, yearApprox: true, dim: "institution", weight: 3, title: "乌尔第三王朝的行省档案网", summary: "以总督、书吏与定期报表，列诸城于统一账簿。", detail: { background: "王朝疆域自波斯湾至基什，需要跨城的财政与人力调度。", process: "各行省遣「沙加纳」监督，驿站以驴队传送文书；王室档案馆（如吉沙与德勒哈姆）按年名分类封存泥板，含收支、牲畜与徭役名单，出土数以万计。", impact: "这套以报表和年名归档的行政技术被视为古代官僚制的样板，其档案习惯为巴比伦与亚述继承。", figures: ["不可考的王朝书吏"], place: "乌尔第三王朝诸省（今伊拉克南部）", state: "乌尔第三王朝", sources: ["乌尔第三王朝行政泥板丛刊", "《剑桥古代史》第1卷第2分册"], tags: ["官僚制", "档案", "行省"] }, related: [] },
  { id: "world--b2030--p01", track: "world", year: -2030, yearApprox: true, dim: "politics", weight: 3, title: "舒尔吉改制与《舒尔吉法典》", summary: "统一历法、军制与税则，编纂五部分法典。", detail: { background: "其父乌尔纳姆奠基后，舒尔吉以四十余年统治完善制度并长期对古提与埃兰用兵。", process: "《舒尔吉法典》序言宣称禁强凌弱、为孤儿寡妇立正义，条款涉及军役与「拉古鲁」阶层、税则与度量；同时推行以王历年为纪年、统一地方行政。", impact: "它把军事义务与免税特权绑定，形成两河最早的正规军制，并使法典成为王权意识形态的标准载体。", figures: ["舒尔吉"], place: "乌尔与尼普尔（今伊拉克南部）", state: "乌尔第三王朝", sources: ["《舒尔吉法典》序言与条文（《古代近东文献》选译）", "乌尔第三王朝纪年表"], tags: ["改革", "军制", "法典"] }, related: [] },
  { id: "world--b2030--a01", track: "world", year: -2030, yearApprox: true, dim: "art", weight: 2, title: "舒尔吉颂歌与王权文学", summary: "以自我谦抑与神宠叙事颂扬王朝第三主。", detail: { background: "宫廷诗人需要把君主的征战、巡游与虔敬写成可传诵的范式。", process: "现存约二十余首署名舒尔吉的颂歌含《舒尔吉与帕尔兰奈》等，描写其巡视诸城、祭祀与「我非长者、吾王尚少」的谦辞；抄本为书吏学校教材。", impact: "这批文本确立了两河的「君王巡游—正义—祭祀」叙事模板，也是研究苏美尔诗歌格律与并行体的核心材料。", figures: ["舒尔吉", "不可考的宫廷诗人"], place: "尼普尔与乌尔（今伊拉克）", state: "乌尔第三王朝", sources: ["电子苏美尔语文学语料库（ETCSL）舒尔吉颂歌条目", "普里查德编《古代近东文献》"], tags: ["颂歌", "宫廷文学", "苏美尔语"] }, related: [] },
  { id: "world--b2020--m01", track: "world", year: -2020, yearApprox: true, dim: "military", weight: 3, title: "「莫里杜姆」防阿摩利边墙", summary: "王朝筑长城式堤墙遏制半游牧部落北侵。", detail: { background: "阿摩利（「西方人」）族群随干旱向南与向东渗入定居农业区。", process: "泥板记舒尔吉与伊丁-达甘时代修筑名为「莫里杜姆」的堤墙，「以禁阿摩利人」，沿线设哨所与烽火传警，征发诸城民役守堵。", impact: "这是两河最早的长城式边界工程，其失败（约一代后王朝为阿摩利与埃兰所灭）成为古代定居—游牧张力的典型样本。", figures: ["舒尔吉", "伊丁-达甘"], place: "两河中游草原与河阶地带（今伊拉克）", state: "乌尔第三王朝", sources: ["乌尔第三王朝行政泥板中「莫里杜姆」条（刊布与综述）", "《剑桥古代史》第1卷第2分册"], tags: ["边界工事", "阿摩利人", "定居与游牧"] }, related: [] },
  { id: "world--b2004--p01", track: "world", year: -2004, yearApprox: true, dim: "politics", weight: 4, title: "埃兰灭乌尔第三王朝", summary: "埃兰与伊辛联军破乌尔，执末王伊比辛。", detail: { background: "王朝税役沉重，伊辛总督伊什比耶拉断贡，阿摩利人群入境，边军离心。", process: "约前2004年（学界推定）埃兰军与伊辛联军攻陷乌尔，末王伊比辛被俘至埃兰处死；《乌尔哀歌》称城市遭焚、神庙被掠，马尔杜克神像北迁。", impact: "苏美尔作为独立政治体自此消失，其语言转为宗教与学术用语，两河进入巴比伦、伊辛、拉尔萨并立的阿摩利诸王朝时代。", figures: ["伊比辛", "伊什比耶拉", "埃兰王金底努"], place: "乌尔与苏萨（今伊拉克与伊朗）", state: "乌尔第三王朝", sources: ["《乌尔哀歌》（《古代近东文献》选译）", "伊辛与埃兰相关年名表"], tags: ["王朝覆亡", "埃兰", "阿摩利人"] }, related: [] },
  { id: "world--b2000--c01", track: "world", year: -2000, yearApprox: true, dim: "culture", weight: 3, title: "苏美尔语的学院化", summary: "政治消亡后苏美尔语仍以宗教与学术语言存续。", detail: { background: "阿卡德语成为口语后，神庙礼仪与法典、文学文本仍依赖苏美尔语原本。", process: "伊辛与拉尔萨时期尼普尔等地学校大量抄写苏美尔文学与词表，出现苏阿对照双语教材与「苏美尔语辞书」，吉尔伽美什等史诗被重订。", impact: "这一「拉丁式」双层语言格局支撑了两河知识阶层的共同身份，也使苏美尔文献得以进入后来的亚述与巴比伦抄本传统。", figures: ["不可考的尼普尔教师"], place: "尼普尔、伊辛与拉尔萨（今伊拉克）", state: "伊辛-拉尔萨时期诸邦", sources: ["范德米尔洛普《苏美尔与阿卡德文学的生成》（2015）", "电子苏美尔语文学语料库（ETCSL）编纂说明"], tags: ["双语教育", "文献传承", "苏美尔语"] }, related: [] },
  { id: "world--b1985--p01", track: "world", year: -1985, yearApprox: true, dim: "politics", weight: 3, title: "第十二王朝迁都伊塔维", summary: "阿蒙涅姆赫特一世重建中央集权并立太子共治。", detail: { background: "第一中间期州长割据使王权萎缩，底比斯系君主需摆脱旧贵族网络。", process: "约前1985年（学界推定）阿蒙涅姆赫特一世建都伊塔维（全称意为「阿蒙涅姆赫特攫取双土」，今埃及利什特），并首创王太子加冕共治制，其《阿蒙涅姆赫特训诫》述宫廷危机与登基经过。", impact: "该王朝重整税制、军队与灌溉，开启中王国盛期，其文学宣传手法（训诫、预言）成为埃及政治写作的新样式。", figures: ["阿蒙涅姆赫特一世", "塞努斯雷特一世"], place: "伊塔维与法尤姆绿洲（今埃及利什特）", state: "古埃及", sources: ["《阿蒙涅姆赫特训诫》纸草（《古代近东文献》选译）", "《剑桥古代史》第1卷第2分册"], tags: ["中王国", "共治", "政治文学"] }, related: [] },
  { id: "world--b1975--s01", track: "world", year: -1975, yearApprox: true, dim: "science", weight: 3, title: "法尤姆水利与垦田", summary: "以堤坝、调节湖与渠道，改沼泽为新耕地。", detail: { background: "中王国需要在不增赋的情况下扩大税基，法尤姆洼地具备条件。", process: "在拉洪筑堤与溢洪道，把约塞勒湖（莫里斯湖）作为汛期蓄水库，经渠道网输入洼田；拉洪与卡胡恩出土测量标记、地籍板与营城遗址。", impact: "该工程新增可耕地与稳定灌溉，是古代最大规模的人工水利垦区之一，其「蓄水—调节—配水」原理为后世复用。", figures: ["塞努斯雷特二世", "塞努斯雷特三世"], place: "法尤姆绿洲（今埃及）", state: "古埃及", sources: ["不列颠博物院藏拉洪纸草刊本", "《剑桥古代技术史》第1卷"], tags: ["水利", "垦田", "地籍"] }, related: [] },
  { id: "world--b1970--i01", track: "world", year: -1970, yearApprox: true, dim: "institution", weight: 3, title: "削平世袭州长", summary: "第十二王朝废除州职权，恢复王室税吏直辖。", detail: { background: "第一中间期各州长世袭掌兵粮，形成割据。", process: "铭文与传记（如《赫加提-提比传记》）显示王室强制州长交出「州印」，把税册与徭役归中央「两国库」，并以「随从」制把地方精英子弟安置于宫廷。", impact: "这次行政集权使法老重新直接掌握人力与谷仓，为中王国的大型工程与努比亚远征提供财政前提。", figures: ["塞努斯雷特三世", "不可考的州长"], place: "上埃及诸州（今埃及中南部）", state: "古埃及", sources: ["《剑桥古代史》第2卷", "赫加提-提比等州长传记铭文"], tags: ["中央集权", "州制", "行政改革"] }, related: [] },
  { id: "world--b1950--e01", track: "world", year: -1950, yearApprox: true, dim: "economy", weight: 4, title: "亚述商列与卡尼什档案", summary: "亚述私商以锡与布匹换取安纳托利亚白银。", detail: { background: "两河缺银，安纳托利亚富银缺锡，而锡为青铜所必需。", process: "库尔特佩（古卡尼什）出土约23000块泥板，记以驴队跨越扎格罗斯与托罗斯的商站（卡鲁姆），贷记、合伙、寄售与利息条款详备，货物以白银计价、以锡与「阿姆图」布匹抵付。", impact: "这批档案是现存最早的私人商业文书群，证明前两千纪已存在跨国的信用与合伙制度，也确立了亚述的商业城市角色。", figures: ["普苏塞内（亚述商人）", "拉玛-阿舒尔（其妻，纺织经营者）"], place: "卡尼什（今土耳其库尔特佩）与阿舒尔", state: "古亚述", sources: ["库尔特佩泥板刊本（甲、乙集）", "米克尔森《亚述商人与其企业》综述（20世纪80年代）"], tags: ["商列", "合伙制", "锡贸易"] }, related: [] },
  { id: "world--b1950--i01", track: "world", year: -1950, yearApprox: true, dim: "institution", weight: 3, title: "商号的合伙与汇兑契约", summary: "以「出资—代运—分成」契约分担长途贸易风险。", detail: { background: "长途贸易风险高、通信以年计，需要可执行的责任分配与信用安排。", process: "卡尼什契约中，商人家族以家族成员分驻阿舒尔与卡尼什，「纳鲁姆」款项由出资方交付代理人，约定运损、盗劫与迟延责任，利息以每舍克尔每月若干舍计算。", impact: "这类契约是后世汇票与公司制度的远祖之一，也说明古代近东的法律技术已能处理跨期、跨地的金融关系。", figures: ["不可考的亚述商伙"], place: "卡尼什与阿舒尔（今土耳其与伊拉克）", state: "古亚述", sources: ["库尔特佩泥板刊本", "范德米尔洛普《古代近东》商业制度章"], tags: ["合伙", "信贷", "契约法"] }, related: [] },
  { id: "world--b1930--p01", track: "world", year: -1930, yearApprox: true, dim: "politics", weight: 3, title: "塞努斯雷特三世划定努比亚边界", summary: "建塞姆纳界碑于第二瀑布，禁努比亚人北过。", detail: { background: "尼罗河第二瀑布一带是黄金、牲畜与奴隶贸易的关口。", process: "塞姆纳与博亨堡垒出土花岗岩界碑，铭文以严酷措辞禁止努比亚人「越此界北上贸易」，违者受击；同时期遣军深入第四瀑布。", impact: "该边界制度使埃及得以垄断黄金南下与人口掠夺，其碑文也是研究古代族群边界与国家管控政策的直接材料。", figures: ["塞努斯雷特三世"], place: "塞姆纳堡（今苏丹瓦迪哈勒法附近）", state: "古埃及", sources: ["塞姆纳界碑铭文（《古代近东文献》选译）", "英国埃及探险学会努比亚勘察报告"], tags: ["边界", "努比亚", "要塞"] }, related: [] },
  { id: "world--b1930--m01", track: "world", year: -1930, yearApprox: true, dim: "military", weight: 2, title: "埃及努比亚堡垒线", summary: "沿第二瀑布建砖堡与吊桥式城门，控扼河运。", detail: { background: "尼罗河峡谷地段不便陆行，控制河船即可控制金矿与畜群。", process: "塞姆纳、库玛、博亨等堡垒以厚泥砖墙围合，内置粮仓、兵营与船坞；纸草显示守军以信鸽与哨船通报，越境者按界碑处治。", impact: "这套纵深河防是古代以要塞网管理边界的范例，其驻军—粮秣—巡查体制在后期被新王国进一步推向第四瀑布。", figures: ["不可考的堡监"], place: "努比亚堡垒线（今埃及南部与苏丹北部）", state: "古埃及", sources: ["塞姆纳纸草（英国博物馆藏）刊布", "埃默里《努比亚考古》"], tags: ["要塞", "边界管理", "河防"] }, related: [] },
  { id: "world--b1920--c01", track: "world", year: -1920, yearApprox: true, dim: "culture", weight: 3, title: "埃及教谕文学的定型", summary: "以「父训子」体裁总结治国与处世之道。", detail: { background: "中王国宫廷需要把官僚伦理与服从规范传给精英子弟。", process: "《普罗塔赫教谕》《阿蒙涅姆赫特训诫》与《对美里卡拉王的教谕》成于中王国或其抄本传统，内容论慎言、选才、赈贫与「勿欺弱、惧公义」。", impact: "这类文本被学界视为古代智慧文学的东方源头之一，其「劝诫—箴言」结构与《箴言》等希伯来文献的关联长期被讨论。", figures: ["普罗塔赫", "美里卡拉（传说王）"], place: "底比斯与伊塔维（今埃及）", state: "古埃及", sources: ["普里查德编《古代近东文献》教谕选译", "利科《埃及智慧文学》"], tags: ["智慧文学", "教谕", "官僚伦理"] }, related: [] },
  { id: "world--b1900--s01", track: "world", year: -1900, yearApprox: true, dim: "science", weight: 3, title: "中王国的数学与工程算例", summary: "以「阿佩德」比值处理塔坡坡度，算截锥体积。", detail: { background: "金字塔与堤坝施工需要可复算的坡度与土方量方法。", process: "莫斯科数学纸草所收题（其原本被学界归入中王国传统）含截锥体积算法与「阿佩德」（水平跑若干肘对应垂直升一肘）计算；卡胡纳出土木质量规与测量标记。", impact: "这些算法表明埃及已形成实用几何与算术体系，为建筑标准化与国家地籍测量提供工具，其方法沿用至托勒密时期。", figures: ["不可考的工程算吏"], place: "伊塔维与卡胡纳（今埃及）", state: "古埃及", sources: ["瓦西里耶夫《莫斯科数学纸草》刊本", "《剑桥古代技术史》第1卷"], tags: ["数学", "坡度", "测量"] }, related: [] },
  { id: "world--b1894--p01", track: "world", year: -1894, yearApprox: true, dim: "politics", weight: 3, title: "巴比伦第一王朝建立", summary: "阿摩利人苏姆阿伊姆据有巴比伦小城。", detail: { background: "乌尔第三王朝崩溃后，阿摩利部落首领在诸城自立，巴比伦地处两河最窄处。", process: "王表记约前1894年（学界推定）苏姆阿伊姆取巴比伦，其后百年间小城仍受制于伊辛、拉尔萨与亚述；至汉谟拉比时方成大国。", impact: "巴比伦由边陲小城跃为宗教与政治中心，其守护神马尔杜克被抬升为万神之首，城市自此成为两河南部的永久首都。", figures: ["苏姆阿伊姆", "汉谟拉比（其后裔）"], place: "巴比伦（今伊拉克希拉附近）", state: "古巴比伦王国", sources: ["《巴比伦王表》（《古代近东文献》选译）", "范德米尔洛普《巴比伦：古代世界的活历史》"], tags: ["阿摩利王朝", "巴比伦", "建国"] }, related: [] },
  { id: "world--b1850--p01", track: "world", year: -1850, yearApprox: true, dim: "politics", weight: 2, title: "伊辛-拉尔萨的两河竞逐", summary: "两城争夺尼普尔与灌溉要道，形成均势。", detail: { background: "伊辛持尼苏拉神庙的祭祀正统，拉尔萨控扼通往波斯湾的水路。", process: "双方以运河筑坝为武器互断水源，争夺伊辛河与「哈马布拉」渠口，并各自宣称「苏美尔与阿卡德之王」；城邦间以条约与联姻维系同盟。", impact: "这种以水为兵的竞争模式说明灌溉体系的脆弱性，也为汉谟拉比以外交与水利手段整合两河提供了先例。", figures: ["里特-伊什塔尔（立法者）", "拉尔萨王里姆辛"], place: "伊辛与拉尔萨（今伊拉克）", state: "伊辛-拉尔萨时期诸邦", sources: ["《拉姆辛年名表》", "《古代近东文献》法典序言选译"], tags: ["水战", "均势", "城邦竞争"] }, related: [] },
  { id: "world--b1830--m01", track: "world", year: -1830, yearApprox: true, dim: "military", weight: 3, title: "沙姆什-阿达德一世建上美索不达米亚", summary: "亚述王推势力至地中海，并控扼商路。", detail: { background: "亚述趁伊辛-拉尔萨衰落北扩，夺取卡尼什等商站。", process: "文献记其得马里并扶植儿子伊什梅-达甘为穆克纳姆，远征「上地」至「大海」；《亚述王表》称其同时「五世（年）在尼尼微」修建神庙。", impact: "这是亚述第一次成为两河霸主，其商路—附庸体系与「宇宙之王」称号为此后新亚述帝国提供了模板。", figures: ["沙姆什-阿达德一世", "伊什梅-达甘", "叶赫顿-利姆（马里王）"], place: "亚述与马里（今伊拉克北部与叙利亚）", state: "古亚述", sources: ["马里与亚述王表文献（《古代近东文献》选译）", "《剑桥古代史》第1卷第2分册"], tags: ["亚述扩张", "商路", "附庸制"] }, related: [] },
  { id: "world--b1810--x01", track: "world", year: -1810, yearApprox: true, dim: "explore", weight: 2, title: "驴队商道与扎格罗斯山隘", summary: "商列档案留下最早的内陆驿路详记。", detail: { background: "锡与布匹需经山地与草原运往安纳托利亚，路况决定成本。", process: "卡尼什泥板记自阿舒尔经埃卡拉图姆、哈马丹道至卡尼什约1000公里，驴队日行约30—40公里，途中在「达玛合姆」驿站过夜，须付草料与山民通行费。", impact: "这些路线与站点构成西亚最早的有文献可考的陆路交通体系，其走向在此后两千年被帝国御道大体继承。", figures: ["不可考的驼驴夫"], place: "扎格罗斯与托罗斯山道（今伊拉克—土耳其）", state: "古亚述", sources: ["卡尼什泥板行程条（刊本综述）", "《剑桥古代技术史》第1卷交通章"], tags: ["商道", "驿站", "山隘"] }, related: [] },
  { id: "world--b1792--p01", track: "world", year: -1792, yearApprox: true, dim: "politics", weight: 3, title: "汉谟拉比即位巴比伦", summary: "第六代巴比伦王以外交与水利逐步统一两河。", detail: { background: "即位时巴比伦夹处拉尔萨、亚述、埃什嫩那与马里之间。", process: "依「中等年表」其即位在约前1792年（学界另有短年表说）；早年修渠、筑城、调解属邦纷争，与拉尔萨结盟共灭埃兰，再反戈灭拉尔萨（前1763）。", impact: "四十余年的经营使巴比伦成为两河全境的宗主，其立法与行政遗产塑造了此后一千年的巴比伦尼亚秩序。", figures: ["汉谟拉比", "里姆辛"], place: "巴比伦城（今伊拉克希拉附近）", state: "古巴比伦王国", sources: ["《汉谟拉比年名表》", "《剑桥古代史》第1卷第2分册（含年表争议说明）"], tags: ["汉谟拉比", "中等年表", "外交"] }, related: [] },
  { id: "world--b1785--e01", track: "world", year: -1785, yearApprox: true, dim: "economy", weight: 3, title: "「汉谟拉比丰饶」运河", summary: "以长渠引幼发拉底水入南部干旱洼地。", detail: { background: "拉尔萨与巴拉图地区灌溉不均，王权以水利工程宣示「养民」。", process: "铭文记其凿「汉谟拉比是丰饶之源」运河，「为苏美尔与阿卡德引水」，渠口设闸门并遣「渠监」；泥板显示按户配水与清淤劳役轮派。", impact: "新灌区扩大麦田与枣园产量，也使下游水权争端频繁，水渠管理由此成为巴比伦国家行政的核心职能。", figures: ["汉谟拉比"], place: "巴比伦尼亚南部（今伊拉克希拉以南）", state: "古巴比伦王国", sources: ["汉谟拉比王室铭文（《古代近东文献》选译）", "范德米尔洛普《汉谟拉比：巴比伦之王》（2021）"], tags: ["运河", "灌溉", "水利行政"] }, related: [] },
  { id: "world--b1780--s01", track: "world", year: -1780, yearApprox: true, dim: "science", weight: 4, title: "巴比伦数学泥板与勾股数表", summary: "普林顿322列出多组满足勾股关系的整数三元组。", detail: { background: "书吏训练需要面积、坡度与平方根的算法，60进制位值算体系成熟。", process: "普林顿322（抄本约当古巴比伦期，学界推定）含十五行数字，学界认为与直角三角形比值表相关；另见倒数表、平方与立方表及二次方程题解（如大英博物馆13901号泥板）。", impact: "这些文献证明巴比伦已具纯算术与代数操作能力，早于毕达哥拉斯千余年，其方法经希腊与伊斯兰传入近代欧洲。", figures: ["不可考的书吏算家"], place: "拉尔萨或西帕尔（抄本出处，今伊拉克）", state: "古巴比伦王国", sources: ["诺伊格鲍尔《数学泥板》（1935）与普林顿大学馆藏说明", "罗布森《古巴比伦的数学》"], tags: ["数学泥板", "勾股数", "六十进制"] }, related: [] },
  { id: "world--b1776--m01", track: "world", year: -1776, yearApprox: true, dim: "military", weight: 3, title: "汉谟拉比水淹马里", summary: "以决堤与围城终结这座幼发拉底河商都。", detail: { background: "马里曾与巴比伦同盟灭拉尔萨，随后倒向反巴比伦联盟。", process: "年名记其筑坝围城、毁「城墙与营垒」，文献传统称以水灌城；发掘显示马里宫殿与档案库（含约25000块泥板）在一场焚毁中被弃。", impact: "马里的覆亡使巴比伦掌握通往叙利亚与安纳托利亚的河运枢纽，其焚毁也意外保存了研究当时外交的庞大泥板档案。", figures: ["汉谟拉比", "津里-利姆（马里末王）"], place: "马里（今叙利亚泰勒哈里里）", state: "古巴比伦王国", sources: ["马里档案与汉谟拉比年名表", "范德米尔洛普《汉谟拉比》"], tags: ["围城", "决水", "马里档案"] }, related: [] },
  { id: "world--b1762--p01", track: "world", year: -1762, yearApprox: true, dim: "politics", weight: 4, title: "汉谟拉比统一两河中下游", summary: "灭埃什嫩那与亚述附庸体系，称「四方之王」。", detail: { background: "继灭拉尔萨、马里与埃什嫩那之后，仅剩亚述与南方海岸未被直接控制。", process: "晚年铭文与年名记其拆毁诸城城墙、平定「安丹尼格与埃什嫩那」，取「巴比伦之王、四方之王」号，把关税与军粮集中于王室仓库。", impact: "这一整合结束了苏美尔崩溃后的列国时代，形成以巴比伦为中心的统一税制与法典体系，构成后世西亚帝国的范式之一。", figures: ["汉谟拉比"], place: "巴比伦与亚述诸城（今伊拉克、叙利亚）", state: "古巴比伦王国", sources: ["汉谟拉比后期年名与铭文（《古代近东文献》选译）", "《剑桥古代史》第1卷第2分册"], tags: ["统一", "霸权", "巴比伦"] }, related: [] },
  { id: "world--b1754--i01", track: "world", year: -1754, yearApprox: true, dim: "institution", weight: 5, title: "《汉谟拉比法典》", summary: "序言加282条，确立同态复仇与分级赔偿的成文法。", detail: { background: "新征服的土地需要统一司法标准，并以「正义」话语巩固王权。", process: "黑色闪长岩石柱高约2.25米（藏卢浮宫），序言称神命其「使正义遍临国土、杜绝强凌弱」，正文282条涉财产、租佃、婚姻、伤害、奴隶与专业责任（匠、医、船工），按自由民、穆什肯努与奴隶分级量刑。", impact: "它是古代近东保存最完整、影响最大的成文法，其分级责任与举证原则经亚述、希伯来法影响后世地中海法律传统。", figures: ["汉谟拉比"], place: "西帕尔（原碑），后为埃兰掠至苏萨", state: "古巴比伦王国", sources: ["卢浮宫法典石碑馆藏与谢尔刊本", "普里查德编《古代近东文献》全文选译"], tags: ["法典", "同态复仇", "社会分层"] }, related: [] },
  { id: "world--b1750--a01", track: "world", year: -1750, yearApprox: true, dim: "art", weight: 3, title: "法典碑顶的日神授权图", summary: "以面对面授环杖图像表达王权源于神授正义。", detail: { background: "石碑需以图像向不识字的臣民宣示其权威来源。", process: "碑顶浅浮雕中汉谟拉比向端坐的沙马什（日神与正义之神）伸手受「环与杖」，神肩放火焰、坐姿为神圣标志，构图沿用两河「朝见—授予」传统。", impact: "该图像把「立法」表现为神授职责，成为近东政治神学的核心视觉范式，也为此后君主立碑传统树立样板。", figures: ["汉谟拉比"], place: "巴比伦（原件藏卢浮宫）", state: "古巴比伦王国", sources: ["卢浮宫东方古物部馆藏图录", "《剑桥古代史》第1卷第2分册"], tags: ["授权图像", "沙马什", "纪念碑"] }, related: [] },
  { id: "world--b1750--s01", track: "world", year: -1750, yearApprox: true, dim: "science", weight: 3, title: "法典中的医者与匠人责任条款", summary: "以手术成败与建筑倒塌定赔偿或刑罚。", detail: { background: "专业化生产与医疗服务需要可预期的责任标准。", process: "法典规定：以青铜刀施「重度手术」致自由民死亡则断其手，致奴隶死亡则赔奴；房屋倒塌压死业主，则处死营造者；压死其子则处死其子；船工所造船漏则赔偿并重建。", impact: "这是已知最早的执业责任与产品责任立法，其「以身份定责」的原则反映古代法律的等级结构，也保存了两河外科与建筑技术水平。", figures: ["不可考的巴比伦外科医师"], place: "古巴比伦王国（今伊拉克）", state: "古巴比伦王国", sources: ["《汉谟拉比法典》第215—223、228—233条（通行编号）", "《古代近东文献》选译"], tags: ["医疗责任", "建筑规范", "法律"] }, related: [] },
  { id: "world--b1750--e01", track: "world", year: -1750, yearApprox: true, dim: "economy", weight: 3, title: "巴比伦的银本位与租佃市场", summary: "以银计价、按收成定租，出现专业放贷与中介。", detail: { background: "统一量制与长途贸易扩张，使货币化租佃与借贷成为常态。", process: "泥板显示田租多为收成1/3至1/2、园圃2/3，牛租以银计；放贷利率法定上限为谷物借贷33⅓%、银贷20%；「塔木达」商社与「沙马洛」代理制承担货运与代卖。", impact: "这套以银本位、法定利率与合伙代理为核心的市场制度，是古代近东最成熟的商品经济形态之一，为此后亚述与波斯所承袭。", figures: ["不可考的巴比伦放贷人"], place: "巴比伦、西帕尔、拉尔萨（今伊拉克）", state: "古巴比伦王国", sources: ["《汉谟拉比法典》租息条款", "古巴比伦私人契约泥板刊本（如 UET、YOS 丛刊）"], tags: ["银本位", "利率", "租佃"] }, related: [] },
  { id: "world--b1740--f01", track: "world", year: -1740, yearApprox: true, dim: "figure", weight: 2, title: "伊什梅-拉姆：王室通信的收信人", summary: "汉谟拉比致其南方书札，留存至今。", detail: { background: "国王以通信遥控边疆军政，是其行政风格的直接证据。", process: "出土数十封汉谟拉比与其子（或重臣）伊什梅-拉姆往来信，内容涉及军粮、渠工、祭祀与「速遣人报我」的政务指令，用语细致、语气急迫。", impact: "这批书信是研究古代君主「微观管理」与文书行政的第一手材料，也说明驿传系统在帝国治理中的决定作用。", figures: ["汉谟拉比", "伊什梅-拉姆"], place: "巴比伦与拉尔萨（今伊拉克南部）", state: "古巴比伦王国", sources: ["拉尔萨与巴比伦书信泥板刊本（《亚述与巴比伦文本》丛刊）", "范德米尔洛普《汉谟拉比》"], tags: ["王室书信", "行政", "驿传"] }, related: [] },
  { id: "world--b1700--p01", track: "world", year: -1700, yearApprox: true, dim: "politics", weight: 4, title: "喜克索斯人立朝三角洲", summary: "西亚裔统治者建第十五王朝，都于阿瓦里斯。", detail: { background: "第十三王朝衰微，三角洲东部长期有西亚移民与驻军首领。", process: "曼涅托与都灵王表所记「喜克索斯」（埃及语「异国统治者」）诸王以阿瓦里斯为都，取法老称号并沿用埃及神祇（以赛特对应其主神），同时上埃及诸王称臣纳贡。", impact: "这是埃及首次由外来王朝统治，其引入的战车、复合弓与青铜技术，以及被驱逐的记忆，直接推动新王国的军事化与叙利亚扩张。", figures: ["塞利（传说征服者）", "雅赫摩斯（后驱逐者）"], place: "阿瓦里斯（今埃及泰勒达巴）", state: "古埃及（第十五王朝）", sources: ["都灵王表与曼涅托（《埃及史》残篇）", "《剑桥古代史》第2卷；英国埃及探险学会泰勒达巴报告"], tags: ["喜克索斯", "外来王朝", "第二中间期"] }, related: [] },
  { id: "world--b1700--s01", track: "world", year: -1700, yearApprox: true, dim: "science", weight: 4, title: "战车与复合弓传入埃及", summary: "两轮战车与骨木复合弓改变西亚与埃及军力结构。", detail: { background: "马拉两轮战车与三层弓（木芯、角面、筋弦）源自近东草原与胡里安技术圈。", process: "阿瓦里斯与同时期遗址出土马具、颊饰与战车构件，壁画与浮雕显示驾驶舱、双轮辐条轮；复合弓射程与穿透力远超埃及自弓。", impact: "战车使「移动射手」成为战场主力，推动青铜时代晚期西亚国际体系形成；埃及驱逐喜克索斯后据此建立新王国野战军与叙利亚军团。", figures: ["不可考的胡里安车匠"], place: "尼罗河三角洲与黎凡特（今埃及、叙利亚）", state: "古埃及（第十五王朝）", sources: ["《剑桥古代技术史》第1卷", "泰勒达巴考古报告（荷兰莱顿大学发掘）"], tags: ["战车", "复合弓", "军事技术"] }, related: [] },
  { id: "world--b1700--e01", track: "world", year: -1700, yearApprox: true, dim: "economy", weight: 3, title: "印度河城市的衰落与东迁", summary: "河道改移与降水减少，哈拉帕大城陆续见弃。", detail: { background: "印度河与萨拉斯瓦蒂（加格尔-哈克拉）水系变迁直接决定城市存亡。", process: "摩亨佐-达罗晚期地层见房屋挤占、排水失修与重复铺面；多个大型城址在约前1900—前1300年间缩小或废弃，聚落重心东移至恒河上游，稻作与铁器时代文化随之兴起。", impact: "城市体系的解体使印度河文字与度量传统中断，南亚文明中心转向恒河流域，吠陀时代的村落社会由此成为主体。", figures: ["不可考的迁居农户"], place: "印度河与萨拉斯瓦蒂河流域（今巴基斯坦与印度西北）", state: "印度河文明", sources: ["肯沃西《印度河文明》（2008）", "焦桑等《印度河水系变迁》（《美国国家科学院院刊》2012）"], tags: ["城市衰落", "河道变迁", "南亚"] }, related: [] },
  { id: "world--b1650--p01", track: "world", year: -1650, yearApprox: true, dim: "politics", weight: 4, title: "赫梯国家定都哈图沙", summary: "印欧语系赫梯人建王国于安纳托利亚中枢。", detail: { background: "亚述商列时期城邦林立，哈梯人旧城被印欧语集团逐步整合。", process: "约前1650年（学界推定）拉巴尔纳斯或哈图沙一世取哈图沙为首都，其后哈图西里一世并吞阿勒颇与阿尔扎瓦，把王国推向地中海与叙利亚。", impact: "赫梯成为青铜时代晚期近东五强之一，其条约体系、炼铁技术与混合宗教深刻影响安纳托利亚、叙利亚与希腊世界。", figures: ["拉巴尔纳斯", "哈图沙"], place: "哈图沙（今土耳其博阿兹柯伊）", state: "赫梯王国", sources: ["赫梯王表与「哈图沙编年」（库尔特佩、博阿兹柯伊刊本）", "《剑桥古代史》第2卷"], tags: ["赫梯", "哈图沙", "建国"] }, related: [] },
  { id: "world--b1640--m01", track: "world", year: -1640, yearApprox: true, dim: "military", weight: 3, title: "赫梯早期征服安纳托利亚", summary: "以焚城与迁徙人口手段整合高原诸邦。", detail: { background: "安纳托利亚诸城邦以城墙与联盟抵抗中央化。", process: "哈图沙一世铭文自述夜袭普尔珊达、焚阿尔扎瓦、迁俘虏至哈图沙；其子穆尔西里一世续征阿勒颇，把兵锋推进到幼发拉底。", impact: "「焚毁—迁徙」成为赫梯与后来亚述的标准征服术，也促成安纳托利亚人口与工匠（尤其金属匠）的强制流动。", figures: ["哈图沙一世", "穆尔西里一世"], place: "安纳托利亚中部与东南部", state: "赫梯王国", sources: ["「哈图沙一世六年年鉴」（《古代近东文献》选译）", "克洛赫《赫梯战争》"], tags: ["征服", "焚城", "人口迁徙"] }, related: [] },
  { id: "world--b1628--d01", track: "world", year: -1628, yearApprox: true, dim: "disaster", weight: 4, title: "锡拉火山大喷发", summary: "爱琴海圣托里尼喷发摧毁岛屿并波及克里特。", detail: { background: "锡拉（塞克拉/圣托里尼）为火山弧一环，阿克罗蒂里已见繁荣聚落。", process: "冰芯硫酸盐层与碳十四给出约前1628—前1600的喷发窗口，考古年代学则主张约前1530；喷发指数约7级，火山灰厚覆阿克罗蒂里，海啸冲击克里特北岸港口与宫殿。", impact: "该事件削弱米诺斯海上力量、加速迈锡尼接管克里特，并被学界与「亚特兰蒂斯沉没」及埃及灾异记载相联系。", figures: ["马里尼托斯（发现阿克罗蒂里的考古学家）"], place: "锡拉岛与克里特（今希腊爱琴海）", state: "米诺斯文明", sources: ["弗里德里希《锡拉与米诺斯文明》", "冰芯与碳十四测年争议综述（《科学》相关论文）"], tags: ["火山喷发", "锡拉", "海啸"] }, related: [] },
  { id: "world--b1600--p01", track: "world", year: -1600, yearApprox: true, dim: "politics", weight: 4, title: "迈锡尼竖穴墓与大陆崛起", summary: "希腊大陆武士贵族以黄金面具昭示新权力中心。", detail: { background: "锡拉喷发后克里特势力衰退，希腊大陆诸邦借吸收米诺斯技术兴起。", process: "迈锡尼圆墓圈A、B的竖穴墓出土大量金器、镶嵌短剑与「阿伽门农面具」（实早于特洛伊传统年代），显示王室墓葬与远程金属贸易。", impact: "迈锡尼取代克诺索斯成为爱琴海主导力量，其宫殿、文字与军事组织为荷马史诗中的「亚该亚人」世界提供历史内核。", figures: ["施里曼（1876年发掘者）"], place: "迈锡尼与梯林斯（今希腊伯罗奔尼撒）", state: "迈锡尼希腊", sources: ["施里曼《迈锡尼》发掘报告", "《剑桥古代史》第2卷爱琴海章"], tags: ["迈锡尼", "竖穴墓", "黄金面具"] }, related: [] },
  { id: "world--b1600--s01", track: "world", year: -1600, yearApprox: true, dim: "science", weight: 4, title: "线形文字B记录希腊语", summary: "宫殿书吏以音节文字登记羊只、织物与战车零件。", detail: { background: "克里特线形文字A未破译，迈锡尼人改造其音节符号书写早期希腊语。", process: "克诺索斯与皮洛斯泥板（约前1450—前1200抄本，其创制传统上溯17世纪）以87个音节符加限定符记账；1952年文特里斯据重复词干破译，证明所记为希腊语。", impact: "这是欧洲最早的文字之一，其档案使迈锡尼的宫殿经济、神名与职官可考，也确立了希腊语在印欧语系中的早期位置。", figures: ["文特里斯", "查德威克（牛津大学）"], place: "克诺索斯与皮洛斯（今希腊）", state: "迈锡尼希腊", sources: ["文特里斯与查德威克《破译线形文字B》（1973）", "皮洛斯泥板汇编（塔、特恩诸集）"], tags: ["线形文字B", "破译", "音节文字"] }, related: [] },
  { id: "world--b1600--e01", track: "world", year: -1600, yearApprox: true, dim: "economy", weight: 3, title: "凯尔玛王国与努比亚黄金路", summary: "尼罗河第四瀑布的努比亚政权掌控黄金与畜群。", detail: { background: "瓦迪阿拉巴特等干河通往埃及金矿，谁控扼南端即控金源。", process: "凯尔玛（今苏丹栋古拉附近）以巨大泥砖「德福法」礼坛、随葬数千头牛并输入埃及奢侈品著称，其墓葬出土大量被掠或购入的埃及器物。", impact: "凯尔玛长期作为埃及南方对手存在，其黄金、畜群与兵源（努比亚弓手）此后被新王国直接纳入埃及财政与军队。", figures: ["雷斯纳（凯尔玛发掘者）"], place: "凯尔玛（今苏丹北部）", state: "凯尔玛王国", sources: ["雷斯纳《凯尔玛》发掘报告", "《剑桥非洲历史》第1卷"], tags: ["凯尔玛", "黄金贸易", "努比亚"] }, related: [] },
  { id: "world--b1600--a01", track: "world", year: -1600, yearApprox: true, dim: "art", weight: 2, title: "斯堪的纳维亚岩画与北欧青铜", summary: "挪威与瑞典海岸刻船、猎人与犁耕图像。", detail: { background: "北欧青铜时代社会以铜锡输入与本地琥珀、毛皮出口换取金属。", process: "坦姆、阿勒富萨等岩画以凿刻出双层龙骨船、持斧武士、犁与太阳圆盘车，年代约前1800—前500，本条取其早期密集阶段。", impact: "这些图像是研究无文字北欧社会航海、祭祀与农业的唯一直观材料，也显示青铜时代欧洲已存在贯通地中海与北海的交换链。", figures: ["福特（岩画记录者，19世纪）"], place: "挪威与瑞典西部海岸", state: "北欧青铜时代社会", sources: ["《剑桥北欧史》前史部分", "瑞典国家遗产委员会岩画数据库"], tags: ["岩画", "北欧青铜", "船形图像"] }, related: [] },
  { id: "world--b1595--m01", track: "world", year: -1595, yearApprox: true, dim: "military", weight: 4, title: "赫梯穆尔西里一世劫巴比伦", summary: "安纳托利亚军队长途奔袭终结古巴比伦王朝。", detail: { background: "赫梯需打通叙利亚商路，巴比伦第一王朝此时已衰。", process: "年表记约前1595年（学界推定）穆尔西里一世沿幼发拉底南下，破巴比伦、掠金像与「马尔杜克神像」，回程经哈拉勃尔；其随后死于宫廷政变。", impact: "此役使两河进入加喜特与海地王朝并立的时代，也说明战车与步兵混合的安纳托利亚军队具备超越距离的打击能力。", figures: ["穆尔西里一世", "沙姆苏-迪塔纳（巴比伦末王）"], place: "巴比伦与叙利亚（今伊拉克、叙利亚）", state: "赫梯王国", sources: ["「穆尔西里一世年表」（赫梯编年丛刊）", "《巴比伦王表》A本"], tags: ["奔袭", "巴比伦陷落", "战车军"] }, related: [] },
  { id: "world--b1575--p01", track: "world", year: -1575, yearApprox: true, dim: "politics", weight: 3, title: "加喜特人统治巴比伦", summary: "山地族群建近四百年王朝，纳两河入「喀什图」秩序。", detail: { background: "赫梯破巴比伦后权力真空，扎格罗斯山麓的加喜特人顺势入主。", process: "加喜特诸王以「巴比伦与苏美尔之王」自称，重修神庙、恢复灌溉，把土地分封给「贝勒·巴哈利」等家族，并以外交联姻与埃及、赫梯往来（阿玛尔纳书信可见）。", impact: "该王朝使巴比伦宗教与书吏传统渡过崩溃期，其分封制与界石制度为后世两河土地法留下深远印记。", figures: ["阿古姆·卡克里默", "布尔纳-布里亚什二世"], place: "巴比伦与杜尔·库里加尔祖（今伊拉克）", state: "加喜特巴比伦", sources: ["加喜特王室题记与界石（《古代近东文献》选译）", "《剑桥古代史》第2卷"], tags: ["加喜特", "分封制", "王朝延续"] }, related: [] },
  { id: "world--b1550--p01", track: "world", year: -1550, yearApprox: true, dim: "politics", weight: 4, title: "雅赫摩斯一世收复阿瓦里斯", summary: "底比斯王逐出喜克索斯，开启新王国。", detail: { background: "卡摩斯自上埃及北伐，与阿瓦里斯的喜克索斯王互递侮辱性书信。", process: "约前1550年（学界推定）雅赫摩斯攻陷阿瓦里斯、追至沙鲁亨围城三年，三角洲重归埃及；士兵埃尔-卡布的自传铭刻其战功与「掳俘」记录。", impact: "驱逐外族王朝的记忆使埃及转向军事化与对外扩张，催生新王国的常备军、叙利亚政策与法老军功图像传统。", figures: ["雅赫摩斯一世", "卡摩斯", "埃尔-卡布（士兵自传作者）"], place: "阿瓦里斯与底比斯（今埃及泰勒达巴、卢克索）", state: "古埃及（第十八王朝）", sources: ["埃尔-卡布墓自传铭文", "《剑桥古代史》第2卷"], tags: ["驱逐喜克索斯", "新王国", "军功铭文"] }, related: [] },
  { id: "world--b1525--i01", track: "world", year: -1525, yearApprox: true, dim: "institution", weight: 4, title: "《特尔皮努敕令》定王位继承", summary: "赫梯以成文法确立长子继承并限制政治杀戮。", detail: { background: "赫梯早期王位屡由政变与血仇更替，宫廷内斗消耗国力。", process: "特尔皮努敕令规定王位由长子依次继承，无子则取长子之妻所生孙，再不行由王后与贵族会议择子；禁止「刃血相仇」，对废王亲属仅施放逐而非屠戮。", impact: "这是已知最早以成文法解决王位继承的尝试之一，其「王与贵族会议（潘卡）」共治原则成为赫梯政体的显著特征。", figures: ["特尔皮努"], place: "哈图沙（今土耳其博阿兹柯伊）", state: "赫梯王国", sources: ["《特尔皮努敕令》赫梯语与阿卡德语本（《古代近东文献》选译）", "霍夫纳尔《赫梯制度史》"], tags: ["继承法", "贵族会议", "赫梯政制"] }, related: [] },
  { id: "world--b1504--p01", track: "world", year: -1504, yearApprox: true, dim: "politics", weight: 4, title: "哈特谢普苏特摄政称王", summary: "王后以「法老」身份统治埃及二十余年。", detail: { background: "图特摩斯二世早逝，嗣子图特摩斯三世年幼，阿蒙祭司集团支持王室女性。", process: "哈特谢普苏特先以「摄政」名义行事，后取完整王衔、像男性法老形象，并记阿蒙神「亲选」其统治；其在位期间停止大规模征伐、专注神庙与贸易。", impact: "她是埃及史上最有实权的统治者之一，其被后世除名（阿蒙霍特普二世晚年抹去其名与像）也是研究古代政治记忆删除的著名个案。", figures: ["哈特谢普苏特", "图特摩斯三世", "塞内穆特（其建筑师）"], place: "底比斯（今埃及卢克索西岸）", state: "古埃及（第十八王朝）", sources: ["代尔巴赫里神庙铭文与浮雕", "《剑桥古代史》第2卷"], tags: ["女性法老", "摄政", "记忆删除"] }, related: [] },
  { id: "world--b1500--c01", track: "world", year: -1500, yearApprox: true, dim: "culture", weight: 5, title: "《梨俱吠陀》的编集", summary: "印欧移民颂诗辑于旁遮普，厘为梵语圣典。", detail: { background: "印度-雅利安部落以口传诵诗维持祭祀与族群认同，「吠陀」意为知识。", process: "学界多据语言与天文线索把《梨俱吠陀》核心篇章的编订定在约前1500—前1200年；全书1028颂、以因陀罗、阿耆尼、伐楼拿崇拜为主，另见《阿闼婆吠陀》等后出。", impact: "吠陀文献成为婆罗门教与印度教的神学、种姓与仪式根源，其口传精确性（音素转写与叠诵法）影响印度语言学与佛教、耆那教的话语文传统。", figures: ["不可考的吠陀诵者（「先知」利希传统）"], place: "七河流域与旁遮普（今巴基斯坦与印度西北）", state: "吠陀时代诸部", sources: ["《梨俱吠陀》梵文本与全译本", "《剑桥印度史》第1卷（吠陀时期章）"], tags: ["梨俱吠陀", "梵语", "口传"] }, related: [] },
  { id: "world--b1500--m01", track: "world", year: -1500, yearApprox: true, dim: "military", weight: 2, title: "吠陀马祭与战车武士", summary: "以马祭与车战仪式确立雅利安贵族的军事宗教秩序。", detail: { background: "游牧—半游牧的雅利安部落需以仪式把征服与牲畜再分配合法化。", process: "《梨俱吠陀》与《百道梵书》所述「阿什瓦梅达」（马祭）放走祭马随军征逐，另「拉贾苏耶」即位祭以战利品与马群献祭，战车（拉塔）为贵族身份标志。", impact: "马祭把军事掠夺纳入祭祀体系，形成「武士—祭司」共生的印度上层结构，其仪轨在后世王国政治中反复复活。", figures: ["不可考的吠陀祭司"], place: "印度西北部", state: "吠陀时代诸部", sources: ["《百道梵书》译本（哈木丛刊）", "《剑桥印度史》第1卷"], tags: ["马祭", "战车", "武士贵族"] }, related: [] },
  { id: "world--b1473--p01", track: "world", year: -1473, yearApprox: true, dim: "politics", weight: 3, title: "图特摩斯三世独揽王权", summary: "受抑二十年的「古代拿破仑」，始远征叙利亚。", detail: { background: "哈特谢普苏特去世后，图特摩斯三世以「阿蒙之鹰」为名重掌军政。", process: "其在位第22年至42年间至少十七次进入叙利亚-巴勒斯坦，立《年卡勒》编年于卡纳克，把埃及边界推到幼发拉底，并接受米坦尼以外诸邦纳贡。", impact: "此期埃及建立首个海外帝国，设附庸王、驻军与贡赋网，其国际体系与赫梯、巴比伦、亚述并立为近东「大国俱乐部」。", figures: ["图特摩斯三世", "米坦尼王帕拉塔纳"], place: "卡纳克与叙利亚诸城", state: "古埃及（第十八王朝）", sources: ["图特摩斯三世年卡勒编年（卡纳克铭刻，照像刊本）", "《剑桥古代史》第2卷"], tags: ["帝国扩张", "编年铭文", "附庸制"] }, related: [] },
  { id: "world--b1470--x01", track: "world", year: -1470, yearApprox: true, dim: "explore", weight: 4, title: "哈特谢普苏特的蓬特远航", summary: "五艘大船自红海出发，载回乳香树与黑人酋长。", detail: { background: "乳香没药为神庙焚祭必需，埃及本土无法种植。", process: "代尔巴赫里神庙浮雕绘船队（约五艘、每艘水手数十至二百余人）绕行今厄立特里亚一带，记蓬特后妃「体型硕大」，运回活乳香树三十株、没药、象牙、黑檀与狒狒。", impact: "这是有图像与文字实录的最早远洋国家探险之一，其航线与「蓬特」地望（今厄立特里亚—索马里或苏丹东岸）至今是非洲与埃及史研究焦点。", figures: ["哈特谢普苏特", "尼赫西（远征队长）"], place: "红海航路与蓬特（今厄立特里亚一带）", state: "古埃及（第十八王朝）", sources: ["代尔巴赫里蓬特浮雕与铭文（导航刊本）", "《剑桥古代史》第2卷"], tags: ["蓬特", "红海航路", "乳香"] }, related: [] },
  { id: "world--b1457--m01", track: "world", year: -1457, yearApprox: true, dim: "military", weight: 4, title: "美吉多战役", summary: "埃及军穿越险径突袭，击败叙利亚-迦南联军。", detail: { background: "卡叠什为首的诸邦在美吉多结盟反埃及，联军约万人。", process: "图特摩斯三世亲率约2个师（学界估算1—2万人）经阿鲁纳窄道一日行军，以「中军如鹰、两翼如影」布阵破城；卡纳克年录记俘获战车924辆、金银器与粮谷万计。", impact: "此役确立埃及对巴勒斯坦与腓尼基的统治，被学界视为历史上第一场有较完整战术记载的会战，七年后进贡制度化。", figures: ["图特摩斯三世", "美吉多王"], place: "美吉多（今以色列北部基布兹）", state: "古埃及（第十八王朝）", sources: ["卡纳克《年卡勒》美吉多段（普里查德编《古代近东文献》选译）", "《剑桥古代史》第2卷"], tags: ["美吉多", "会战", "进贡体系"] }, related: [] },
  { id: "world--b1450--i01", track: "world", year: -1450, yearApprox: true, dim: "institution", weight: 3, title: "埃及设「库施之王子」总督", summary: "以王室要员直辖努比亚，行埃及税制与神庙体系。", detail: { background: "新王国需稳定取得金矿、畜源与兵源，仅靠堡垒线不足。", process: "图特摩斯三世后确立「库施之王子」官职，驻安巴/博亨，掌第二至第四瀑布间的贡赋、司法与驻军，另设「库施秘书」官监督诸州；埃及式神庙与移民城镇随之而建。", impact: "这套殖民式行政把努比亚纳入埃及经济与宗教圈逾四百年，为后来库施王国反向征服埃及（第二十五王朝）准备了文化条件。", figures: ["不可考的库施总督"], place: "努比亚（今苏丹北部与埃及南部）", state: "古埃及（第十八王朝）", sources: ["库施总督墓葬与题记（塞加拉、安巴出土）", "《剑桥非洲历史》第2卷"], tags: ["总督制", "努比亚", "殖民行政"] }, related: [] },
  { id: "world--b1450--a01", track: "world", year: -1450, yearApprox: true, dim: "art", weight: 2, title: "卡纳克节年厅的动植物图谱", summary: "浮雕以写实手法记录叙利亚带回的异兽与植物。", detail: { background: "远征战利品需以图像入庙献神，兼作王功档案。", process: "图特摩斯三世「植物厅」浮雕刻出约二百余种动植物，包括学界争论的猴子、长角牛、骆驼与多种树木，部分为活体移植后写生。", impact: "这是古代最接近博物志的图像记录，为复原青铜时代西亚—东非物种分布与家畜史提供了独特证据。", figures: ["图特摩斯三世"], place: "卡纳克神庙（今埃及卢克索）", state: "古埃及（第十八王朝）", sources: ["卡纳克植物厅浮雕刊本（《叙利亚与埃及的年代志》相关研究）", "《剑桥古代史》第2卷"], tags: ["博物图像", "浮雕", "战利品记录"] }, related: [] },
  { id: "world--b1450--s01", track: "world", year: -1450, yearApprox: true, dim: "science", weight: 3, title: "埃及玻璃料与彩釉容器", summary: "以核心缠绕法生产多彩小瓶，成为外交奢侈品。", detail: { background: "彩釉与玻璃原料（硅、碱、铜钴着色）需从沙漠与近东取得。", process: "新王国作坊以耐火芯缠玻璃料条再划纹，出土带铭文玻璃碗与窑址（如马尔卡塔、尼姆鲁德后续发现）；阿玛尔纳书信记埃及向巴比伦「遣玻璃匠」。", impact: "玻璃器成为近东外交礼物的通货，其工艺经腓尼基与罗马传布，是古代技术扩散与国家手工业结合的范例。", figures: ["不可考的玻璃匠"], place: "底比斯与马尔卡塔工坊（今埃及）", state: "古埃及（第十八王朝）", sources: ["《剑桥古代技术史》第1卷", "沙勒《古代玻璃史》"], tags: ["玻璃工艺", "奢侈品贸易", "手工业"] }, related: [] },
  { id: "world--b1440--c01", track: "world", year: -1440, yearApprox: true, dim: "culture", weight: 3, title: "埃及王室编年史的传统", summary: "以「年卡勒」体例逐年记王功，开编年史书写。", detail: { background: "神庙需按年登记祭祀与战功，形成官方记事系统。", process: "图特摩斯三世「岁名书吏」逐年刻功；同期《阿拜多斯王表》《都灵王表》以世系列出诸王在位年数，《阿尼斯副本》则把天文与政事并记。", impact: "这套编年与王表传统是埃及年代学的骨架，也说明古代国家如何以历史书写服务合法性。", figures: ["不可考的岁名书吏"], place: "卡纳克与阿拜多斯（今埃及）", state: "古埃及（第十八王朝）", sources: ["阿拜多斯王表与都灵王表刊本", "《剑桥古代史》第2卷"], tags: ["编年史", "王表", "年代学"] }, related: [] },
  { id: "world--b1425--s01", track: "world", year: -1425, yearApprox: true, dim: "science", weight: 3, title: "埃及水钟与对角星表", summary: "以漏壶与恒星偕落时刻划分夜间十二小时。", detail: { background: "夜间祭祀与礼仪需可计时的手段，季节不同夜长亦变。", process: "阿蒙霍特普三世水钟（卡纳克出土）内壁刻不同月份的水位刻度线；更早的「对角星表」以36组恒星的偕落时刻定夜之十二刻，见于棺盖。", impact: "这些记录使埃及拥有可分割的均匀时间单位，其小时概念经希腊、罗马传入欧洲，是时间计量史的起点之一。", figures: ["不可考的神庙天文书吏"], place: "底比斯与卡纳克（今埃及）", state: "古埃及（第十八王朝）", sources: ["《古代埃及天文历法》（帕克）", "卡纳克水钟铭文刊本"], tags: ["水钟", "星表", "时间计量"] }, related: [] },
  { id: "world--b1400--s01", track: "world", year: -1400, yearApprox: true, dim: "science", weight: 5, title: "赫梯的炼铁垄断", summary: "安纳托利亚改块炼铁为战略商品与外交筹码。", detail: { background: "锡路不稳与铜价高昂促使高原诸国开发铁矿（褐铁矿、磁铁矿丰富）。", process: "赫梯文本记「好铁」与铁匠（「铁匠之神」崇拜），并以铁为礼物赠埃及、亚述；渗碳与反复锻打去渣工艺使刃口可硬化。", impact: "铁器打破青铜对武器供给的限制，随赫梯崩溃技师流散，铁器普及到黎凡特与希腊，直接促成铁器时代的农业与军事扩散。", figures: ["不可考的赫梯铁匠"], place: "哈图沙与安纳托利亚（今土耳其）", state: "赫梯王国", sources: ["赫梯铁器与「铁匠之神」文献（《古代近东文献》选译）", "穆尔韦《铁器时代的起源》"], tags: ["炼铁", "技术垄断", "铁器时代"] }, related: [] },
  { id: "world--b1400--p01", track: "world", year: -1400, yearApprox: true, dim: "politics", weight: 3, title: "米坦尼王国与胡里安秩序", summary: "两河上游的胡里安-印欧贵族政权与埃及平分叙利亚。", detail: { background: "赫梯南侵后留下的幼发拉底以东真空由米坦尼填补，其统治层含印度-雅利安名号。", process: "米坦尼王图什拉塔与阿蒙霍特普三世、阿肯那顿联姻通使（阿玛尔纳书信存其文），并与赫梯反复争夺阿勒颇与穆克什；后为赫梯与亚述夹击而亡。", impact: "米坦尼把胡里安语言、神话（《吉尔伽美什》胡里安改编本）与马术技术传遍近东，其灭亡使亚述获得向叙利亚扩张的机会。", figures: ["图什拉塔", "沙图瓦拉萨"], place: "米坦尼（今叙利亚东北与伊拉克北部）", state: "米坦尼王国", sources: ["阿玛尔纳书信米坦尼件（普里查德编《古代近东文献》选译）", "《剑桥古代史》第2卷"], tags: ["米坦尼", "联姻外交", "胡里安"] }, related: [] },
  { id: "world--b1400--c01", track: "world", year: -1400, yearApprox: true, dim: "culture", weight: 3, title: "波伽兹科约马术文本", summary: "胡里安驭者基库里文以梵语借词记驯马与医马。", detail: { background: "战车技术需系统的驯马与兽医知识，米坦尼以此闻名。", process: "赫梯档案库中存「基库里」驯马文与兽医文，含「玛丽亚（马）」等印度-雅利安语词与数字、颜色术语，另有条约所书「因陀罗、密特拉、纳萨提亚」神名。", impact: "该文本是印度-雅利安语言与文化西传的最直接证据，也证明古代近东已有专门化的技术写作与职业知识共同体。", figures: ["基库里（胡里安驭者）"], place: "波伽兹科伊（古哈图沙）档案库", state: "赫梯王国", sources: ["波伽兹科伊文本丛刊基库里条", "《剑桥古代史》第2卷"], tags: ["驯马术", "印度-雅利安语", "技术文献"] }, related: [] },
  { id: "world--b1400--i01", track: "world", year: -1400, yearApprox: true, dim: "institution", weight: 2, title: "加喜特界石「库杜鲁」与免赋令", summary: "以刻神符的石界记土地赠与并免除徭役。", detail: { background: "王室赏田需永久性凭证，并防止地方官重复征调。", process: "库杜鲁石正面刻田亩四至、受赠人与诸神符记，背面为诅咒条文（违令者遭神罚），并规定该地免「努杜」徭役与「马德科」税。", impact: "界石制度保存了加喜特至巴比伦时期的土地法与税制细节，其「神符+诅咒」的凭证形式影响了叙利亚与巴勒斯坦的立石传统。", figures: ["不可考的加喜特王室书吏"], place: "巴比伦与苏萨（今伊拉克、伊朗）", state: "加喜特巴比伦", sources: ["卢浮宫与大英博物馆库杜鲁馆藏刊本", "《古代近东文献》界石铭文选译"], tags: ["界石", "免赋", "土地法"] }, related: [] },
  { id: "world--b1370--p01", track: "world", year: -1370, yearApprox: true, dim: "politics", weight: 3, title: "阿玛尔纳外交档案", summary: "近东诸王以阿卡德语互派使节、通婚与索金。", detail: { background: "「大国俱乐部」需一套超越各族语言的外交书面语，阿卡德语成通用。", process: "1887年阿玛尔纳出土约380块泥板（今分藏柏林、伦敦等），内容为巴比伦、亚述、米坦尼、阿勒颇与迦南城邦诸王致埃及法老的书信，涉及联姻、黄金配额与「箭与使节」的护送。", impact: "这批档案是研究前14世纪国际体系的第一手材料，其「兄弟相称」的平等外交与礼品—贡赋交换模式为后世帝国条约制度提供雏形。", figures: ["阿蒙霍特普三世", "巴比伦王布尔纳-布里亚什二世"], place: "阿玛尔纳（今埃及泰勒阿马尔纳）", state: "古埃及（第十八王朝）", sources: ["阿玛尔纳书信刊本（「E.A.」编号）与译注", "莫拉利《阿玛尔纳书信集》"], tags: ["外交文书", "阿卡德语", "国际体系"] }, related: [] },
  { id: "world--b1353--c01", track: "world", year: -1353, yearApprox: true, dim: "culture", weight: 4, title: "阿肯那顿的阿顿改革", summary: "以日轮神阿顿独尊取代阿蒙神系，关闭诸神庙。", detail: { background: "阿蒙祭司集团掌握大量地产与官僚网络，法老需夺回财源。", process: "约前1353年（学界推定）阿蒙霍特普四世改名阿肯那顿，封闭阿蒙神庙、抹去「阿蒙」字样，独奉可见于日轮的阿顿；《阿顿大颂诗》为其神学文本（与《诗篇》104篇的关联学界长期讨论）。", impact: "这场改革在法老死后即被推翻，但其一神倾向、颂诗文体与自然主义艺术对叙利亚宗教文学及后世一神教研究构成重要参照。", figures: ["阿肯那顿", "纳芙蒂蒂", "阿伊"], place: "底比斯与新都阿赫塔吞（今埃及）", state: "古埃及（第十八王朝）", sources: ["《阿顿大颂诗》岩刻本（普里查德编《古代近东文献》选译）", "《剑桥古代史》第2卷"], tags: ["阿顿", "一神倾向", "宗教改革"] }, related: [] },
  { id: "world--b1350--p01", track: "world", year: -1350, yearApprox: true, dim: "politics", weight: 3, title: "迁都阿赫塔吞", summary: "新建王都于未垦空地，以摆脱旧神庙势力。", detail: { background: "底比斯的阿蒙祭司与贵族网络使改革难以推行。", process: "界碑铭文宣告阿顿「亲自划定」新都，速建宫殿、神庙与官署，面积约6平方公里；阿玛尔纳村（工人墓）出土数百具骨架显示高强度劳动与营养不良、骨折与畸形。", impact: "该城建成后约二十年即被废弃，成为研究古代「计划都城」与王室劳工体制的独特个案，其遗存支撑了阿玛尔纳艺术的全部材料。", figures: ["阿肯那顿", "帕伊（维齐尔）"], place: "阿赫塔吞（今埃及泰勒阿马尔纳）", state: "古埃及（第十八王朝）", sources: ["阿玛尔纳界碑铭文刊本", "阿玛尔纳皇家墓葬与工人墓发掘报告"], tags: ["迁都", "界碑", "王室劳工"] }, related: [] },
  { id: "world--b1345--a01", track: "world", year: -1345, yearApprox: true, dim: "art", weight: 3, title: "阿玛尔纳的自然主义", summary: "浮雕与壁画写法老为育儿之父而非神祇。", detail: { background: "新教义要求艺术表现「阿顿之下真实的人」，突破千年程式。", process: "浮雕出现阿肯那顿抱女、与纳芙蒂蒂共食、家庭场景；人物造型拉长头型、宽腹、细肢，色彩鲜艳，彩塑与镶嵌工艺发达。", impact: "这场约二十年的风格革命是古代艺术史上最鲜明的「反程式」实验，其消亡与复辟也证明艺术风格与意识形态的绑定关系。", figures: ["图特摩斯（王宫雕刻师）", "阿肯那顿"], place: "阿玛尔纳雕塑家作坊（今埃及）", state: "古埃及（第十八王朝）", sources: ["阿玛尔纳「雕刻家作坊」出土品报告（含未完成的纳芙蒂蒂像）", "罗伯斯《埃及艺术》"], tags: ["阿玛尔纳艺术", "自然主义", "宫廷雕刻"] }, related: [] },
  { id: "world--b1332--a01", track: "world", year: -1332, yearApprox: true, dim: "art", weight: 4, title: "图坦卡蒙墓的发现", summary: "帝王谷唯一近乎完整的法老墓出土五千余件器物。", detail: { background: "阿玛尔纳复辟后的短命幼王，其墓因规模小、被堆土遮蔽而免盗。", process: "1922年11月卡特在帝王谷KV62发现四级堆叠的墓室，出土5398件登记品，含金棺三重（内层纯金约110公斤）、战车、座椅与食物；1925年11月开棺。", impact: "此次发掘成为现代考古学与公共传播的里程碑，其器物组合为复原新王国宫廷工艺、宗教与物质文化提供了基准标本。", figures: ["卡特", "卡纳冯勋爵", "图坦卡蒙"], place: "帝王谷KV62（今埃及卢克索西岸），藏开罗博物馆", state: "古埃及（第十八王朝）", sources: ["卡特与福斯《图坦卡蒙之墓》发掘报告", "开罗博物馆图坦卡蒙藏品目录"], tags: ["图坦卡蒙", "帝王谷", "考古发现"] }, related: [] },
  { id: "world--b1330--s01", track: "world", year: -1330, yearApprox: true, dim: "science", weight: 3, title: "图坦卡蒙墓的金工与鎏金", summary: "以锤揲、镶嵌、玻璃料与失蜡鎏金达成极高纯度工艺。", detail: { background: "王室作坊集中全国匠人，工艺配方由神庙作坊传承。", process: "面具以两层金片锤揲接合、镶嵌青金石与彩色玻璃料；刀、剑为锻打青铜含微量砷；家具以金箔贴附乌木并以玻璃料条装饰，分析显示金纯度约22K。", impact: "这批器物成为判断古代冶金与材料工艺的实验室，其成分分析也为复原埃及—努比亚—近东的黄金与青金石来源提供了数据。", figures: ["不可考的王室匠师"], place: "帝王谷KV62（今埃及）", state: "古埃及（第十八王朝）", sources: ["图坦卡蒙文物材料分析科学报告", "开罗博物馆馆藏记录"], tags: ["鎏金", "合金分析", "工艺"] }, related: [] },
  { id: "world--b1325--s01", track: "world", year: -1325, yearApprox: true, dim: "science", weight: 3, title: "图坦卡蒙的陨铁短剑", summary: "以高镍铁质的陨铁打制刃器，铁比黄金更贵。", detail: { background: "前14世纪铁极少见，埃及文献称铁为「来自天空的金属」。", process: "墓中两柄短剑之一为铁刃金鞘；2016年X射线荧光分析显示高镍与钴成分与铁陨石一致，刃部含石灰石质护面。", impact: "此器证明早于赫梯铁器普及期，地中海东部已能加工块状陨铁，也解释了为何铁在近东最初作为王室礼器而非工具。", figures: ["达尼莱等（米兰理工与开罗大学分析组）"], place: "帝王谷KV62（今埃及），藏开罗博物馆", state: "古埃及（第十八王朝）", sources: ["《陨石学与行星科学》相关论文（2016）", "开罗博物馆铁刃短剑馆藏记录"], tags: ["陨铁", "早期冶铁", "材料分析"] }, related: [] },
  { id: "world--b1322--p01", track: "world", year: -1322, yearApprox: true, dim: "politics", weight: 3, title: "霍朗赫布复辟阿蒙正统", summary: "将军出身的法老系统清除阿玛尔纳遗产。", detail: { background: "阿肯那顿死后出现阿伊等短暂过渡，军人与阿蒙祭司结盟。", process: "霍朗赫布以「阿蒙所立」自居，重新开放神庙、把税入归还神产，并以《卡纳克王表》删去「异端」诸王之名；其《行政敕令》整肃地方税吏与军队占田。", impact: "这次复辟终结了阿玛尔纳时代，其反腐与军政改革诏令是研究新王国末期国家治理与官纪的重要法文。", figures: ["霍朗赫布", "阿伊"], place: "底比斯与孟菲斯（今埃及）", state: "古埃及（第十八王朝）", sources: ["霍朗赫布《阿什莫林/都灵》刑法铭文（《古代近东文献》选译）", "《剑桥古代史》第2卷"], tags: ["复辟", "行政敕令", "反腐"] }, related: [] },
  { id: "world--b1300--p01", track: "world", year: -1300, yearApprox: true, dim: "politics", weight: 3, title: "第十九王朝与皮拉美西斯新都", summary: "三角洲新都以王名命名，重心北移近叙利亚。", detail: { background: "埃及需更接近叙利亚前线与陆海商路，底比斯过于靠南。", process: "拉美西斯二世（约前1279年即位，学界推定）在阿瓦里斯故地扩建「皮拉美西斯-梅里阿蒙」，设王宫、军械坊、阿斯塔特与塞特神庙；发掘出土大量近东式彩陶与工坊。", impact: "该都的考古（今卡提纳、泰勒达巴）为复原新王国军事工业、多族群居民与国际贸易提供了最重要实例。", figures: ["拉美西斯二世"], place: "皮拉美西斯（今埃及卡提纳、泰勒达巴）", state: "古埃及（第十九王朝）", sources: ["皮拉美西斯发掘报告（德国考古研究所开罗分所）", "《剑桥古代史》第2卷"], tags: ["迁都", "军械坊", "多族群城市"] }, related: [] },
  { id: "world--b1290--m01", track: "world", year: -1290, yearApprox: true, dim: "military", weight: 3, title: "埃及军的外族编制", summary: "以沙苏、谢尔丹与利比亚人组成独立旗队。", detail: { background: "常年对外用兵使本国征兵不足，俘虏与雇佣成为主要补充。", process: "文献与军营名单记「沙苏游牧民」「谢尔丹（撒丁？）海上民」「卢卡人」编入各师，佩本族兵器、由本族首领统领，另设「弓箭手兵团」与努比亚「麦德查伊」警备队。", impact: "这种以族群为单位的雇佣编组既强化王军，也在第三中间期使外族军事首领得以割据，成为国家分裂的伏笔。", figures: ["不可考的外族军团首领"], place: "埃及各师驻地（今尼罗河三角洲与底比斯）", state: "古埃及（第十九王朝）", sources: ["拉美西斯二世军队名册与神庙浮雕题记", "《剑桥古代史》第2卷军事章"], tags: ["雇佣军", "族群编制", "军制"] }, related: [] },
  { id: "world--b1285--a01", track: "world", year: -1285, yearApprox: true, dim: "art", weight: 4, title: "阿布辛贝勒岩窟神庙", summary: "四尊20米坐像凿入努比亚山崖，迁建于水库之侧。", detail: { background: "拉美西斯二世需在努比亚宣示神化王权并压服当地。", process: "大庙深约65米，圣所四神（拉-哈拉赫提、阿蒙、神化的拉美西斯、普塔）并坐；每年两次（学界认为约2月与10月）晨光入照三像，形成著名的「日光节」现象，1960年代整体切割抬升迁移。", impact: "该庙是岩石开凿技术与太阳历观测结合的杰作，其国际抢救工程也成为现代文化遗产保护制度的起点。", figures: ["拉美西斯二世", "尼斐尔泰丽"], place: "阿布辛贝勒（今埃及阿斯旺南，纳赛尔湖岸）", state: "古埃及（第十九王朝）", sources: ["阿布辛贝勒迁移与天文研究（霍金斯等）", "联合国教科文组织努比亚抢救工程报告"], tags: ["岩窟庙", "日照现象", "遗产迁移"] }, related: [] },
  { id: "world--b1274--m01", track: "world", year: -1274, yearApprox: true, dim: "military", weight: 5, title: "卡迭什战役", summary: "埃及与赫梯为叙利亚霸权决战，双方皆称胜利。", detail: { background: "穆瓦塔里二世支持穆克什、阿勒颇倒向赫梯，埃及北上争夺奥龙特斯河渡口。", process: "拉美西斯二世第四年（约前1274年）率四师渡河，因俘虏诈供而轻进；赫梯以约2500—3500乘战车自河湾突袭「拉师」，埃及靠沙苏步兵与增援稳住阵线，当日不解而退。", impact: "这是战车会战在历史上最后一次决定性表演，双方各以碑铭与浮雕宣扬己胜，成为研究古代战报宣传与史实差异的经典案例。", figures: ["拉美西斯二世", "穆瓦塔里二世", "沙尔-米苏纳（赫梯统帅）"], place: "奥龙特斯河畔卡迭什（今叙利亚卡塔纳附近）", state: "古埃及（第十九王朝）", sources: ["卡迭什「公报」与「诗」普里查德编《古代近东文献》选译", "赫梯方面书信与编年残片"], tags: ["卡迭什", "战车会战", "战报宣传"] }, related: [] },
  { id: "world--b1274--a01", track: "world", year: -1274, yearApprox: true, dim: "art", weight: 3, title: "卡迭什战图的纪念碑传播", summary: "同一战役以诗、公报与浮雕，屡刻于十余处神庙。", detail: { background: "王权需把险胜转化为可反复观看的功绩叙事。", process: "「卡迭什诗」与散文「公报」并存，卢克索、卡纳克、阿拜多斯、阿布辛贝勒等处以不同版式刻画渡河、突袭与王身先士卒的场景，构图常呈半圆形包围。", impact: "这种「同一事件的多媒介、多地复制」是世界上最早的官方向宣传体系之一，为研究古代政治传播提供完整样本。", figures: ["拉美西斯二世"], place: "底比斯与努比亚诸神庙（今埃及）", state: "古埃及（第十九王朝）", sources: ["卡迭什浮雕与铭文刊本（如卡纳克与阿布辛贝勒铭刻刊本）", "《剑桥古代史》第2卷"], tags: ["战图浮雕", "政治宣传", "多媒介"] }, related: [] },
  { id: "world--b1259--p01", track: "world", year: -1259, yearApprox: true, dim: "politics", weight: 5, title: "埃及-赫梯永久和约", summary: "现存最早成文国际和约，含互不侵犯与引渡条款。", detail: { background: "卡叠什后十五年，赫梯受亚述压力、埃及利比亚边患，双方需北线稳定。", process: "约前1259年（学界推定）拉美西斯二世与赫胡塔西里三世订立和约，埃及与赫梯两版本存世：条文规定互不侵犯、共同防御、引渡政治流亡者并予善待、王族互援；以千余神为誓。", impact: "该约近东首次以成文形式确立均势与条约义务，其银板副本与神庙刻本并存，成为国际法史与外交史的公认原点。", figures: ["拉美西斯二世", "赫胡塔西里三世"], place: "卡纳克与波伽兹科伊（埃及刻本与赫梯泥板本）", state: "赫梯王国", sources: ["和约埃及象形文本与赫梯泥板文本（全文对译刊本）", "联合国总部复刻本说明"], tags: ["和约", "引渡条款", "国际法起源"] }, related: [] },
  { id: "world--b1250--s01", track: "world", year: -1250, yearApprox: true, dim: "science", weight: 3, title: "赫梯的水坝与都城供水", summary: "以土石坝与石砌渠道蓄季节雨洪为城市水源。", detail: { background: "哈图沙地处干旱高原，人口数万需稳定饮水与灌溉。", process: "波伽兹科伊周边出土数座石砌与土心坝（如厄克帕尔、格勒塞坝），配泄洪道与刻有狮、斯芬克斯的「雅西耶卡尤」水渠，把水引入城内蓄池。", impact: "这批工程是青铜时代最大规模的水利坝群之一，其结构原理为后世近东与地中海蓄水池技术提供早期范本。", figures: ["不可考的赫梯水工"], place: "哈图沙周边（今土耳其博阿兹柯伊）", state: "赫梯王国", sources: ["土耳其水利考古调查（博阿兹柯伊坝群报告）", "《剑桥古代技术史》第1卷"], tags: ["水坝", "供水系统", "水利工程"] }, related: [] },
  { id: "world--b1250--a01", track: "world", year: -1250, yearApprox: true, dim: "art", weight: 3, title: "亚兹勒卡亚岩刻圣所", summary: "露天神祠以巨幅神像浮雕构成万神殿行列。", detail: { background: "赫梯宗教重山泉与露天崇拜，王室在圣所刻像祭祀。", process: "北廊浮雕为雷电神持双斧立于二狮之上，南廊为太阳女神与王室献祭图，另有神祇、山岳与武器行列共约65像，尺寸达数米。", impact: "它是安纳托利亚宗教艺术的顶峰，其图像母题（双头鹰、狮身人面、武器神）在赫梯灭亡后由叙利亚-安纳托利亚新赫梯诸国继续传承。", figures: ["不可考的赫梯雕刻匠"], place: "亚兹勒卡亚（今土耳其约兹加特附近）", state: "赫梯王国", sources: ["博阿兹柯伊与亚兹勒卡亚浮雕图录", "《伊朗与古代近东艺术》馆刊"], tags: ["岩刻", "万神殿", "宗教艺术"] }, related: [] },
  { id: "world--b1240--e01", track: "world", year: -1240, yearApprox: true, dim: "economy", weight: 4, title: "乌加里特的国际贸易", summary: "港城以铜、紫布、染料与中转税成为近东商都。", detail: { background: "乌加里特位于地中海东岸最便利泊点，与塞浦路斯铜区相对。", process: "档案（约1000余块泥板）记王室主导的「卡鲁姆」商区、锡与铜的定额征收、船队与保险式借贷，并显示其与埃及、克里特、迈锡尼、美索不达米亚同时通商，城内有胡里安、阿摩利、赫梯等外侨区。", impact: "这批文书使乌加里特成为古代国际贸易、法律与多语社会研究最完整的个案，其毁灭（约前1185）标志青铜世界体系的断裂。", figures: ["尼科马赫（末代王）", "阿穆鲁（其父，摄政）"], place: "乌加里特/拉沙姆拉（今叙利亚海岸）", state: "乌加里特城邦", sources: ["拉沙姆拉泥板刊本", "《乌加里特城的衰落与毁灭》"], tags: ["转口贸易", "外侨区", "商业文书"] }, related: [] },
  { id: "world--b1240--s01", track: "world", year: -1240, yearApprox: true, dim: "science", weight: 4, title: "乌加里特字母楔形文字", summary: "以30个符号的字母体系书写塞姆语，兼记胡里安语。", detail: { background: "音节楔形文字符号数千，商人阶层需易学易书的记音法。", process: "拉沙姆出土字母表泥板按「哈利夫」顺序排30符（后简化为22），把楔形刻法与西塞姆字母原则结合，用于本地行政与神话文本（巴力循环、凯列特史诗）。", impact: "这套体系是腓尼基-希伯来-希腊字母链条上的关键一环，字母表序（阿-贝-吉-德）与「以少量符号表音」的原理经此传入地中海全境。", figures: ["不可考的乌加里特书吏"], place: "乌加里特（今叙利亚拉沙姆拉）", state: "乌加里特城邦", sources: ["拉沙姆字母表泥板刊本", "曼《字母的起源》研究"], tags: ["字母楔形文字", "字母表序", "书写改革"] }, related: [] },
  { id: "world--b1220--c01", track: "world", year: -1220, yearApprox: true, dim: "culture", weight: 4, title: "《吉尔伽美什史诗》标准本", summary: "书吏校订十二泥板本，成为两河文学的经典定本。", detail: { background: "苏美尔短篇经数百年拼合，各地方本内容参差。", process: "学者传统归功尼尼微的书吏西诺-莱奇-乌尼尼，以「超越一切诸王」为篇首序语，把「他看见深渊」的十一表本加洪水篇成十二表；亚述巴尼帕抄本保存最完整。", impact: "史诗以友谊、死亡恐惧与追寻永生为主题，其洪水篇与大洪水传统成为研究希伯来《创世记》文学关系的核心文献。", figures: ["西诺-莱奇-乌尼尼（校订书吏）", "吉尔伽美什（传说中主人公）"], place: "尼尼微与巴比伦（今伊拉克）", state: "新巴比伦与亚述学术圈", sources: ["《吉尔伽美什史诗》标准本（乔治译注本）", "普里查德编《古代近东文献》选译"], tags: ["吉尔伽美什", "史诗校订", "洪水神话"] }, related: [] },
  { id: "world--b1212--p01", track: "world", year: -1212, yearApprox: true, dim: "politics", weight: 3, title: "麦伦普塔的以色列石碑", summary: "现存唯一提及「以色列」的埃及王碑。", detail: { background: "迦南诸城在叙利亚-巴勒斯坦反埃及暴动，法老北伐平乱。", process: "约前1208年（学界推定）麦伦普塔胜利碑以「以色列已荒、其种无存」入诗，同碑另列亚实基伦、基色、阿施陀罗等城；碑文为韵体战功文学。", impact: "此条是「以色列」一名最早的域外记载，其措辞与《出埃及》传统的有无被学界反复讨论，是圣经考古的基准铭文之一。", figures: ["麦伦普塔"], place: "底比斯（原碑藏开罗博物馆）", state: "古埃及（第十九王朝）", sources: ["以色列石碑铭文（《古代近东文献》选译）", "《剑桥古代史》第2卷"], tags: ["以色列石碑", "迦南", "最早记载"] }, related: [] },
  { id: "world--b1200--d01", track: "world", year: -1200, yearApprox: true, dim: "disaster", weight: 4, title: "前1200年前后的气候与粮荒", summary: "地中海东岸转干冷，歉收与饥荒连锁动摇宫殿体系。", detail: { background: "多源记录显示公元前13世纪末东地中海降水带南移、生长季缩短。", process: "阿玛尔纳与乌加里特书信有「年荒、民相食」之语；死海与加利利湖沉积、安纳托利亚树轮与格陵兰冰芯指示约前1250—前1100年的干冷段，同期赫梯属国断粮、埃及向赫梯运「谷物船」。", impact: "气候压力与粮荒使依赖再分配的宫殿经济难以应变，成为青铜时代晚期体系崩溃（连同迁徙、战争与断锡）的关键触发因素之一。", figures: ["不可考的赫梯饥民"], place: "东地中海与安纳托利亚", state: "赫梯王国", sources: ["罗伯茨《青铜时代的崩溃》（2014中译本）", "气候沉积与树轮研究综述"], tags: ["气候变冷", "饥荒", "体系崩溃"] }, related: [] },
  { id: "world--b1200--a01", track: "world", year: -1200, yearApprox: true, dim: "art", weight: 4, title: "奥尔梅克巨石头像", summary: "中美洲以整块玄武岩雕出数吨重的王侯头像。", detail: { background: "韦拉克鲁斯-塔巴斯科的森林河川社会需以石像彰显权力。", process: "圣洛伦索与拉文塔出土17尊头像，高约1.5—3.4米、重约6—50吨，自图斯特拉山运来并磨光，戴方帽、面部特征写实，年代约前1200—前900（学界推定）。", impact: "奥尔梅克雕刻确立了中美洲的神权图像与球戏、历法传统，被学界视为玛雅与后续墨西哥文明的母体文化之一。", figures: ["斯塔布斯与贝内特（早期调查者）"], place: "圣洛伦索与拉文塔（今墨西哥韦拉克鲁斯、塔巴斯科）", state: "奥尔梅克", sources: ["科亚特《奥尔梅克：墨西哥的黎明》", "斯普兰茨等《中美洲的黎明》"], tags: ["巨石头像", "奥尔梅克", "中美洲"] }, related: [] },
  { id: "world--b1200--s01", track: "world", year: -1200, yearApprox: true, dim: "science", weight: 3, title: "恒河流域的铁器与稻作", summary: "冶炼与铁制斧犁推动恒河平原的森林开垦。", detail: { background: "印度河衰落后的文化重心东移到恒河上游，雨量充沛宜稻。", process: "恒河中游「黑红陶」与铜石并用文化层出土铁矛、刀、犁铧与炉渣，年代约前14—前11世纪（学界推定）；伴随水稻、小米轮作与牛耕。", impact: "铁斧与铁犁使大规模砍伐与深耕成为可能，奠定吠陀时代后期村落农业与恒河城市化的物质基础。", figures: ["不可考的恒河冶铁匠"], place: "恒河中游（今印度北方邦）", state: "后哈拉帕恒河诸部", sources: ["《剑桥印度史》第1卷（铁器时代章）", "沙尔马等《印度考古与历史》综述"], tags: ["铁器", "稻作", "恒河文明"] }, related: [] },
  { id: "world--b1185--p01", track: "world", year: -1185, yearApprox: true, dim: "politics", weight: 4, title: "乌加里特的末代书简与城毁", summary: "末代君主向亚述求粮的书信成为宫殿体系的绝笔。", detail: { background: "乌加里特以转口贸易立国，依赖赫梯庇护与塞浦路斯粮船；前13世纪末饥荒与兵乱交迫。", process: "出土泥板中有末代王阿姆穆拉皮向亚述王求粮、求援之信，以及塞浦路斯敌舰抵岸的警报；遗址地层显示城区与王宫在同一时期被焚，毁坏层无重建。", impact: "这座国际商都的消失标志青铜时代近东秩序解体，也保存了前1200年前后危机的一手文书。", figures: ["阿姆穆拉皮（乌加里特末代王）"], place: "乌加里特（今叙利亚拉塔基亚郊外）", state: "乌加里特城邦", sources: ["法国考古研究所拉塔基亚发掘报告", "《剑桥古代史》第2卷（青铜时代崩溃章）", "大英博物馆近东文书目"], tags: ["乌加里特", "青铜崩溃", "求粮书简"] }, related: [] },
  { id: "world--b1180--e01", track: "world", year: -1180, yearApprox: true, dim: "economy", weight: 3, title: "东地中海贸易网瓦解", summary: "锡、铜与粮船的航线中断，宫殿经济失去市场。", detail: { background: "青铜生产依赖远程供铜供锡，宫殿掌握仓储与再分配，商人、书吏与工匠跨国流动。", process: "约前1200—前1150年间，赫梯、乌加里特、塞浦路斯与埃及莱万特站点的仓储与账板同期停止；外来陶与进口金属在遗址上层骤减（考古统计）。", impact: "远程贸易萎缩使小亚细亚、塞浦路斯与黎凡特转入地方化、自给化经济，铁与陶器逐步取代青铜礼器。", figures: ["不可考的航线商人与书吏"], place: "东地中海（安纳托利亚—塞浦路斯—黎凡特）", state: "东地中海青铜诸王国", sources: ["莫里斯《希腊：一部历史》（黑暗时代章）", "《剑桥古代史》第2卷"], tags: ["贸易网络", "青铜经济", "衰退"] }, related: [] },
  { id: "world--b1177--d01", track: "world", year: -1177, yearApprox: true, dim: "disaster", weight: 5, title: "宫殿体系的整体崩溃", summary: "数十年间东地中海诸王国接连毁弃，旧世界终结。", detail: { background: "旱作带减产、地震、人口迁徙与系统相互依赖，使宫殿国家同时承压（气候岩芯与地层证据）。", process: "约前1200—前1150年，哈图沙、基齐瓦特那达、乌加里特、亚实杜德与亚实基伦相继被焚或废弃；埃及虽击退入侵者，但失去海外属土与税源。", impact: "这一连串崩溃终结了青铜时代国际体系，为铁器、字母、城邦与地域王国铺路，是古代世界最重大的断裂之一。", figures: ["不可考的迁徙部族首领"], place: "东地中海与安纳托利亚", state: "青铜时代晚期诸王国", sources: ["克莱因《1177年：青铜时代的海上民族与文明崩溃》", "《剑桥古代史》第2卷", "美国国家科学院院刊东地中海古气候论文"], tags: ["青铜崩溃", "系统断裂", "文明转折"] }, related: [] },
  { id: "world--b1175--m01", track: "world", year: -1175, yearApprox: true, dim: "military", weight: 4, title: "拉美西斯三世的海陆之战", summary: "埃及拒海上民族于三角洲与叙利亚北岸。", detail: { background: "第20王朝的塞提二世时利比亚人已压西部边；拉美西斯三世在位第8年，多部族联合东侵。", process: "哈里斯大纸草与梅迪奈特哈布浮雕记陆战于尼罗河口诸隘、海战于帕鲁加与底吉；埃及以弓箭手、步兵与河船设伏，据铭称杀敌逾九千（数字系王室战果记法）。", impact: "埃及免于宫殿式灭顶，但军费与失土掏空国库，第20王朝此后加速解体；被击败者部分定居海岸，成为非利士人。", figures: ["拉美西斯三世"], place: "尼罗河三角洲与帕鲁加（今叙利亚北岸）", state: "埃及新王国", sources: ["都灵埃及博物馆藏哈里斯大纸草", "梅迪奈特哈布祭庙浮雕", "布雷斯特德《古代埃及文献记》"], tags: ["海上民族", "三角洲会战", "新王国"] }, related: [] },
  { id: "world--b1170--p01", track: "world", year: -1170, yearApprox: true, dim: "politics", weight: 3, title: "非利士五城与海岸定居", summary: "入侵者立五个自治城邦于迦南南岸。", detail: { background: "拉美西斯三世后，海上民族中的培莱赛特等部被安置或自行占据地中海东岸平原。", process: "考古在五城（加沙、阿什克隆、亚实杜德、以革伦、迦特）见爱琴式炉灶、陶与葬俗，与当地迦南传统并存；以革伦出土 献词铭文记其神祇。", impact: "非利士人与以色列诸部长期争夺海岸与谷地，其城邦制、督官与火器传统进入希伯来圣经叙事。", figures: ["不可考的非利士城邦督官"], place: "迦南地中海东岸（今加沙至以革伦）", state: "非利士五城", sources: ["以色列考古局以革伦发掘报告", "塞格尔《非利士物质文化研究》", "《剑桥古代史》第3卷"], tags: ["非利士", "五城", "海岸定居"] }, related: [] },
  { id: "world--b1150--s01", track: "world", year: -1150, yearApprox: true, dim: "science", weight: 3, title: "冶铁术的扩散", summary: "炼铁与锻打从安纳托利亚传向四方，青铜配额失效。", detail: { background: "青铜依赖远程铜锡，崩溃后供应断裂；褐铁矿与沼铁在多地可就近取得。", process: "前12世纪起，安纳托利亚、塞浦路斯、黎凡特与两河出土炼渣、坩埚与铁器比例上升；渗碳与淬火经验使刀刃可锻，但块炼铁产量仍低。", impact: "铁器与本地矿源使技术不再被宫殿与远路垄断，加速地方手工业与农户武装化，后世以「铁器时代」命名。", figures: ["不可考的安纳托利亚与黎凡特铁匠"], place: "安纳托利亚—黎凡特—塞浦路斯", state: "铁器时代早期诸社群", sources: ["《技术史》第1卷（古代篇）", "考古冶金学期刊之铁器时代论文综述"], tags: ["冶铁", "块炼铁", "技术扩散"] }, related: [] },
  { id: "world--b1150--d01", track: "world", year: -1150, yearApprox: true, dim: "disaster", weight: 3, title: "北欧湖侵与气候转湿", summary: "斯堪的纳维亚湖位上涨，农田与聚落没于水。", detail: { background: "青铜时代晚期北欧以沼泽铁、亚麻与畜群为生，聚落多在湖畔台地。", process: "瑞典与芬兰的古湖位研究以湖成阶地与水下泥炭定出约前1150年与前750年两次水位上升（据湖泊沉积与碳十四序列，学界仍在细化），同期遗址上层见洪积层与废弃面。", impact: "湿地扩张改变了北欧的牧道与田畴布局，聚落向高地迁移，也促成后来以沼泽沉积物献祭的宗教习惯。", figures: ["不可考的北欧湖畔农户"], place: "瑞典与芬兰南部湖区", state: "北欧青铜时代诸社群", sources: ["瑞典地貌与古湖位研究综述", "《斯堪的纳维亚青铜时代》专著综述", "芬兰国家古物局湖岸遗址报告"], tags: ["湖侵", "气候", "北欧"] }, related: [] },
  { id: "world--b1125--c01", track: "world", year: -1125, yearApprox: true, dim: "culture", weight: 3, title: "《温阿蒙记述》与残存商路", summary: "埃及官员出聘比布罗斯，记宫殿体系崩溃后的世态。", detail: { background: "阿蒙祭司派温阿蒙赴黎凡特购雪松，船资、护卫与汇率皆需自讨，反映王库不再供事。", process: "纸草记其抵比布罗斯受亲王扎克巴尔轻慢、以金银暂抵货款、途中遭劫掠索偿；文末他在塔尼斯滞留三十一日（原文自述）。", impact: "文书是前11世纪东地中海商业、货币与外交实态的珍贵见证，也记出埃及影响力在黎凡特的收缩。", figures: ["温阿蒙（阿蒙神庙官员）", "扎克巴尔（比布罗斯亲王）"], place: "塔尼斯至比布罗斯（今黎巴嫩朱拜勒）", state: "埃及新王国末期", sources: ["莫斯科普希金美术馆藏阿蒙尼纸草", "《古埃及文学：新王国与第三中间期》选译本"], tags: ["温阿蒙", "雪松贸易", "旅行文学"] }, related: [] },
  { id: "world--b1122--p01", track: "world", year: -1122, yearApprox: true, dim: "politics", weight: 2, title: "箕子东来的传说记载", summary: "后世中朝史籍记商末贵族率众入朝鲜立教。", detail: { background: "此属传说性族源叙事，年代依商周之际推定，考古证据尚无定论（学界存疑）。", process: "《史记·宋微子世家》与《汉书·地理志》记商亡后箕子率五千人入朝鲜，教民田作、礼法与八条之禁；高丽《三国遗事》另立檀君系统。", impact: "该记载成为朝鲜半岛史学中「东方礼义之邦」自我理解的早期文本依据，近代亦被用作民族史论争焦点。", figures: ["箕子"], place: "朝鲜半岛北部与辽东（传说范围）", state: "古朝鲜（传说）", sources: ["《史记·宋微子世家》", "《汉书·地理志》", "《三国遗事》纪异篇"], tags: ["箕子", "古朝鲜", "族源传说"] }, related: [] },
  { id: "world--b1100--c01", track: "world", year: -1100, yearApprox: true, dim: "culture", weight: 4, title: "琐罗亚斯德与《伽萨》颂诗", summary: "波斯高原出现以善恶抉择为核心的改革信仰。", detail: { background: "早期伊朗多神信仰与游牧民祭并存；《伽萨》语言古于阿维斯他其余部分，年代学界多在前二千年末至前一千年。", process: "琐罗亚斯德宣阿胡拉·马兹达为智慧之主，与安格拉·曼纽对立，人须以「善思、善言、善行」抉择，末日审判与肉身复活观念由此成形。", impact: "该信仰后成波斯国教，其天使、撒旦、救世与末世论经犹太—基督教—伊斯兰传统深刻影响西方宗教观。", figures: ["琐罗亚斯德"], place: "东伊朗—中亚草原（推定）", state: "伊朗诸部", sources: ["《阿维斯他·伽萨》耶斯纳28—34章", "博伊斯《琐罗亚斯德教徒：他们的信仰与实践》", "《伊朗剑桥史》第2卷（宗教与文字）"], tags: ["琐罗亚斯德", "伽萨", "二元论"] }, related: [] },
  { id: "world--b1070--p01", track: "world", year: -1070, yearApprox: true, dim: "politics", weight: 3, title: "塔尼斯与底比斯的双重王权", summary: "第21王朝设都于北，南由阿蒙大祭司掌土。", detail: { background: "第20王朝末国库枯竭，阿蒙神庙地产扩张，利比亚裔军事首领把持三角洲。", process: "斯蒙地斯在塔尼斯称王并称「阿蒙神之事」，底比斯方面阿蒙大祭司赫里霍尔及其后族世袭，王号与祭司印同时见于碑刻；两方共用以阿蒙年号纪年。", impact: "埃及首次出现南北分治的王朝形态，王权神授的表述让位于神庙行政，第三中间期的分裂格局固定。", figures: ["斯蒙地斯", "赫里霍尔（阿蒙大祭司）"], place: "塔尼斯与底比斯", state: "埃及第21王朝", sources: ["塔尼斯王室墓出土铭刻", "卡尔纳克大庭院祭司雕像基座", "《剑桥古代史》第3卷"], tags: ["第三中间期", "阿蒙祭司", "分治"] }, related: [] },
  { id: "world--b1050--s01", track: "world", year: -1050, yearApprox: true, dim: "science", weight: 5, title: "二十二字母的腓尼基书写", summary: "以辅音字母记词，书写脱离楔形与表意系统。", detail: { background: "迦南—西奈的简笔表音符号长期存在于矿山与铭刻；黎凡特城邦商人需要可学、可写的记账工具。", process: "约前11世纪中叶，比布鲁斯与西顿等地形成由阿雷夫至陶夫的22个辅音字母，定名、定序、定书写向（自右而左），字母名为具体物名。", impact: "此套字母成为希腊、伊特鲁里亚、拉丁、阿拉米、阿拉伯与希伯来文字的共祖，是人类使用最广的字母系统之源。", figures: ["不可考的比布鲁斯书吏"], place: "腓尼基海岸（今黎巴嫩比布鲁斯—西顿）", state: "腓尼基城邦", sources: ["《剑桥古代史》第3卷（字母起源章）", "《字母与文字通史》综述", "法国考古研究所比布鲁斯发掘报告"], tags: ["腓尼基字母", "辅音文字", "书写革命"] }, related: [] },
  { id: "world--b1020--p01", track: "world", year: -1020, yearApprox: true, dim: "politics", weight: 2, title: "撒母耳立王与士师时代终结", summary: "部落联盟迫于非利士，请立君。", detail: { background: "士师记时代各部落由战时兴起的「士师」临时统领，无税收与常备军。", process: "《撒母耳记上》记长老聚集米斯巴求立王，撒母耳膏便雅悯人扫罗于吉甲，随后以王权统合军队（细节为圣经文本，考古无独立见证）。", impact: "以色列从部落联盟转向世袭王权，为大卫国家的税、军与祭司体制定型铺路。", figures: ["撒母耳", "扫罗"], place: "米斯巴与吉甲（今巴勒斯坦中部）", state: "以色列部落联盟", sources: ["《希伯来圣经·撒母耳记上》8—10章", "阿尔布雷特《以色列考古史》"], tags: ["士师", "立王", "扫罗"] }, related: [] },
  { id: "world--b1010--m01", track: "world", year: -1010, yearApprox: true, dim: "military", weight: 2, title: "基利波山之战与非利士退却", summary: "以色列军于耶斯列平原击溃海岸城邦军队。", detail: { background: "非利士五城控制海岸与谷地，封锁铁匠以防以色列自制兵器（圣经所述）。", process: "《撒母耳记上》记扫罗与约拿单在基利波山阵亡前后，大卫以机动袭扰亚玛力与非利士边地，终在巴力·拉帕拉追击中使敌军北溃。", impact: "海岸城邦的军事优势被打破，为大卫统一山地与建立王国提供条件。", figures: ["大卫", "扫罗"], place: "基利波山与亚斯力平原（耶斯列谷）", state: "以色列诸部", sources: ["《希伯来圣经·撒母耳记上》28—30章", "《剑桥古代史》第3卷"], tags: ["基利波山", "非利士", "大卫崛起"] }, related: [] },
  { id: "world--b1000--p01", track: "world", year: -1000, yearApprox: true, dim: "politics", weight: 4, title: "大卫定都耶路撒冷", summary: "取中间地带的山城为都，合二邦为一国。", detail: { background: "耶路撒冷原为耶布斯人所据山脊小城，处犹大与以色列之间，不属任何部族地分。", process: "撒母耳记下记大卫夺取锡安保障，迁约柜入城，建宫室与官方祭司班；城下扩为行政与宗教中心（今考古在东城发现石砌台基与隧道系统）。", impact: "「大卫之约」与锡安神学自此成为犹太王权与末世盼望的核心，耶路撒冷至今是三教圣城。", figures: ["大卫"], place: "耶路撒冷（锡安坡）", state: "以色列联合王国", sources: ["《希伯来圣经·撒母耳记下》5章", "以色列考古局大卫城发掘报告", "耶路撒冷考古与圣殿山研究综述"], tags: ["大卫", "耶路撒冷", "定都"] }, related: [] },
  { id: "world--b1000--c01", track: "world", year: -1000, yearApprox: true, dim: "culture", weight: 3, title: "《原人歌》与四瓦尔纳", summary: "吠陀末章以献祭神话为社会分层立说。", detail: { background: "《梨俱吠陀》第十曼陀罗编集较晚，此期婆罗门与王族地位上升，部族内业役分化明显。", process: "原人歌颂巨原人献祭，其口生婆罗门、双臂生王族（罗伽尼亚）、双腿生吠舍、双足生首陀罗（原文喻象）。", impact: "该颂成为后世瓦尔纳制度最常引的经典依据，种姓分立由此获得宇宙论解释，影响南亚社会至今。", figures: ["不可考的第十曼陀罗诗人家"], place: "旁遮普与恒河上游（吠陀地区）", state: "后期吠陀诸部", sources: ["《梨俱吠陀》10.90", "《剑桥印度史》第1卷（吠陀社会章）", "《印度种姓制度研究》综述"], tags: ["原人歌", "瓦尔纳", "种姓起源"] }, related: [] },
  { id: "world--b990--e01", track: "world", year: -990, yearApprox: true, dim: "economy", weight: 2, title: "推罗与以色列的通商", summary: "腓尼基城邦以匠人、木材换谷物与油。", detail: { background: "所罗门需要造船材料与 熟练工匠，推罗控制雪松运路与海上船坞。", process: "列王纪记希兰王运香柏木与金，以色列供麦二万歌珥、油二十罢特；又记以旬迦别红海船队与推口水手同航俄斐（文本记载，实物待证）。", impact: "这类「匠人换粮」协定把山地王国接入腓尼基商业网，也带进异邦神与外来的建筑、冶金知识。", figures: ["推罗王希兰", "所罗门"], place: "推罗与以旬迦别（今黎巴嫩与亚喀巴湾岸）", state: "腓尼基城邦与以色列", sources: ["《希伯来圣经·列王纪上》5、9章", "《剑桥古代史》第3卷"], tags: ["希兰", "香柏木", "红海船运"] }, related: [] },
  { id: "world--b970--p01", track: "world", year: -970, yearApprox: true, dim: "politics", weight: 3, title: "所罗门集权与税区制", summary: "国王分王国为十二供税区，置官营牧场与战车城。", detail: { background: "大卫留下较大版图但部落裂隙深，宫廷开支与建筑工程需稳定供给。", process: "列王纪上记全国设十二官、各按月供王与百官之食；又记米吉多、夏琐、基色筑城与马厩，考古在米吉多见六室门与成排石柱马厩基（年代归属学界仍有争论）。", impact: "重税与力役激起北方不满，为王国分裂埋因；亦使耶路撒冷首次成为国际商道上的名都。", figures: ["所罗门"], place: "耶路撒冷与米吉多、夏琐", state: "以色列联合王国", sources: ["《希伯来圣经·列王纪上》4、9章", "以色列考古局米吉多发掘报告"], tags: ["所罗门", "税区", "筑城"] }, related: [] },
  { id: "world--b957--c01", track: "world", year: -957, yearApprox: true, dim: "culture", weight: 3, title: "耶路撒冷第一圣殿落成", summary: "山地王国建起一座近东式三进式圣殿。", detail: { background: "大卫欲建神屋未获允，所罗门时期王权与商税足以供役；样式取近东圣殿通制。", process: "列王纪记殿分前廊、主殿与内殿（至圣所），以香柏木、石头与金饰成，用推罗—比布鲁斯工匠与采石役；七年而成，行奉献节七日。", impact: "祭仪集中于耶路撒冷，成为「唯一敬拜处」的神学基础；圣殿此后是犹太民族认同与末世叙事的轴心。", figures: ["所罗门", "推罗工匠户兰"], place: "耶路撒冷圣殿山", state: "以色列联合王国", sources: ["《希伯来圣经·列王纪上》6—8章", "《圣经世界考古学》", "耶路撒冷考古与圣殿山研究报告"], tags: ["第一圣殿", "奉献礼", "锡安神学"] }, related: [] },
  { id: "world--b950--e01", track: "world", year: -950, yearApprox: true, dim: "economy", weight: 3, title: "阿拉伯乳香与没药商路", summary: "骆驼队运南阿拉伯香料北至迦南与两河。", detail: { background: "今也门与佐法尔的乳香树树脂为地中海与美索不达米亚祭祀必需品，陆运需骆驼与绿洲水站。", process: "考古在提姆奈与马因遗址见灌溉渠与神庙铭刻，纳巴泰与盖达里叶诸部控制加沙—但—耶路撒冷线，埃及与亚述文献记载阿拉伯女王的骆驼与香料贡。", impact: "香料贸易使南阿拉伯与小亚细亚之间的绿洲城邦积累资本，也促成阿拉伯字母与灌溉王国的兴起。", figures: ["不可考的阿拉伯商部长"], place: "南阿拉伯至加沙（乳香之路）", state: "南阿拉伯诸王国", sources: ["《阿拉伯考古与碑铭》综述", "普里查德《古代近东文献》（阿拉伯贡赋条）", "耶路撒冷圣经之地博物馆商路特展图录"], tags: ["乳香", "骆驼商队", "南阿拉伯"] }, related: [] },
  { id: "world--b930--p01", track: "world", year: -930, yearApprox: true, dim: "politics", weight: 3, title: "王国分裂：以色列与犹大", summary: "税役之争使北方十二支派另立王。", detail: { background: "所罗门死后继位者拒减役，北方会众在示剑集会。", process: "列王纪上记耶罗波安于但、伯特利立金牛像、设非撒督系祭司，与耶路撒冷的罗波安王朝对峙；两国边患与移民往来并存。", impact: "南北并立使「以色列」成为政治与宗教双重概念，其经文正典与先知传统在两国各自发展。", figures: ["耶罗波安", "罗波安"], place: "示剑与耶路撒冷", state: "北国以色列与南国犹大", sources: ["《希伯来圣经·列王纪上》12章", "以色列博物馆圣经时代展厅文物目"], tags: ["王国分裂", "伯特利", "耶罗波安"] }, related: [] },
  { id: "world--b925--m01", track: "world", year: -925, yearApprox: true, dim: "military", weight: 3, title: "舍顺克一世远征迦南", summary: "埃及第二十二王朝重划巴勒斯坦势力线。", detail: { background: "第三中间期末埃及利比亚系王族欲恢复黎凡特朝贡旧例，庇护逃王的耶罗波安。", process: "卡尔纳克巴布斯提斯门胜利名单刻其取百数十城邑之名（原为248条，残存可读者过半），米吉多残碑亦见其名；同名单中另见犹大诸城之名。", impact: "此役后北国失去部分税区与商路，事件被圣经记为「埃及交于你手」的神学解释，也是埃及纪年与圣经年表交叉的锚点。", figures: ["舍顺克一世"], place: "米吉多与犹大丘陵", state: "埃及第22王朝", sources: ["卡尔纳克第二塔门胜利名单", "《希伯来圣经·列王纪上》14:25", "《剑桥古代史》第3卷"], tags: ["舍顺克", "米吉多碑", "朝贡"] }, related: [] },
  { id: "world--b911--p01", track: "world", year: -911, yearApprox: true, dim: "politics", weight: 3, title: "亚述中兴：阿淑尔丹二世", summary: "亚述先清游牧侧翼，再复两河商道。", detail: { background: "青铜崩溃后亚述缩至底格里斯中游，阿拉米部落据卡迭什以东，粮道受阻。", process: "其铭文自述逐阿拉米人于幼发拉底中游、渡河掠其驼群与羊群，并重开巴比伦—亚述商路；编年史残片记其一年两征。", impact: "此两代王的重建恢复亚述的骑兵与渡河能力，为前9—前7世纪的帝国扩张提供财政与兵源基础。", figures: ["阿淑尔丹二世"], place: "底格里斯与幼发拉底中游", state: "中亚述—新亚述之际", sources: ["尼姆鲁德（卡拉赫）王表与铭文", "《亚述王表与铭文集成》", "《剑桥古代史》第3卷"], tags: ["亚述中兴", "阿拉米人", "商路"] }, related: [] },
  { id: "world--b900--a01", track: "world", year: -900, yearApprox: true, dim: "art", weight: 3, title: "诺克文化的陶塑人像", summary: "西非尼日尔河谷出现等身大小的烧陶人首。", detail: { background: "诺克分布于今尼日利亚中部高原，以农业、冶铁与陶范著称，遗址多为被扰乱层。", process: "1928年起出土空心陶头与立像，三角眼、穿孔瞳孔、分层发型，经热释光测年部分标本在公元前一千纪初（测年数据有争议）。", impact: "这是撒哈拉以南非洲最早的具象雕塑传统之一，其风格线索见于后来的伊费与贝宁，改变非洲艺术「无写实」的旧说。", figures: ["不可考的诺克陶工"], place: "诺克与卡齐纳河谷（今尼日利亚）", state: "诺克文化", sources: ["德国法兰克福民族学博物馆诺克展图录", "杰姆库尔《诺克：非洲最早的陶塑传统》", "热释光测年论文（非洲考古期刊）"], tags: ["诺克", "陶塑", "西非"] }, related: [] },
  { id: "world--b900--x01", track: "world", year: -900, yearApprox: true, dim: "explore", weight: 2, title: "奥尔梅克的玉、可可与橡胶", summary: "中美洲以河运汇翡翠、可可与橡胶于湾区。", detail: { background: "韦拉克鲁斯湿热地带产橡胶树与可可，翡翠则来自东南的莫塔瓜河谷。", process: "遗址分析显示翡翠器原料来自危地马拉北部矿带，磁铁矿与海贝同流通；拉文塔与圣洛伦索的泥炭层中见栽培可可与橡胶林残留（植硅体与化学分析）。", impact: "这条以物易物的交换网把中美洲高地与低地连成一体，其玉礼、可可饮与球戏器具成为后来玛雅与墨西哥文明的共同底子。", figures: ["不可考的湾区舟运者"], place: "墨西哥湾沿岸至危地马拉", state: "奥尔梅克", sources: ["危地马拉翡翠矿带地质考古研究", "拉文塔与圣洛伦索植物残留分析简报", "《中美洲的黎明》综述"], tags: ["翡翠", "可可", "交换网络"] }, related: [] },
  { id: "world--b883--m01", track: "world", year: -883, yearApprox: true, dim: "military", weight: 3, title: "亚述纳西尔帕二世的西征", summary: "八次北伐叙利亚，攻城以屠与迁民立威。", detail: { background: "亚述需打通至地中海的雪松与银路，新赫梯小邦与阿拉米诸国各守山城。", process: "其年鉴铭刻记围城、削鼻剜目、堆尸为京、徙民于亚述耕作等惩罚（王室铭文以恐怖为宣传，数字多有夸大）；前879年迁卡拉赫建新宫。", impact: "残酷镇抚成为新亚述的属邦治理模板，也为亚述招致普遍抵抗；其宫廷浮雕是古代战争图像的主要资料。", figures: ["亚述纳西尔帕二世"], place: "扎格罗斯至奥龙特河（今叙利亚北部）", state: "新亚述王国", sources: ["卡拉赫王座铭文与年鉴", "《亚述王年鉴》校订汇编", "大英博物馆尼姆鲁德浮雕藏目"], tags: ["纳西尔帕二世", "围城", "迁民"] }, related: [] },
  { id: "world--b879--a01", track: "world", year: -879, yearApprox: true, dim: "art", weight: 2, title: "卡拉赫王宫的征服浮雕", summary: "石膏壁板编攻城、迁民与贡赋为连续画面。", detail: { background: "亚述王宫以壁面叙事取代象形纪念，观者为使节与属邦来朝者。", process: "西北宫出土浮雕与铭文带记围城坡道、悬盾渡壕、剥皮与徙民行列、贡船运雪松；匠人以阿拉米与腓尼基工匠为主（风格分析）。", impact: "这套图像宣传是研究新亚述军制、工程与族迁的第一手视觉资料，也塑造了近东王权「牧养与惩罚」的造型语汇。", figures: ["不可考的卡拉赫刻石匠人"], place: "卡拉赫（今伊拉克尼姆鲁德）", state: "新亚述王国", sources: ["大英博物馆尼姆鲁德壁板藏目", "《亚述艺术》专著综述", "《亚述宫殿浮雕与帝国意识形态》研究综述"], tags: ["宫殿浮雕", "攻城图", "宣传"] }, related: [] },
  { id: "world--b850--x01", track: "world", year: -850, yearApprox: true, dim: "explore", weight: 3, title: "推罗商站扩至西西里与撒丁", summary: "腓尼基人设泊地、陶窑与神庙于西地中海。", detail: { background: "锡、银与紫螺资源在西端，希腊殖民尚未成势，西西里土著与撒丁努拉吉文化提供中转。", process: "莫齐亚、帕诺尔穆斯与撒丁苏尔基斯遗址出土前9—前8世纪腓尼基式陶、双联罐与阿斯塔蒂祭所；诺拉石碑为其时在撒丁的腓尼基文刻石（年代归属有争）。", impact: "这些泊地后来多半成为迦太基属站，也留下拉丁与希腊字母借道西传的中间环节。", figures: ["不可考的推罗与西顿船主"], place: "西西里莫齐亚与撒丁苏尔基斯", state: "腓尼基西方商站", sources: ["西西里莫齐亚考古公园发掘简报", "《腓尼基与布匿的地中海》图录", "撒丁诺拉石碑铭刻释文"], tags: ["商站", "莫齐亚", "西地中海"] }, related: [] },
  { id: "world--b842--m01", track: "world", year: -842, yearApprox: true, dim: "military", weight: 2, title: "黑色方尖碑上的朝贡", summary: "以色列王耶户伏地献银金与器皿的图像记录。", detail: { background: "沙尔马纳塞尔三世再征西方，压服大马士革以北诸邦；以色列此时北受亚兰之逼。", process: "卡拉赫出土黑方尖碑五层浮雕，第二层铭称「以色列家之税」，画面一伏地者戴尖顶帽，学者多认作耶户使者（碑文与《列王纪下》可互校）。", impact: "这是圣经人物同时见于亚述纪念物的最早图像之一，也为公元前9世纪近东纪年提供交叉锚点。", figures: ["沙尔马纳塞尔三世", "耶户"], place: "卡拉赫（今尼姆鲁德）", state: "新亚述王国", sources: ["大英博物馆黑色方尖碑藏目", "普里查德《古代近东文献》（亚述条）"], tags: ["黑方尖碑", "耶户", "朝贡图"] }, related: [] },
  { id: "world--b814--p01", track: "world", year: -814, yearApprox: true, dim: "politics", weight: 4, title: "迦太基建城的传统年代", summary: "推罗流亡者建新商业王国于北非海湾。", detail: { background: "古典作家记推罗王族内争与祭祀之乱，伊里萨（狄多）率众携神像西奔；罗马纪年据此推算。", process: "维吉尔与查士丁所记「牛皮围地」的博尔萨山故事属传说；考古在圆形港与托斐特圣所最早的器物层不早于前8世纪末（与文献年代有别）。", impact: "迦太基后来成为西地中海的农业与商业大国，与罗马的三次布匿战决定地中海世界归属，故此城是西方史的关键起点之一。", figures: ["伊里萨（狄多）"], place: "北非突尼斯湾（今突尼斯拉吉勒）", state: "迦太基", sources: ["维吉尔《埃涅阿斯纪》第1卷", "查士丁《腓尼基王史》第18卷", "突尼斯迦太基遗址发掘简报"], tags: ["迦太基", "狄多", "建城"] }, related: [] },
  { id: "world--b810--c01", track: "world", year: -810, yearApprox: true, dim: "culture", weight: 3, title: "查文德万塔尔的朝圣中心", summary: "安第斯山口的石构神庙成为共信之所。", detail: { background: "高地与沿海诸社群玉米、鱼粉与棉花互通，需要中立的节庆与神谕场所。", process: "遗址以马蹄形台基、地下回廊、石砌排水与「兰松」巨柱神像为特征，石上刻美洲豹、凯门鳄与蛇纹；出土贝号与致幻植物残留（分析数据）。", impact: "查文风格的神像与礼器传布秘鲁北部，构成安第斯第一个跨族群宗教文化圈，而非靠军事或文字维系。", figures: ["不可考的查文祭司"], place: "安卡什山口（今秘鲁瓦里）", state: "查文文化", sources: ["秘鲁文化部查文遗址档案", "考夫曼等《安第斯的古代文明》", "《剑桥安第斯史》第1卷"], tags: ["查文", "神庙", "安第斯"] }, related: [] },
  { id: "world--b800--x01", track: "world", year: -800, yearApprox: true, dim: "explore", weight: 3, title: "跨撒哈拉的牛队与盐路", summary: "骆驼未至时，撒哈拉以牛车与步行队连通南北。", detail: { background: "撒哈拉此时仍存湖泊与草道残留，加拉曼特与加纳姆等绿洲部族掌握水井与向导。", process: "岩画与遗址见四轮牛车、盐块与陶器南北流向，今尼日尔与乍得遗址出土盐、铜与小米共存层；希罗多德后追记加拉曼特人驾车猎埃塞俄人（记载属后世转述）。", impact: "这条前骆驼时代的通道把西非谷物、畜群与地中海盐、铜连成一体，为后来的金—盐贸易奠定基础。", figures: ["不可考的绿洲向导"], place: "中撒哈拉（今尼日尔塔西利—乍得比勒马）", state: "撒哈拉绿洲诸部", sources: ["塔西利阿杰尔岩画调查报告", "《非洲通史》第3卷（撒哈拉交换章）", "英国皇家地理学会早期撒哈拉旅行记"], tags: ["撒哈拉", "牛车商路", "盐"] }, related: [] },
  { id: "world--b800--c01", track: "world", year: -800, yearApprox: true, dim: "culture", weight: 3, title: "婆罗门书与献祭神学", summary: "祭司文书解祭式细节为宇宙运行机制。", detail: { background: "吠陀口传分「本集」与「梵书」两部，恒河—阎牟那河间（梵书地区）的婆罗门家族掌其传。", process: "《百道梵书》《爱多列雅梵书》等逐条解苏摩祭、火坛筑法与祭司唱诵之「所以然」，并记王权即位祭与马祭的规制与费用。", impact: "献祭被解释为可自力生效的术，婆罗门由此取得仪式垄断地位，种姓分工与「净与不净」观念被制度化。", figures: ["沙塔帕塔等不可考的传教师"], place: "俱卢—般遮罗地区（恒河—阎牟那河间）", state: "后期吠陀婆罗门诸团", sources: ["《百道梵书》英译（艾格顿本）", "《剑桥印度史》第1卷（梵书时期章）", "《吠陀文献研究导论》"], tags: ["梵书", "苏摩祭", "婆罗门"] }, related: [] },
  { id: "world--b800--s01", track: "world", year: -800, yearApprox: true, dim: "science", weight: 3, title: "稻作与磨制农具入日本列岛", summary: "水田、硬陶与石镰自朝鲜海峡传入九州北部。", detail: { background: "绳文时代的采集渔猎社会在公元前一千纪末接触到大陆传来的水稻与农耕技术（学界称此变为弥生时代之始）。", process: "福冈板付等遗址见水田遗迹、木框田埂、磨制石镰与含稻壳的陶片；碳十四与树轮校正把水田始期推在约前800—前500年间（传统年代以前300年为准，两说并存）。", impact: "稻作与定居村落使西日本人口与首领权激增，出现储粮、灌溉协作与后来的方国雏形，绳文的采集世界逐步退场。", figures: ["不可考的九州稻农"], place: "北九州（今福冈板付）", state: "日本列岛弥生前期诸聚落", sources: ["板付水田遗迹发掘报告", "京都大学碳十四与树轮校正研究", "《日本考古学》弥生卷"], tags: ["稻作", "水田", "弥生"] }, related: [] },
  { id: "world--b787--p01", track: "world", year: -787, yearApprox: true, dim: "politics", weight: 2, title: "乌拉尔图筑埃里布尼堡", summary: "山地王国立要塞与粮仓于亚拉腊山脚。", detail: { background: "凡湖以东城邦为亚述所扰，乌拉尔图借马、铁与粮收合高原诸部。", process: "阿尔吉什提一世的铭文记「以神力建埃里布尼堡，徙民众数千以实之」；今亚美仑考古在岩丘见基座石、仓储窖与楔形刻（遗址即今埃里温）。", impact: "该堡与卡米尔—贝尔等要塞形成高原防线，使乌拉尔图能与亚述争叙利亚北部的铁、马与商道。", figures: ["阿尔吉什提一世"], place: "埃里布尼（今亚美尼亚埃里温）", state: "乌拉尔图王国", sources: ["埃里布尼楔形建筑铭", "《剑桥古代史》第3卷（乌拉尔图章）", "亚美尼亚科学院发掘简报"], tags: ["乌拉尔图", "埃里布尼", "要塞"] }, related: [] },
  { id: "world--b776--c01", track: "world", year: -776, yearApprox: true, dim: "culture", weight: 4, title: "奥林匹亚竞技与希腊纪年", summary: "伯罗奔尼撒的赛会后来成为全希腊的年代坐标。", detail: { background: "阿尔菲奥斯河谷的宙斯圣所早已有人群节庆； 伊利斯城掌赛期与「神圣休战」。", process: "传统以前776年为首届，此后每四年一届；考古在该层见烧土台与青铜三足鼎、小型还愿物，赛项起初仅有短跑一项（后续世纪渐增）。", impact: "希腊人以「奥林匹亚第若干年」记时，希庇亚斯与亚里士多德派学者据此编年表，竞技成为城邦认同与泛希腊秩序的枢纽。", figures: ["科罗埃布斯（传说中的首位优胜者）"], place: "伯罗奔尼撒奥林匹亚", state: "希腊诸城邦", sources: ["保塞尼亚斯《希腊志》第6卷", "希腊考古院奥林匹亚发掘报告", "《剑桥古代史》第3卷（希腊赛会章）"], tags: ["奥林匹亚", "赛会纪年", "休战"] }, related: [] },
  { id: "world--b770--s01", track: "world", year: -770, yearApprox: true, dim: "science", weight: 5, title: "希腊字母增入元音", summary: "借辅音字母并加母音，得可读可诵的新文字。", detail: { background: "闪语字母不写元音，而希腊语形态变化依赖母音；线形文字B已亡于宫殿崩溃。", process: "学界推定前9—前8世纪在库迈、匹特库塞或东岸港口由希腊人借腓尼基22字母，取若干不作希腊首音之字母转为元音，并自右向左改为可回转书写。", impact: "元音字母使拼读门槛骤降，史诗得写成固定文本，法律、哲学与戏剧随之可传抄，成为欧洲文字的共同源头。", figures: ["不可考的库迈与东岸书吏"], place: "爱琴海与意大利南部（推定）", state: "几何时代希腊", sources: ["杰弗里《古风希腊的地方文字》", "《剑桥古代史》第3卷", "《字母与文字通史》综述"], tags: ["希腊字母", "元音", "书写"] }, related: [] },
  { id: "world--b763--d01", track: "world", year: -763, yearApprox: false, dim: "disaster", weight: 3, title: "亚述日食与北方叛乱", summary: "亚述历西芒努月之日食解为凶兆，王旗随即内卷。", detail: { background: "亚述以天文预兆决政事，日食属大凶；阿淑尔丹二世后王位更迭、属邦停贡。", process: "亚述编年史于「布赫-沙勒」任职之年条下记「日食，神辛显兆」，此条可推算为前763年6月15日之食，正是近代学者定亚述年表的支点；同期十四城叛，阿淑尔尼拉里五世在位九年而内战继之。", impact: "该记录既是古代天象观测的可靠凭据，也让亚述的绝对年代链可与巴比伦、埃及与圣经年表互校。", figures: ["阿淑尔尼拉里五世"], place: "亚述与伊达尔（底格里斯中游）", state: "新亚述王国", sources: ["《亚述王编年史》前763年条", "大英博物馆楔形编年史板藏目", "《巴比伦与亚述纪年体系》研究专刊"], tags: ["布赫日食", "纪年", "内战"] }, related: [] },
  { id: "world--b753--p01", track: "world", year: -753, yearApprox: true, dim: "politics", weight: 4, title: "罗马建城的传统年代", summary: "拉丁姆台地诸聚落，传说合并为一城。", detail: { background: "拉丁姆有帕拉丁、凯里等山岗村落与围栏，盐道通萨宾地区，埃特鲁里亚人在旁。", process: "瓦罗所定前753年4月21日为罗马建城日，传罗慕路斯越界杀勒穆斯、立城垣与庇护所；考古在帕拉丁见前8世纪中期茅屋桩沟与围栏（早于传说中的城垣）。", impact: "此年代成为罗马纪年之始（「建城以某年」），把拉丁、萨宾与埃特鲁里亚三系记忆并入同一城市共同体。", figures: ["罗慕路斯", "勒穆斯"], place: "台地河畔罗马（今意大利）", state: "罗马（王政前期）", sources: ["瓦罗《拉丁语源》所定建城年", "李维《建城以来史》第1卷", "帕拉丁考古队前8世纪层报告"], tags: ["罗马建城", "瓦罗纪年", "罗慕路斯"] }, related: [] },
  { id: "world--b750--a01", track: "world", year: -750, yearApprox: true, dim: "art", weight: 4, title: "荷马史诗的口传与写定", summary: "六音步长短短格铸英雄传说为固定文本。", detail: { background: "游吟诗人在宴会中以套语与类型场景即兴演述特洛伊与归乡故事，方言混合爱奥尼亚与埃奥利亚。", process: "《伊利亚特》24卷、《奥德赛》24卷各约一万五千六百行（通行本行数），「荷马」其人有无与成文年代学界长期争论，写定多推在前8—前7世纪字母传入后。", impact: "史诗成为希腊的学校课本、众神谱系与伦理范式，也是古风时代政治与地理叙事引用最多的权威文本。", figures: ["荷马"], place: "小亚细亚爱奥尼亚与斯慕耳那（传说）", state: "几何—古风时代希腊", sources: ["洛德《故事的歌手》（口述程式理论）", "《剑桥古代史》第3卷（荷马问题章）", "亚历山大里亚校勘本残片"], tags: ["荷马", "史诗", "口传写定"] }, related: [] },
  { id: "world--b750--e01", track: "world", year: -750, yearApprox: true, dim: "economy", weight: 3, title: "土地不足与希腊殖民潮", summary: "继承份额过小的农户与失势者渡海另立田亩。", detail: { background: "希腊本土多山，可耕块小，人口在几何时代后期回升，贵族争地加剧。", process: "前8—前6世纪由优卑亚、科林斯、米利都等母邦派出移民，西至匹特库塞、叙拉古、那不勒斯湾，北抵赫勒斯滂与黑海沿岸，新建据点逾四百（学界统计口径有别）。", impact: "殖民把希腊农产、陶与金属品推向全地中海，也带来信阳与谷地，令母邦的政治与商业结构被根本改写。", figures: ["不可考的殖民队长"], place: "地中海与黑海（殖民带）", state: "希腊母邦与子邦", sources: ["《希腊世界的史料（前900—前300年）》殖民章", "《希腊殖民地的考古调查》", "《剑桥古代史》第4卷"], tags: ["殖民潮", "土地", "子邦"] }, related: [] },
  { id: "world--b750--p01", track: "world", year: -750, yearApprox: true, dim: "politics", weight: 3, title: "提姆特与萨巴的灌溉王国", summary: "红海两岸以水坝与渠系立起塞姆语城邦。", detail: { background: "也门高地与今厄立特里亚、提格雷的雨季山洪可蓄可引，移民与耕作社群沿谷地定居。", process: "耶哈的提姆特神庙与碑铭（前一千纪中期，文字属南阿拉伯系）记其王号与神名；萨巴则以马里卜筑坝蓄洪、种枣与乳香，穆卡里卜之号称谓见于铭刻（年代序列依铭刻学推定）。", impact: "红海两岸由此进入有铭文、有王号与公共水利的历史，其文字与神名北上带入埃塞俄比亚北部，成为阿克苏姆文明的前身之一。", figures: ["提姆特诸王（名多残阙）"], place: "耶哈、马里卜与阿克舒姆周边", state: "提姆特与萨巴", sources: ["意大利考古队耶哈发掘简报", "《南阿拉伯碑铭集成》", "《非洲通史》第2卷（红海两岸章）"], tags: ["提姆特", "萨巴", "红海"] }, related: [] },
  { id: "world--b745--p01", track: "world", year: -745, yearApprox: true, dim: "politics", weight: 3, title: "提格拉特帕拉沙尔三世即位", summary: "将军于尼尼微夺位，改造国家与军制。", detail: { background: "前8世纪中叶亚述贵族坐大，属邦抗税，乌拉尔图压北方，巴比伦不受控。", process: "其铭文自述以「卡拉赫之众」入尼尼微，前743年亲征阿尔比杜破乌拉尔图—阿拉米联军，随后拆分大省、置驻军与移民。", impact: "这次即位开启新亚述的军事—行政改革，把亚述从受围的邦国变为可长期占领他土的帝国。", figures: ["提格拉特帕拉沙尔三世"], place: "尼尼微与卡拉赫", state: "新亚述王国", sources: ["《亚述王编年史》相关年条", "卡拉赫王表", "《亚述帝国行政研究》"], tags: ["亚述改革", "阿尔比杜", "夺位"] }, related: [] },
  { id: "world--b743--s01", track: "world", year: -743, yearApprox: true, dim: "science", weight: 2, title: "乌拉尔图的灌渠与山城", summary: "高原王国以石渠引山雪水耕谷地。", detail: { background: "凡湖与阿尔达希尔平原雨少，需以渠与库蓄雪水；乌拉尔图以农与畜为国家税基。", process: "铭刻记阿尔吉什提与萨尔杜里二世凿「穆努亚渠」等工程，渠长数十公里，以石砌暗渠越岗；要塞兼谷仓，窖藏麦以万计（据出土窖位容积推算）。", impact: "这套水利与仓储使乌拉尔图能长期抗亚述，其石作与渠法经亚述与后来的波斯沿用至少数民族山区。", figures: ["穆努亚（乌拉尔图王，铭文所记）"], place: "凡湖与阿尔达希尔平原（今土耳其东部）", state: "乌拉尔图王国", sources: ["凡城与托普拉卡莱楔形水利铭", "《剑桥古代史》第3卷（乌拉尔图章）", "皮奥特罗夫斯基《乌拉尔图王国》"], tags: ["乌拉尔图", "灌溉", "仓储"] }, related: [] },
  { id: "world--b738--i01", track: "world", year: -738, yearApprox: true, dim: "institution", weight: 5, title: "亚述的行省制与驿传", summary: "征服地改为纳粮出兵之省，官道与信驿相连。", detail: { background: "属邦朝贡制易叛，亚述需常设征税、征兵与移民机制。", process: "改革把大邦拆为小省，省督由王任且不得世袭，置军驻、仓库与「书吏之屋」；官道设驿馆，信使以接力传泥板公文，尼姆鲁德出土信件可见调度。", impact: "这是近东第一个成熟的领土行政体系，米底、波斯与罗马的省制、驿传与移民政策多循其成法。", figures: ["提格拉特帕拉沙尔三世", "不可考的省督与书吏"], place: "亚述诸省（两河至地中海东岸）", state: "新亚述帝国", sources: ["尼姆鲁德与尼尼微书信档案", "《亚述帝国行政研究》", "《剑桥古代史》第3卷"], tags: ["行省制", "驿传", "帝国行政"] }, related: [] },
  { id: "world--b735--x01", track: "world", year: -735, yearApprox: true, dim: "explore", weight: 3, title: "优卑亚人取匹特库塞与库迈", summary: "希腊人于那不勒斯湾设最早的两个永久商站。", detail: { background: "伊特鲁里亚的铜、铁与农产品需中转，优卑亚的卡尔基斯与埃雷特里亚争此利。", process: "约前8世纪后期，卡尔基斯人据匹特库塞（今伊斯基亚岛）并建圣所，随后上陆建库迈；出土杯铭以「涅斯托尔杯」之名提及此间饮宴（刻字为希腊字母早期样本）。", impact: "这两站把希腊字母、陶风与农艺传入意大利，也是希腊人与伊特鲁里亚、迦太基三方贸易与冲突的起点。", figures: ["不可考的卡尔基斯航者"], place: "匹特库塞与库迈（今那不勒斯湾）", state: "优卑亚殖民站", sources: ["伊斯基亚与库迈发掘简报", "《大希腊考古指南》", "《剑桥古代史》第4卷"], tags: ["匹特库塞", "库迈", "希腊西迁"] }, related: [] },
  { id: "world--b734--x01", track: "world", year: -734, yearApprox: true, dim: "explore", weight: 3, title: "希腊人建叙拉古", summary: "科林斯移民取西西里东岸最佳双港立城。", detail: { background: "西西里东岸有两处良港与内陆麦地，西边的腓尼基站与东边的西库尔人并存。", process: "修昔底德记阿尔基亚斯率科林斯移民与从属民占奥尔提吉亚岛、逐西库尔人建内城，随后合邦扩地；建城年代依其前后列名推定（今考古以墓地定为证）。", impact: "叙拉古成为西希腊最强城邦与粮出口地，其后与迦太基、雅典与罗马的争夺塑造整个西部地中海史。", figures: ["阿尔基亚斯"], place: "奥尔提吉亚与西西里东岸", state: "叙拉古", sources: ["修昔底德《伯罗奔尼撒战争史》6.2—6.5", "西西里叙拉古考古公园简报", "《剑桥古代史》第4卷"], tags: ["叙拉古", "科林斯", "殖民"] }, related: [] },
  { id: "world--b728--p01", track: "world", year: -728, yearApprox: true, dim: "politics", weight: 2, title: "米底部族的聚合", summary: "亚述文献里的玛达与部族首领开始共戴一王。", detail: { background: "扎格罗斯山南北的玛达诸部无统一王权，常为亚述抄掠对象。", process: "亚述编年史前8世纪后期屡记「玛达之地」的贡与战，希罗多德后记戴奥凯斯裁断争讼、筑埃克巴坦那七重回城（传说成分重，考古仅见大型石基）。", impact: "部的聚合使伊朗高原首次出现可对抗亚述的政体，也为前7世纪米底王国与「玛达大王」称号铺路。", figures: ["戴奥凯斯（传说）"], place: "埃克巴坦那与哈马丹（今伊朗）", state: "米底诸部", sources: ["《亚述王编年史》玛达条", "希罗多德《历史》1.96—1.101", "伊朗考古队哈马丹简报"], tags: ["米底", "部族聚合", "埃克巴坦那"] }, related: [] },
  { id: "world--b722--m01", track: "world", year: -722, yearApprox: true, dim: "military", weight: 4, title: "撒玛利亚陷落与北国流散", summary: "亚述围城三年，迁北国居民于哈腊与古邦。", detail: { background: "以色列何细亚王停贡并通埃及，萨尔贡二世（实录为撒尔根继其父）遣军讨之。", process: "亚述年记前722年取撒玛利亚，徙二万七千二百九十人于哈腊、戈赞之哈布尔与玛达诸城（铭文数字），而以巴比伦、古他等地移民填之；撒玛利亚陶片亦记其人。", impact: "北国教会从此散亡，「失落的十支」成为后世族群传说，而混居产生的撒玛利亚人与耶路撒冷的分裂延续至罗马时代。", figures: ["萨尔贡二世", "何细亚"], place: "撒玛利亚与哈布尔河流域", state: "新亚述帝国与北国以色列", sources: ["萨尔贡二世尼姆鲁德年记", "《希伯来圣经·列王纪下》17章", "撒玛利亚陶片档案"], tags: ["撒玛利亚", "亚述迁徙", "十支派"] }, related: [] },
  { id: "world--b720--m01", track: "world", year: -720, yearApprox: true, dim: "military", weight: 3, title: "第一次美塞尼亚战争", summary: "斯巴达跨过泰格托斯山夺取西部平原。", detail: { background: "斯巴达核心地拉刻达蒙人多地少，美塞尼亚麦地与草场在其西侧。", process: "保塞尼亚斯所传战史以诗人与碑铭为据，记「美塞尼亚之乱」历十余年，伊托梅山为最后据点，斯巴达以分田与定期检阅维持军力；年代与细节学界视为半传说。", impact: "战后美塞尼亚人被固定为希洛农奴，斯巴达由此获得稳定的农业剩余与全民兵制，成为伯罗奔尼撒盟主。", figures: ["忒奥庞普（传说统帅）"], place: "美塞尼亚与伊托梅山", state: "斯巴达城邦", sources: ["保塞尼亚斯《希腊志》4.4—4.26", "修昔底德《伯罗奔尼撒战争史》1.10", "《斯巴达社会史》研究综述"], tags: ["美塞尼亚", "希洛", "斯巴达"] }, related: [] },
  { id: "world--b700--s01", track: "world", year: -700, yearApprox: true, dim: "science", weight: 3, title: "阿拉米字母成近东通用文字", summary: "帝国以阿拉米语与字母行文，楔形泥板退居二线。", detail: { background: "阿拉米部落遍布两河与叙利亚商路，其字母简于书写、易授徒。", process: "新亚述与巴比伦的公文、驿传与条约渐用羊皮与莎草写阿拉米语，提拉夫与哈马特出土的早期阿拉米铭刻可与亚述官方文书相互印证。", impact: "皮革易朽故原件罕存，但此「帝国阿拉米语」成为亚述、波斯乃至犹太回归后的通用书写语，也衍生希伯来、纳巴泰与阿拉伯字母。", figures: ["不可考的亚述与阿拉米书吏"], place: "两河与叙利亚（今叙利亚北部）", state: "新亚述帝国与阿拉米诸邦", sources: ["《阿拉米铭文集成》", "《剑桥古代史》第3卷（字母与通用语章）", "叙利亚文物总局提拉夫报告"], tags: ["阿拉米字母", "通用语", "书写行政"] }, related: [] },
  { id: "world--b700--c01", track: "world", year: -700, yearApprox: true, dim: "culture", weight: 3, title: "赫西俄德的农时与正义", summary: "玻俄提亚农夫诗人写历书与道德训诫入诗行。", detail: { background: "希腊本土小农在贵族争地下常受诉讼与高利之苦，玻俄提亚阿斯克拉地瘠民贫。", process: "《工作与时日》以八十节农事历、天气与禁忌教其弟分产之道，《神谱》则把诸神世系编为谱牒；二篇皆六音步，但自述身世与愤世之语（诗中自称「与农夫同耕」）。", impact: "此作提供了古风希腊农村经济、历法与「正义（狄刻）」观念的第一手材料，也确立了希腊道德训诫诗的传统。", figures: ["赫西俄德"], place: "玻俄提亚阿斯克拉", state: "古风时代希腊", sources: ["赫西俄德《工作与时日》（中文选译本）", "《剑桥古代史》第3卷（古风希腊章）", "奥斯汀《希腊世界的史料（前900—前300年）》"], tags: ["赫西俄德", "农时", "神谱"] }, related: [] },
  { id: "world--b700--p01", track: "world", year: -700, yearApprox: true, dim: "politics", weight: 3, title: "斯基泰人入主南俄草原", summary: "游牧骑射手变黑海北岸为马上联盟。", detail: { background: "马其顿以北的马萨格特与斯基泰诸部因气候与挤压西迁，驱辛梅里人南走高加索。", process: "考古在库班、切尔托梅雷克与米努辛斯克一线见带马具、短剑与动物纹牌的「斯基泰三要素」墓葬；亚述与希腊文献分记其王名与部落名（转写互异）。", impact: "斯基泰控制草原粮、马与奴隶之路，一度逼使米底与亚述北顾；其金工与马具技术经草原带东传西布。", figures: ["斯基泰诸部首领（名多不可考）"], place: "黑海北岸与库班草原", state: "斯基泰诸部联盟", sources: ["希罗多德《历史》第4卷", "黑海北岸库甘墓发掘报告", "《欧亚草原考古》综述"], tags: ["斯基泰", "库甘墓", "草原联盟"] }, related: [] },
  { id: "world--b700--x01", track: "world", year: -700, yearApprox: true, dim: "explore", weight: 2, title: "三列桨船与希腊海运兴起", summary: "冲角战术船连爱琴与西地中海为一片海路。", detail: { background: "殖民与粮运需更大更快的船，腓尼基与埃及的双层桨船先已存在。", process: "修昔底德记科林斯人最早造三列桨船，年代在其建叙拉古前后约六百年（推算即前7世纪）；萨摩斯与科林斯的船坞遗址见滑道与桨架孔（构件为后世复原推定）。", impact: "廉价快速的风帆—桨混合动力使货物、雇佣兵与文字可在数日之内横渡地中海，古风时代的海上世界因此成形。", figures: ["不可考的科林斯船匠"], place: "科林斯湾与萨摩斯", state: "古风希腊诸邦", sources: ["修昔底德《伯罗奔尼撒战争史》1.13", "《雅典三列桨船》研究专著", "科林斯伊奥利亚海坞发掘简报"], tags: ["三列桨船", "海运", "科林斯"] }, related: [] },
  { id: "world--b700--s02", track: "world", year: -700, yearApprox: true, dim: "science", weight: 3, title: "马里卜大坝的修筑", summary: "萨巴人以土石坝与泄道蓄山洪灌田。", detail: { background: "也门鲁姆拉谷雨少而山洪骤至，须以坝蓄水、以渠分配。", process: "萨巴记事碑铭（「哈腊木」碑等）记国王与部落首领修坝、浚渠、设闸与岁修分工，前一千纪中后期已成体系（后世屡加扩建，残址仍可测绘）；灌区面积估算自数百至千余公顷不等（学界有异）。", impact: "这套水利使萨巴成为阿拉伯商路与粮产的核心，碑铭中的部落—官—工役分工是研究前伊斯兰阿拉伯国家的第一手材料。", figures: ["卡里比尔·瓦塔尔（萨巴穆卡里卜，铭刻所记）"], place: "马里卜（今也门）", state: "萨巴王国", sources: ["《南阿拉伯碑铭集成》（马里卜记事碑）", "法国与德国考古队马里卜测绘报告", "《阿拉伯考古与碑铭》综述"], tags: ["大坝", "灌溉", "碑铭"] }, related: [] },
  { id: "world--b691--s01", track: "world", year: -691, yearApprox: true, dim: "science", weight: 3, title: "尼尼微的水渠与杰尔万渡槽", summary: "亚述以五十公里渠系与石渡槽灌溉帝都。", detail: { background: "尼尼微雨量不足以供宫城与园囿，辛那赫里布引哈济尔等山水。", process: "其铭文自述凿山开渠、以石灰岩砌成「跨谷之桥」，杰尔万渡槽残存约二百八十米、有七个拱孔，另有渠道铭文记灌溉宫廷猎苑与棉田（今土耳其费什哈布尔一带）。", impact: "这套工程把美索不达米亚的水利推到新高度，被后世传为「亚述的空中花园」之实底，其拱券与输水法为波斯、罗马所本。", figures: ["辛那赫里布", "不可考的亚述渠匠"], place: "尼尼微周边（今伊拉克摩苏尔近郊）", state: "新亚述帝国", sources: ["辛那赫里布渠道铭文（《古代近东文献》选译）", "杰尔万渡槽调查简报", "《剑桥古代史》第3卷"], tags: ["灌溉", "渡槽", "尼尼微"] }, related: [] },
  { id: "world--b689--m01", track: "world", year: -689, yearApprox: true, dim: "military", weight: 3, title: "辛那赫里布毁巴比伦城", summary: "亚述王引水冲圣城为沼泽，王号亦弃。", detail: { background: "巴比伦屡叛并拥立迦勒底王，亚述之子巴比伦总督被掳后遭杀。", process: "其自述铭记「毁城垣、神庙与塔庙，投碎石于运河」，又记徙其神像、掘沟七道；此等举动在亚述传统中近乎自毁其统治合法性（其诸子弑之于神庙事件后）。", impact: "毁圣城使亚述丧失两河道义正统，以撒哈顿遂以重建巴比伦为政策核心；此事亦见于巴比伦编年史与《以赛亚书》的审判语。", figures: ["辛那赫里布", "马尔杜克神像（被徙者）"], place: "巴比伦城", state: "新亚述帝国", sources: ["巴比伦编年史（残）", "辛那赫里布自述铭", "《剑桥古代史》第3卷"], tags: ["毁城", "巴比伦", "正统危机"] }, related: [] },
  { id: "world--b680--c01", track: "world", year: -680, yearApprox: true, dim: "culture", weight: 3, title: "《奥义书》与梵我之辨", summary: "森林书时代哲人转祭祀为内在之知。", detail: { background: "婆罗门垄断繁祭，苦行者与王族学者在森林聚会论「不死」与轮回，时代属前8—前6世纪（学界推定）。", process: "《广林奥义书》《歌集奥义书》等以师徒问答立论，提出「汝即彼」（梵我同一）、业报轮回与解脱之道，否定仅靠献祭得救。", impact: "此转向成为印度哲学的公共底版，佛教、耆那教与后来的六派皆在其语境内回应，其说经近代译介进入欧洲思想界。", figures: ["耶若伏基耶（传说中的论者）", "阇那迦（毗提诃王，问者）"], place: "俱卢—般遮罗与恒河上游森林区", state: "后期吠陀智识诸团", sources: ["《八十奥义书》选译本", "《剑桥印度史》第1卷（奥义书章）", "《吠陀文献研究导论》"], tags: ["奥义书", "梵我", "轮回"] }, related: [] },
  { id: "world--b680--e01", track: "world", year: -680, yearApprox: true, dim: "economy", weight: 3, title: "恒河平原的第二波城市化", summary: "北方黑亮陶与铸币标志着恒河城市的再生。", detail: { background: "铁器稻作与人口东渐之后，恒河中游出现大型聚落与防御壕沟。", process: "王舍城、吠舍离、桥赏弥等遗址见夯土城墙、排水沟与「北方黑亮陶」器群，刻有铭印的穿孔钱币（原始币）同期出现，货物品类与手工业分区明显增加（发掘报告统计）。", impact: "农业剩余与手工业分工使国家税基脱离部落献祭，为十六大国与摩揭陀的常设官制准备条件。", figures: ["不可考的恒河城邑工匠"], place: "恒河中游（今比哈尔与北方邦）", state: "恒河城市诸邦", sources: ["《印度考古调查》吠舍离报告", "《剑桥印度史》第1卷（第二次城市化章）", "穿孔币研究专刊"], tags: ["北方黑亮陶", "铸币", "城市化"] }, related: [] },
  { id: "world--b671--m01", track: "world", year: -671, yearApprox: true, dim: "military", weight: 3, title: "亚述军首次打入埃及", summary: "以撒哈顿沿地中海东岸西进，破孟菲斯。", detail: { background: "库施第25王朝支持腓尼基与三角洲诸侯抗亚述，属邦接连叛乱。", process: "其年记与胜利铭记其越西奈、历十二次战至孟菲斯，屠城徙民；又自称为「埃及与帕特罗斯之王」（王室称号，实际控制区有限）。", impact: "尼罗河谷第一次受两河帝国的军事打击，地方诸侯（后来的塞伊特家）由此取得在亚述与库施之间取利的空间。", figures: ["以撒哈顿", "塔哈卡（库施王）"], place: "西奈至孟菲斯（今埃及北）", state: "新亚述帝国与埃及", sources: ["以撒哈顿年记与胜利铭", "《剑桥古代史》第3卷", "大英博物馆亚述楔形文书藏目"], tags: ["埃及征伐", "孟菲斯", "属邦"] }, related: [] },
  { id: "world--b664--p01", track: "world", year: -664, yearApprox: true, dim: "politics", weight: 3, title: "塞伊特王朝复辟", summary: "尼罗河三角洲诸侯之一统一埃及，引希腊佣兵。", detail: { background: "亚述退兵后三角洲二十余地方侯并立，尼科家族亲亚述、再亲亚述覆亡后的新秩序。", process: "普萨美提克一世借卡里亚与伊奥尼亚雇佣兵胜敌对诸侯，又与吕底亚结和，前656年左右统一上下埃及（古典作家与埃及碑铭所记略有出入）。", impact: "第26王朝以开放商贸与复古文化重振埃及，其希腊商人与雇佣兵政策改变埃及兵源与财政结构，也埋下外权干预之端。", figures: ["普萨美提克一世", "尼科"], place: "塞易斯与孟菲斯", state: "埃及第26王朝", sources: ["塞伊特王朝碑铭（塞拉皮斯甬道纪年石）", "希罗多德《历史》2.152—2.182", "《剑桥古代史》第3卷"], tags: ["塞伊特", "希腊佣兵", "复辟"] }, related: [] },
  { id: "world--b663--m01", track: "world", year: -663, yearApprox: true, dim: "military", weight: 4, title: "亚述陷底比斯", summary: "亚述巴尼拔焚上埃及圣城，库施势力南退。", detail: { background: "三角洲附庸与库施王坦乌塔蒙在底比斯复起，切断亚述的尼罗河税线。", process: "其年记记围底比斯、「以火取城」，徙其二人与大量金银、四万二千名居民至亚述（铭文数字），并掠方尖与铜门；底比斯神庙群此后百年不复其盛。", impact: "埃及彻底脱离库施王朝，塞伊特家成唯一王族；此事也震动闪族世界，《那鸿书》以「尼亚孟之毁」为喻。", figures: ["亚述巴尼拔", "坦乌塔蒙"], place: "底比斯（今卢克索）", state: "新亚述帝国", sources: ["亚述巴尼拔年记（《古代近东文献》选译）", "《希伯来圣经·那鸿书》3.8—3.10", "底比斯考古层报告"], tags: ["底比斯", "劫掠", "库施"] }, related: [] },
  { id: "world--b660--f01", track: "world", year: -660, yearApprox: true, dim: "figure", weight: 3, title: "半传说中的立法者来库古", summary: "斯巴达以一整套制度归诸一人，其人或非实有。", detail: { background: "古风时代斯巴达需要一套可上溯的「祖制」以约束贵族；普鲁塔克辑诸说。", process: "传统把他置于美塞尼亚战争时期，记其得德尔菲神谕而立「大瑞特拉」：公餐、公共教育、土地均分、金银币改铁条、三十老臣与二王制（部分制度为后世渐进产物）。", impact: "「来库古立法」成为希腊世界对斯巴达平等人制度的解释框架，也启发波利比乌斯与后来的混合政体论。", figures: ["来库古", "普鲁塔克（记述者）"], place: "斯巴达", state: "斯巴达城邦", sources: ["普鲁塔克《希腊罗马名人传·来库古传》", "修昔底德《伯罗奔尼撒战争史》1.18", "《斯巴达古风制度研究》综述"], tags: ["来库古", "大瑞特拉", "祖制"] }, related: [] },
  { id: "world--b660--i01", track: "world", year: -660, yearApprox: true, dim: "institution", weight: 3, title: "希洛制与斯巴达平等人", summary: "受缚农人与全权公民，构成一城的两个部分。", detail: { background: "美塞尼亚战争后，被征服者被固着于土地，公民则脱产专事军役。", process: "希洛按户纳固定谷与油（传统记一半之产归公民），公餐制使公民同食同训，七八岁起入集体训练，六十岁可入选老会（制度定型年代学界推定在前7—前6世纪）。", impact: "这一体制使斯巴达维持希腊最强的重装步兵，但希洛的世袭隶属与定期鞭挞也造成斯巴达长期的内部安全焦虑。", figures: ["不可考的斯巴达监察官"], place: "拉刻达蒙与美塞尼亚", state: "斯巴达城邦", sources: ["普鲁塔克《来库古传》", "色诺芬《拉刻达蒙政制》", "《剑桥斯巴达史》"], tags: ["希洛", "公餐", "公民兵"] }, related: [] },
  { id: "world--b657--p01", track: "world", year: -657, yearApprox: true, dim: "politics", weight: 3, title: "科林斯的库普塞洛斯僭政", summary: "巴基斯家族之外的人以武力取城，开希腊僭政之例。", detail: { background: "科林斯由巴基斯氏族垄断官职与良田，失势者与新兴商人不满。", process: "亚里士多德《政治学》与希罗多德记其凭阿耳戈斯援兵与神谕之助据卫城，未杀民而徙部分贵族；其子佩里安德与米利都、吕底亚通使，建海坞与神庙。", impact: "僭主政治打破贵族世袭、扶植工商与殖民，为后来的平民立法铺路，但也成为希腊语中「非法统治」的原型词。", figures: ["库普塞洛斯", "佩里安德"], place: "科林斯", state: "科林斯城邦", sources: ["亚里士多德《政治学》1310b—1315b", "希罗多德《历史》5.92", "《剑桥古代史》第3卷（僭主章）"], tags: ["僭主", "科林斯", "巴基斯"] }, related: [] },
  { id: "world--b650--f01", track: "world", year: -650, yearApprox: true, dim: "figure", weight: 2, title: "阿基洛科斯与个人之声", summary: "帕罗斯雇佣兵诗人，首次署名自陈于诗。", detail: { background: "诗人为贵族宴饮与战场而作，此前长诗多归于神与英雄。", process: "其残篇（编号一百二十余条，多为引述所存）记帕罗斯殖民之败、盾牌失落之耻与对吕卡姆贝斯姐妹的情欲，以短长格与讽刺诗体写个人怨怒。", impact: "「以第一人称说话」由此进入希腊文学，讽刺短诗亦成为政治攻击与个人情绪的双重工具。", figures: ["阿基洛科斯"], place: "帕罗斯与塔索斯", state: "古风希腊（爱奥尼亚圈）", sources: ["《希腊抒情诗残篇》（韦斯特校勘本）", "《剑桥古代史》第3卷（抒情诗章）"], tags: ["抒情诗", "残篇", "署名"] }, related: [] },
  { id: "world--b650--e01", track: "world", year: -650, yearApprox: true, dim: "economy", weight: 5, title: "吕底亚的早期铸币", summary: "以天然金银合金压出印记，金属价值由公共担保。", detail: { background: "帕克托洛斯河产电金币，近东长期以银块称重计值，伪造与称重皆费事。", process: "今土耳其萨迪斯与以弗所遗址出土早期电金币，一面为狮首或鹿头，按「米勒都标准」自14.2克至0.4克分为多级（重量级数由化验统计），年代推定前7世纪后期至前6世纪初（学界仍争）。", impact: "铸币把国家信用与交换合一，此后税收、军饷、商业与城邦财政皆可计数；希腊、波斯与罗马的货币史由此开端。", figures: ["不可考的吕底亚铸工与王室"], place: "萨迪斯与以弗所（今土耳其西海岸）", state: "吕底亚王国与爱奥尼亚诸邦", sources: ["大英博物馆《早期铸币》目录", "《古代希腊世界的货币与用途》研究综述", "萨迪斯考古队出土币层报告"], tags: ["铸币", "电金币", "国家信用"] }, related: [] },
  { id: "world--b645--s01", track: "world", year: -645, yearApprox: true, dim: "science", weight: 3, title: "亚述巴尼拔的王家图书馆", summary: "尼尼微以抄本与目录聚两河知识于一宫。", detail: { background: "亚述王遣书吏往巴比伦、乌尔、乌鲁克抄录与索取泥板，征发豁免权亦见于令文。", process: "库云吉克出土泥板逾三万片，其中抄本按篇首语归类，牌上记「世界的仓库、亚述王之宫」及「若缺行则如何补」的校勘语，含医、卜、天文、数学与文学（考古登记与目录泥板）。", impact: "《吉尔伽美什》《阿特拉哈西斯》与天文日志赖此得存，近代亚述学即由此奠基；它也是人类最早有明确目录意识的大型藏书机构之一。", figures: ["亚述巴尼拔", "西诺-莱奇-乌尼尼（早期校订书吏传统）"], place: "尼尼微西南宫（今库云吉克）", state: "新亚述帝国", sources: ["大英博物馆尼尼微泥板登记目", "《亚述巴尼拔王室铭文》", "《巴比伦文学史》专著综述"], tags: ["图书馆", "泥板目录", "亚述学"] }, related: [] },
  { id: "world--b640--a01", track: "world", year: -640, yearApprox: true, dim: "art", weight: 3, title: "尼尼微宫中的猎狮图", summary: "石膏壁板写王猎为慢镜头的死亡序列。", detail: { background: "亚述宫廷浮雕以王为宇宙秩序的执矛者，猎狮与战争同属一类叙事。", process: "北宫出土猎狮系列长逾十米，狮中箭、坠崖、被矛刺诸态并列，猎犬与持盾兵前后呼应，刻工以浅阳线与细毛纹区分毛色与肌肉（风格分析）。", impact: "这批壁板是古代近东最具写实力量的作品，随大英博物馆藏品的公开展出而成为西方艺术史叙述中的坐标。", figures: ["不可考的尼尼微刻工"], place: "尼尼微北宫", state: "新亚述帝国", sources: ["大英博物馆西亚藏品目（猎狮壁板）", "《亚述艺术》专著综述","马洛温《尼姆鲁德与尼尼微发掘史》"], tags: ["猎狮", "宫殿浮雕", "写实"] }, related: [] },
  { id: "world--b630--a01", track: "world", year: -630, yearApprox: true, dim: "art", weight: 2, title: "科林斯黑像陶绘", summary: "东方纹样与神话场面进入小亚细亚式陶瓶。", detail: { background: "科林斯控制东西海运，取埃及与叙利亚纹样制成出口陶器。", process: "陶面以黑像剪影加刻线与紫、白彩，常见动物带、战神出发、狄奥尼索斯宴饮；壶形取自近东皮囊与鹧鸪罐，纪年依类型学排在前625—前580（学界分期）。", impact: "此风传入雅典后发育出阿提卡黑像与红像技法，希腊陶绘成为地中海世界的图像流通媒介与断代标尺。", figures: ["克勒提阿斯（传说中的科林斯画师）"], place: "科林斯与克拉尼库斯墓区", state: "科林斯城邦", sources: ["《科林斯考古发掘》陶绘卷", "《希腊陶绘通论》", "卢浮宫藏品目"], tags: ["黑像", "陶绘", "东方化"] }, related: [] },
  { id: "world--b626--p01", track: "world", year: -626, yearApprox: true, dim: "politics", weight: 4, title: "那波帕拉萨尔巴比伦自立", summary: "迦勒底首领称王，四十二年反亚述战争开始。", detail: { background: "亚述巴尼拔死后帝国陷于兄弟内战，巴比伦的迦勒底部落欲脱贡。", process: "其编年史自述即位当年「不敬亚述之轭」，前623年亚述派兵来讨失利，前620年前后其据城称「巴比伦之王」，与玛达、斯基泰人约而北不戒。", impact: "巴比伦的独立把亚述推入两线作战，为前612年尼尼微之亡铺路；其子尼布甲尼撒二世遂成近东新霸主。", figures: ["那波帕拉萨尔"], place: "巴比伦与巴尔萨帕", state: "新巴比伦王国", sources: ["那波帕拉萨尔编年史残片", "巴比伦王表", "《剑桥古代史》第3卷"], tags: ["新巴比伦", "独立", "编年史"] }, related: [] },
  { id: "world--b625--i01", track: "world", year: -625, yearApprox: true, dim: "institution", weight: 3, title: "基亚克萨雷斯整编米底军", summary: "玛代军分持矛、射、投三队，始能远征。", detail: { background: "此前伊朗游牧武装以家族为单位，难以持久围城与野战协同。", process: "希罗多德记基亚克萨雷斯「把众人分为持矛手、弓箭手与投石手」，并以常制粮饷替代劫掠分红（记述属后世整理）；亚述编年史同期记玛达王名乌克沙里纳。", impact: "军制改革使米底能协同巴比伦攻灭亚述，并前612年后取安纳托利亚东部，成为近东五强之一。", figures: ["基亚克萨雷斯"], place: "埃克巴坦那与哈马丹", state: "米底王国", sources: ["希罗多德《历史》1.103", "巴比伦编年史（玛达条）", "《伊朗剑桥史》第2卷（米底章）"], tags: ["米底军制", "三队", "远征"] }, related: [] },
  { id: "world--b624--a01", track: "world", year: -624, yearApprox: true, dim: "art", weight: 2, title: "斯基泰的动物纹金工", summary: "草原墓里的金饰以蜷伏的鹿与噬咬的猛兽为母题。", detail: { background: "游牧贵族以金饰标身份，工匠兼收近东与希腊纹法。", process: "库兰、托勒巴等库甘墓出金牌、带扣与嵌片，构图为盘角羊蜷卧、狮噬马、鹿纵跃，多以薄片锤揲并填彩（出土登记与金相分析）。", impact: "这种紧凑、动势强烈的装饰语汇沿草原带流传，远及南西伯利亚与鄂尔多斯，成为欧亚「动物风格」的共同底本。", figures: ["不可考的草原金匠"], place: "黑海北岸与阿尔泰", state: "斯基泰诸部", sources: ["埃尔米塔日博物馆草原金器藏目", "《欧亚动物风格艺术》专著综述", "库兰墓发掘简报"], tags: ["动物纹", "金工", "草原"] }, related: [] },
  { id: "world--b621--i01", track: "world", year: -621, yearApprox: true, dim: "institution", weight: 4, title: "德拉古的成文法", summary: "雅典刻血罪与债务规则于木板，公之于众。", detail: { background: "贵族解释口传习惯法，基隆事件后「不守法」之怨沸腾。", process: "亚里士多德《雅典政制》记其任执政官之年立法：杀人罪分故意、无意与自愿三种，血族复仇受程序限制，债务奴隶身份仍未废；法成后「皆刻于板材悬于柱」（原文记述）。", impact: "成文法使裁判必须依条文，贵族的裁量空间第一次被公开文本约束，其「严苛」之名遂成西方法律史的成语。", figures: ["德拉古"], place: "雅典", state: "雅典城邦", sources: ["亚里士多德《雅典政制》4.1—4.5", "《德摩斯提尼演说辞》24.42（引德拉古法）", "《剑桥古代史》第4卷"], tags: ["成文法", "血罪", "德拉古"] }, related: [] },
  { id: "world--b612--m01", track: "world", year: -612, yearApprox: true, dim: "military", weight: 5, title: "尼尼微陷落与亚述亡国", summary: "米底与巴比伦联军屠帝都，两河霸权易手。", detail: { background: "亚述巴尼拔死后诸王内争，属邦停贡；那波帕拉萨尔与基亚克萨雷斯结姻盟（巴比伦编年史与后世记述所合）。", process: "前612年联军围城三月，破后焚宫掠庙，「以其财分与玛达人、巴比伦人」（编年史语）；前610年哈兰陷落，末将亚述乌巴利特二世与埃及残军退至卡尔凯美什。", impact: "亚述的省制、驿传、军器与图像传统被战胜者全盘接收，波斯帝国由此继承其行政遗产；旧霸主的崩溃重塑近东均势。", figures: ["那波帕拉萨尔", "基亚克萨雷斯", "辛沙里沙昆（亚述末王，战死于宫中）"], place: "尼尼微（今摩苏尔对岸）", state: "新亚述帝国与新巴比伦、米底", sources: ["巴比伦编年史（尼尼微陷落条）", "南希·桑德斯《巴比伦编年史》译注", "《剑桥古代史》第3卷"], tags: ["尼尼微", "屠城", "霸权转移"] }, related: [] },
  { id: "world--b609--m01", track: "world", year: -609, yearApprox: true, dim: "military", weight: 3, title: "米吉多之战与约西亚之死", summary: "犹大王拦阻埃及北进，战死于耶斯列。", detail: { background: "亚述覆灭后法老尼科二世率军北上，欲在幼发拉底接应残余亚述军。", process: "列王纪下与巴比伦编年史分别记尼科沿海岸北上、约西亚在米吉多拦截被杀，随后埃及废犹大王约阿哈斯、立其弟约雅金为傀儡并取银三百他连得为贡（数字见经文）。", impact: "犹大自此成为埃及属邦又被迫向巴比伦摇摆，十年内即遭灭国之祸；此役也标志埃及最后一次在近东争霸的开端。", figures: ["尼科二世", "约西亚"], place: "米吉多与耶斯列平原", state: "埃及第26王朝与犹大", sources: ["《希伯来圣经·列王纪下》23:29—35", "巴比伦编年史（埃及役条）", "《剑桥古代史》第3卷"], tags: ["米吉多", "约西亚", "属邦"] }, related: [] },
  { id: "world--b605--m01", track: "world", year: -605, yearApprox: true, dim: "military", weight: 3, title: "卡尔凯美什战役", summary: "尼布甲尼撒三日战定叙利亚，埃及退回南方。", detail: { background: "两强皆控不住幼发拉底上游，亚述残军已灭，叙利亚诸城观望。", process: "巴比伦王位继承战记其以父丧急返即位，而先令将领留叙利亚；编年史前604年12月条记取亚实基伦、杀其王，此后腓尼基诸城逐年纳贡。", impact: "两河帝国再度领有地中海东岸，新巴比伦的「叙利亚—巴勒斯坦走廊」战略成立，犹大与推罗进入纳贡与叛服的循环。", figures: ["尼布甲尼撒二世", "尼科二世"], place: "幼发拉底河卡尔凯美什", state: "新巴比伦王国", sources: ["巴比伦编年史（前605—601年条）", "《埃及与近东》研究综述", "《剑桥古代史》第3卷"], tags: ["卡尔凯美什", "叙利亚", "纳贡"] }, related: [] },
  { id: "world--b600--x01", track: "world", year: -600, yearApprox: true, dim: "explore", weight: 3, title: "尼科二世的运河与环航", summary: "法老开尼罗—红海水道，并遣腓尼基人绕非洲。", detail: { background: "埃及欲夺红海香料与印度洋商路，绕好望角者须借推罗水手。", process: "希罗多德记运河起自布巴斯提斯附近、通阿拉伯湾，「历时四年，民死者十二万」（数字为其所闻）；又记腓尼基船队「太阳在右手边」地绕行利比亚（其说在后世被采信）。", impact: "此运河为苏伊士运河的前身，环航之说证明古代水手已能利用季风与西岸洋流；两条记载都是地中海—印度洋交通史的早期凭据。", figures: ["尼科二世", "不可考的腓尼基船长"], place: "瓦迪图米拉特至苏伊士湾", state: "埃及第26王朝", sources: ["希罗多德《历史》2.158—2.159、4.42", "塞拉皮斯与苏伊士古运河考古调查", "《非洲通史》第2卷"], tags: ["古运河", "环航非洲", "红海"] }, related: [] },
  { id: "world--b600--p01", track: "world", year: -600, yearApprox: true, dim: "politics", weight: 3, title: "十六大国与摩揭陀兴起", summary: "恒河平原并起城邦王国，跋耆联盟与摩揭陀对峙。", detail: { background: "《本生经》与耆那教文献列十六大国（摩揭陀、憍萨罗、跋耆、阿槃提等），吠舍离与王舍城为其要地。", process: "跋耆等以「吠舍离大会」与口头表决（文献所述）行寡头共和，摩揭陀则世袭王权、筑城设库；频毗沙罗王取憍萨罗之半与安陀商路（佛典所记）。", impact: "这一竞争格局为佛教、耆那教提供听众与施主，也促成税收、常备军与官僚制的试验场，印度国家形态由此定型。", figures: ["频毗沙罗王", "离车诸族长老"], place: "王舍城与吠舍离", state: "摩揭陀与跋耆联盟", sources: ["《巴利律藏》与《本生经》国名条", "《剑桥印度史》第1卷（十六大国章）", "吠舍离与王舍城考古简报"], tags: ["十六大国", "寡头共和", "摩揭陀"] }, related: [] },
  { id: "world--b600--a01", track: "world", year: -600, yearApprox: true, dim: "art", weight: 3, title: "萨福与莱斯博斯的歌派", summary: "女诗人为少女合唱写婚歌与宴歌，残篇犹带音节。", detail: { background: "莱斯博斯的米蒂利尼贵族文化重宴饮与少女教育，合唱诗人受雇编制歌词。", process: "萨福今存完整者仅一二篇、残句逾千行，其以十一音节「萨福格律」写阿佛洛狄忒颂与相思，柏拉图《会饮》与朗吉努斯《论崇高》各引其句；其团契中女弟子之名见于残篇（阿提斯、昆古拉等）。", impact: "个人情感的抒情体成为欧洲诗歌的源头之一，「萨福」与「莱斯博斯」在后世语言中化为女性之爱与诗艺的语根。", figures: ["萨福"], place: "莱斯博斯岛米蒂利尼", state: "古风希腊", sources: ["《希腊抒情诗残篇》（沃伊特校勘本）", "朗吉努斯《论崇高》8.2", "《剑桥古代史》第4卷（抒情诗章）"], tags: ["萨福", "抒情诗", "合唱"] }, related: [] },
  { id: "world--b597--m01", track: "world", year: -597, yearApprox: true, dim: "military", weight: 3, title: "耶路撒冷第一次失守", summary: "巴比伦兵临犹大，徙王与工匠精英东迁。", detail: { background: "约雅金在埃及与巴比伦之间背盟停贡，尼布甲尼撒遣将东征。", process: "巴比伦编年史前597年2月（「亚达月」）条记「取城、擒其王、立其所愿之王，取其金银宝器归于巴比伦」；列王纪记徙王后、太监、勇士、匠人与铁工七千（数字为经文所列）。", impact: "「工匠与精英」的先期流散使巴比伦与后来的波斯出现犹太社群，圣经文学与祭司传统在流亡语境中加速编订。", figures: ["尼布甲尼撒二世", "约雅斤"], place: "耶路撒冷与巴比伦", state: "新巴比伦王国与犹大", sources: ["巴比伦编年史（前597年条）", "《希伯来圣经·列王纪下》24:10—16", "拉吉陶片档案"], tags: ["第一次流放", "约雅斤", "编年史"] }, related: [] },
  { id: "world--b594--i01", track: "world", year: -594, yearApprox: true, dim: "institution", weight: 5, title: "梭伦的解负令与财产等级", summary: "雅典废债奴、按收入定官职，重划公民权利。", detail: { background: "小农以人身抵债，卖身为奴与外邦流亡相续；基隆余党与贵族争地不解。", process: "梭伦任仲裁执政，行「卸负」：拔债碑、禁以人身为质、召回被卖者；按五百斗、三斗、二百斗、一斗四级定兵役与官职，设四百人会议与人民陪审法庭（普鲁塔克与亚里士多德分述其令）。", impact: "它既未满足重分土地的请求，也终结了贵族对法的垄断：以财产取代血缘为政治资格，为克里斯提尼的民主铺平制度前提。", figures: ["梭伦"], place: "雅典", state: "雅典城邦", sources: ["亚里士多德《雅典政制》5—12章", "梭伦残诗（韦斯特校勘本）", "普鲁塔克《梭伦传》"], tags: ["解负令", "财产等级", "陪审法庭"] }, related: [] },
  { id: "world--b590--e01", track: "world", year: -590, yearApprox: true, dim: "economy", weight: 3, title: "雅典陶器与谷物的海上贸易", summary: "油、陶与银换黑海的麦，凯拉米克斯陶窑扩展。", detail: { background: "阿提卡少麦多油，僭主时代奖励陶工与铸币以补粮差。", process: "前6世纪后期阿提卡黑像瓶大量出土于伊特鲁里亚墓、西班牙与黑海北岸（西西里与刻赤出土统计以千计），同期雅典「猫头鹰」前的铸币以四德拉克马为大宗。", impact: "陶器贸易带来现金与外交网络，使雅典在希腊内部以富商与舰队立身，其粮依赖海路的结构性弱点也同时形成。", figures: ["不可考的凯拉米克斯陶工"], place: "雅典凯拉米克斯与比雷埃夫斯", state: "雅典城邦", sources: ["《阿提卡陶绘通论》", "《希腊经济社会史》专著综述", "黑海殖民地出土陶统计"], tags: ["陶器贸易", "谷物", "铸币"] }, related: [] },
  { id: "world--b586--m01", track: "world", year: -586, yearApprox: true, dim: "military", weight: 5, title: "耶路撒冷陷落与圣殿焚毁", summary: "十八月围城后城破，犹大国有与第一圣殿俱亡。", detail: { background: "西底家停贡并求埃及援，巴比伦军围耶路撒冷（前588年冬起，编年史与经文互校）。", process: "耶利米书与列王纪记城内饥至相食，城破后王族西逃被擒、诸子杀于其前，尼布扎拉旦焚耶和华殿、宫室与民宅，又徙余民（经文分三次记人数，共数千）。", impact: "「巴比伦之囚」使犹大从王国变为行省，先知文学与申命派史家转而以律法、会堂与个人之信重构认同，成为犹太教之基。", figures: ["西底家", "尼布扎拉旦", "耶利米"], place: "耶路撒冷与巴比伦", state: "新巴比伦王国与犹大", sources: ["《希伯来圣经·列王纪下》25章", "拉吉陶片（主前588—587年书信）", "巴比伦编年史残条"], tags: ["圣殿被焚", "巴比伦之囚", "流散"] }, related: [] },
  { id: "world--b585--f01", track: "world", year: -585, yearApprox: true, dim: "figure", weight: 3, title: "泰勒斯与自然解释的开端", summary: "米利都人不借神话而以求水与预测日食立说。", detail: { background: "米利都是黑海商路与近东天文历数交汇的富港，学者无需神庙即可授徒。", process: "传统以其「万物本原是水」与测得前585年5月28日日食（推算与希罗多德所记米底—吕底亚停战同日）著名，另传其测金字塔影、制航海星表（多属后世追记，真伪学界有辨）。", impact: "以可检验的自然因解释世界，由此成为希腊科学与哲学的起点，亚里士多德《形而上学》即以他为第一人。", figures: ["泰勒斯"], place: "米利都（今土耳其西海岸）", state: "爱奥尼亚希腊", sources: ["亚里士多德《形而上学》983b", "希罗多德《历史》1.74", "《早期希腊自然哲学》专著综述"], tags: ["泰勒斯", "本原", "日食"] }, related: [] },
  { id: "world--b582--c01", track: "world", year: -582, yearApprox: true, dim: "culture", weight: 3, title: "德尔菲神谕与皮提亚竞技", summary: "阿波罗的答复、金库与赛会构成泛希腊权威。", detail: { background: "「神圣战争」后近邻同盟掌圣所，殖民与立法常须请示神谕。", process: "前582年增设皮提亚竞技（起初仅有歌声祭神，后加车赛马与五项）；遗址见科林斯、西库昂、吕底亚与雅典的金库台基，铭文存大量「释放奴隶献给阿波罗」的卖身—释奴记录。", impact: "神谕使远隔的城邦在同一套仪式与历法中相互承认，德尔菲由此成为希腊世界的道德与外交仲裁场。", figures: ["不可考的德尔菲女祭司"], place: "福基斯德尔菲", state: "近邻同盟与德尔菲圣所", sources: ["希腊考古院德尔菲发掘报告（金库与铭文卷）", "《希腊神谕与献祭》研究综述", "《剑桥古代史》第4卷"], tags: ["神谕", "皮提亚", "金库"] }, related: [] },
  { id: "world--b570--p01", track: "world", year: -570, yearApprox: true, dim: "politics", weight: 3, title: "庇西特拉图的僭政与工程", summary: "三次夺权的雅典僭主以土地、神庙与节庆收民心。", detail: { background: "平地、海岸与山地三派贵族的党争使梭伦之后仍有混乱。", process: "其以山地派为基础，前561年夺卫城，两度被逐后借底比斯援兵复起；没收部分贵族田土贷予小农，建宙斯神庙与恩涅亚诺鲁泉，移泛雅典娜节为四年大赛并加竞技（修昔底德与《雅典政制》分记）。", impact: "僭政使阿提卡的农产、陶器与铸币对外扩张，神庙与节庆成为城邦共同体的粘合剂，但「僭主」此后在雅典记忆中成为自由的反面。", figures: ["庇西特拉图", "许庇尔科斯（其子）"], place: "雅典与苏尼翁", state: "雅典城邦", sources: ["亚里士多德《雅典政制》13—19章", "希罗多德《历史》1.59—1.64、5.55—5.61", "《剑桥古代史》第4卷"], tags: ["僭主", "公共工程", "泛雅典娜"] }, related: [] },
  { id: "world--b570--i01", track: "world", year: -570, yearApprox: true, dim: "institution", weight: 3, title: "诺克拉提斯：共管的埃及商埠", summary: "希腊诸邦于尼罗河支流通用一个受税口岸。", detail: { background: "塞伊特王朝需希腊银、兵与油，又忌外人散居内地，故划一城管制。", process: "遗址见分属米利都、西库昂、埃伊纳等邦的祭所与商站、统一的重秤与税台；考古在其层中出土大量阿提卡、科林斯与塞浦路斯陶（今塔勒赫·法拉姆发掘登记）。", impact: "此制既是古代「限定通商口岸」的原型，也让希腊人深入了解埃及的物产与制度，希罗多德的埃及见闻即承此传统。", figures: ["阿玛西斯（埃及王，制度之设者）"], place: "诺克拉提斯（今塔勒赫·法拉姆）", state: "埃及第26王朝与希腊诸邦", sources: ["弗林德斯·皮特里《诺克拉提斯与希腊商站》发掘报告", "希罗多德《历史》2.178", "《剑桥古代史》第4卷"], tags: ["商埠", "关税", "希埃交流"] }, related: [] },
  { id: "world--b560--e01", track: "world", year: -560, yearApprox: true, dim: "economy", weight: 3, title: "克罗伊斯的纯金币", summary: "吕底亚王以纯金与纯银的二级币制取代电金。", detail: { background: "电金成色自然浮动，大额支付与军饷需要稳定面值。", process: "萨迪斯出土「克罗伊斯金」厚币，重约10.7克与5.35克两级，含纯金近百分之百，正面双狮头、面牛鹿（金相分析与币型学）；古典作家记其对德尔菲大量献金，金库基座刻其铭。", impact: "金银双本位的雏形使近东与希腊的国际支付有了基准货币，也确立「以铸币显示王权」的惯例，波斯大流士的金达里克沿用其制。", figures: ["克罗伊斯"], place: "萨迪斯与德尔菲", state: "吕底亚王国", sources: ["大英博物馆吕底亚金币藏目", "希罗多德《历史》1.24—1.54", "萨迪斯考古队铸币报告"], tags: ["克罗伊斯", "金币", "本位"] }, related: [] },
  { id: "world--b550--p01", track: "world", year: -550, yearApprox: true, dim: "politics", weight: 5, title: "居鲁士取埃克巴坦那", summary: "波斯王反戈灭米底，伊朗高原归于一姓。", detail: { background: "安善的居鲁士为米底王阿斯提阿格斯的附庸与（传统所说）外孙，波斯诸部纳贡已久。", process: "拿波尼度编年史记「玛达之众叛其王，拥居鲁士王」，前550年冬取埃克巴坦那，获其金银而徙其民；居鲁士不毁其城，仍用米底官制（圆柱铭文与编年史互校）。", impact: "米底的骑射、宫廷礼仪与行省经验并入波斯，从此「波斯」成为近东最强国的名字，爱奥尼亚与巴比伦失去缓冲。", figures: ["居鲁士二世", "阿斯提阿格斯"], place: "埃克巴坦那（今哈马丹）", state: "波斯（阿契美尼德王朝初）", sources: ["拿波尼度编年史（前550年条）", "居鲁士圆柱铭文", "《伊朗剑桥史》第2卷"], tags: ["居鲁士", "灭米底", "阿契美尼德"] }, related: [] },
  { id: "world--b550--f01", track: "world", year: -550, yearApprox: true, dim: "figure", weight: 3, title: "阿那克西曼德与最早的世界图", summary: "米利都人画已知世界为图，并论万物之本。", detail: { background: "泰勒斯之后，米利都学者继续以自然因解释天地，航海与殖民扩大地理知识。", process: "传其绘第一幅希腊世界图（以爱琴海为中心、陆地环海）、立日晷与测时器、定春秋分与至日，并提出万物源于「阿裴朗」（无定者）、生物由湿润经日光变化而生（残篇与后世转引，真伪有辨）。", impact: "地图与宇宙论由此成为可修改的公共模型，其「无限」之说与生物起源之见被后世视为科学与哲学分离的起点。", figures: ["阿那克西曼德"], place: "米利都（今土耳其西海岸）", state: "爱奥尼亚希腊", sources: ["《早期希腊哲学家残篇》（狄尔斯—克兰茨编）", "希波吕图斯《哲学的颠覆》一卷（转引）", "《早期希腊自然哲学》专著综述"], tags: ["世界图", "阿裴朗", "米利都"] }, related: [] },
  { id: "world--b546--m01", track: "world", year: -546, yearApprox: true, dim: "military", weight: 4, title: "波斯取萨迪斯", summary: "十四天围城破吕底亚，骑兵平原决胜负。", detail: { background: "克罗伊斯先渡哈吕斯河攻卡帕多西亚，居鲁士乘其撤退追击。", process: "古典记载与编年史互校：普特里亚之战后吕军解散返国，波斯骑兵直取萨迪斯，城以「素未设防的山脊一侧」被攀上而陷（希罗多德所记）；克罗伊斯被俘，居鲁士恕其性命（一说处火堆而得雨）。", impact: "吕底亚的金银与造船地入波斯，爱奥尼亚希腊城邦被迫纳贡并出舰队，希波之间第一次共享边界，冲突伏线自此埋下。", figures: ["居鲁士二世", "克罗伊斯"], place: "普特里亚与萨迪斯", state: "波斯帝国与吕底亚", sources: ["希罗多德《历史》1.76—1.91", "居鲁士圆柱（波斯的正统叙事）", "《剑桥古代史》第4卷"], tags: ["萨迪斯", "吕底亚亡", "骑兵"] }, related: [] },
  { id: "world--b540--p01", track: "world", year: -540, yearApprox: true, dim: "politics", weight: 3, title: "波斯领有爱奥尼亚诸城", summary: "希腊城邦交出舰队，以纳贡换自治的开端。", detail: { background: "吕底亚亡后爱奥尼亚拒附，米利都以和约得保集市与祭祀自由。", process: "哈尔帕戈斯沿海岸征诸城，希罗多德记其「以围城、断水与内应取之」，波斯随后取诸岛与赫勒斯滂殖民城；部分居民西逃殖民（如福凯亚人赴马赛与科西嘉）。", impact: "波斯第一次统治说希腊语的城市并取得船材与水手，爱奥尼亚的僭主与贵族成为帝国代理人，为其后起义与前490年的冲突积怨。", figures: ["哈尔帕戈斯", "不可考的米利都使节"], place: "以弗所、米利都与福凯亚", state: "波斯帝国与爱奥尼亚", sources: ["希罗多德《历史》1.143—1.169", "《剑桥古代史》第4卷", "福凯亚与马赛考古简报"], tags: ["爱奥尼亚", "纳贡", "僭主"] }, related: [] },
  { id: "world--b539--m01", track: "world", year: -539, yearApprox: true, dim: "military", weight: 5, title: "巴比伦城陷落", summary: "波斯军不战而入帝都，两河千年古国易主。", detail: { background: "拿波尼度长期远离巴比伦、得罪马尔杜克祭司集团，城内粮价高而防务散。", process: "居鲁士先取奥皮斯，前539年10月（巴比伦「塔什里图」月）乌格巴鲁率军沿幼发拉底入城，国王退据内城被俘，「战事未至宫城而城已陷」（居鲁士圆柱与巴比伦编年史语）。", impact: "波斯承继巴比伦的赋税、商路与学者传统，近东自此归于一个从印度河到埃及的单一政权，希腊史家称之为「亚述—波斯」的接续。", figures: ["居鲁士二世", "拿波尼度", "乌格巴鲁（戈贝尔总督）"], place: "巴比伦与奥皮斯", state: "波斯帝国与新巴比伦王国", sources: ["居鲁士圆柱铭文", "巴比伦编年史（前539年条）", "《拿波尼度诗文》与祭司文书研究综述"], tags: ["巴比伦陷落", "不战而入", "政权更替"] }, related: [] },
  { id: "world--b538--p01", track: "world", year: -538, yearApprox: true, dim: "politics", weight: 4, title: "居鲁士诏与犹大回归", summary: "新主许徙民返里，复建圣殿。", detail: { background: "新巴比伦以迁徙精英为统治术，波斯则需沿边忠顺的纳税社群。", process: "以斯拉记存「居鲁士诏」希伯来文，许犹大人返耶路撒冷并归还圣殿器皿；考古与文本研究多认此诏符合波斯「复其神像、归其民于故土」的通例（圆柱铭文可校）。", impact: "回归与重建使犹太共同体从王国遗民转为以律法与圣殿为中心的宗教民族，其经文的编订与正典化由此展开。", figures: ["居鲁士二世", "设巴萨（首批回归者首领）"], place: "巴比伦与耶路撒冷", state: "波斯帝国与犹大", sources: ["《希伯来圣经·以斯拉记》1章", "居鲁士圆柱铭文", "《以色列回归时期的考古》综述"], tags: ["居鲁士诏", "回归", "第二圣殿"] }, related: [] },
  { id: "world--b535--c01", track: "world", year: -535, yearApprox: true, dim: "culture", weight: 3, title: "大雄与耆那教的僧伽", summary: "苦行传统经其手，成两派并立之教团。", detail: { background: "恒河平原的沙门思潮与婆罗门献祭相抗，筏驮摩那（大雄）为诸祖谱系之末祖。", process: "耆那教传其舍家苦修十二年，于吠舍离一带成「最胜智」，立不杀、不妄语、不盗、不淫、离欲五戒，分白衣与天衣两派之端（文献年代多后出，学界推定其活动于前6世纪）。", impact: "「不害」原则由此成为南亚伦理与饮食、法律观的核心范畴，其出家团与信众网络亦长期与王权相互依存。", figures: ["筏驮摩那（大雄）"], place: "吠舍离与王舍城一带", state: "恒河平原诸邦", sources: ["《耆那教圣典》（迦罗经）", "《剑桥印度史》第1卷（沙门传统章）", "耆那教口传世系研究综述"], tags: ["大雄", "不害", "苦行僧团"] }, related: [] },
  { id: "world--b535--m01", track: "world", year: -535, yearApprox: true, dim: "military", weight: 3, title: "阿拉里亚海战", summary: "迦太基与伊特鲁里亚联舰挡住福凯亚人西迁。", detail: { background: "福凯亚希腊人自科西嘉的阿拉利亚向外劫掠，威胁撒丁与伊特鲁里亚的海上税。", process: "希罗多德记六十艘福凯亚船对抗彼等联军数百船（数字为其所闻），「以船连船」接舷而希腊方大败，此后科西嘉与撒丁的势力线重划。", impact: "此战确立迦太基—伊特鲁里亚的西地中海同盟格局，希腊西扩受阻，为日后布匿战争的阵营划分留下底本。", figures: ["不可考的福凯亚船长", "迦太基与伊特鲁里亚指挥官"], place: "科西嘉阿拉利亚近海", state: "迦太基、伊特鲁里亚与福凯亚", sources: ["希罗多德《历史》1.166—1.168", "撒丁与科西嘉考古调查简报", "《布匿的地中海》图录"], tags: ["阿拉利亚", "海战", "西地中海"] }, related: [] },
  { id: "world--b530--f01", track: "world", year: -530, yearApprox: true, dim: "figure", weight: 3, title: "居鲁士二世的死与陵", summary: "创建者东征丧师，帕萨尔加德留下朴素的石冢。", detail: { background: "取巴比伦后，帝国东北的玛萨格泰与游牧诸部未服。", process: "古典诸说不一（希罗多德记其与托米丽丝之战、巴比伦文书则记其死于归途）；今伊朗帕萨尔加德存白色石灰岩墓，七级台阶与带楣室与「居鲁士之室」铭（铭文残存可读者存争议）。", impact: "其死未动摇国本，冈比西斯与后来的大流士皆以「居鲁士之家」为正统之源；其宽容政策与陵墓成为后世论「理想君王」的样板。", figures: ["居鲁士二世", "托米丽丝（传说之女王）"], place: "帕萨尔加德与锡尔河一带（推定）", state: "波斯帝国", sources: ["希罗多德《历史》1.201—1.214", "伊朗考古队帕萨尔加德测绘报告", "《伊朗剑桥史》第2卷"], tags: ["居鲁士", "陵墓", "正统"] }, related: [] },
  { id: "world--b529--f01", track: "world", year: -529, yearApprox: true, dim: "figure", weight: 3, title: "毕达哥拉斯立团于南意大利", summary: "流亡萨摩斯之哲人，结政教合一学友会于克罗顿。", detail: { background: "波斯取爱奥尼亚后，士人西迁；克罗顿为意大利最盛的希腊城。", process: "团规（后世传述）主素食、禁蚕豆、共财与静默五年，以数解音程与图形，成员任城中官职；其学派遗址与墓葬在今意大利南部多处可考（考古遗存与文献互证有限）。", impact: "「数是万物本原」与灵魂轮回之说同时进入希腊科学与宗教，柏拉图派与后来的新柏拉图主义皆承其绪。", figures: ["毕达哥拉斯", "米洛（克罗顿的议席持有者）"], place: "克罗顿与塔林敦", state: "大希腊诸城", sources: ["亚里士多德学派《毕达哥拉斯派》残篇", "波菲利《毕达哥拉斯传》", "《大希腊考古指南》"], tags: ["毕达哥拉斯", "数", "学友会"] }, related: [] },
  { id: "world--b528--c01", track: "world", year: -528, yearApprox: true, dim: "culture", weight: 3, title: "鹿野苑初转法轮", summary: "成道者向五人说中道，僧伽自此有了戒与托钵。", detail: { background: "释迦族出家的求道者在伽耶菩提树下自证后，往波罗奈寻故同行者。", process: "巴利《转法轮经》记其说苦、集、灭、道四谛与八正道，斥苦行与纵欲二边；五人成首批比丘，僧团依托钵与雨安居而存（经典结集年代远在其后，文本为口传整理）。", impact: "一套不以种姓与祭祀为入道条件的团体从此在恒河平原扩展，其伦理与修行体系后传斯里兰卡、中亚与东亚。", figures: ["释迦牟尼", "五比丘"], place: "波罗奈鹿野苑（今萨尔纳特）", state: "恒河平原诸邦", sources: ["《相应部·转法轮经》", "《中阿含》对应经", "萨尔纳特考古与碑铭简报"], tags: ["初转法轮", "八正道", "僧伽"] }, related: [] },
  { id: "world--b525--m01", track: "world", year: -525, yearApprox: true, dim: "military", weight: 4, title: "贝鲁西亚之战与波斯取埃及", summary: "冈比西斯二世决战于三角洲东端，尼罗河归于一主。", detail: { background: "普萨美提克三世复起，埃及欲拒波斯税与驻军，阿拉伯与希腊佣兵态度游移。", process: "古典记载与埃及铭文互校：波斯军以骆驼前锋破埃及军，围贝鲁西亚后追至孟菲斯，普萨美提克三世被俘后死于宫中（据希罗多德记其被迫饮己子之血）。", impact: "埃及成为波斯「第二十七王朝」，其谷税与船材输入帝国，此后三百年埃及的独立努力皆以外力（希腊或本土叛乱）为凭。", figures: ["冈比西斯二世", "普萨美提克三世"], place: "贝鲁西亚与孟菲斯", state: "波斯帝国与埃及", sources: ["希罗多德《历史》3.10—3.15", "乌贾哈雷桑涅塞特自传铭（波斯更替的埃及视角）", "《剑桥古代史》第4卷"], tags: ["贝鲁西亚", "埃及征服", "王朝更替"] }, related: [] },
  { id: "world--b524--i01", track: "world", year: -524, yearApprox: true, dim: "institution", weight: 3, title: "波斯治埃及的税制与祭司", summary: "征服者沿用法老的库藏，却以波斯官员掌兵与税。", detail: { background: "波斯需要埃及谷物与金银，又忌其叛，故分权而治。", process: "孟菲斯等地铭文记埃及贵族乌贾哈雷桑涅塞特先事塞伊特王、后为波斯王司库与书吏，「尼罗河之税依旧」；驻军与驿传置于孟菲斯至三角洲一线（据其自传与出土陶封）。", impact: "此模式（保留本地宗教与官僚、由外族掌军政财）在波斯各行省反复出现，也解释了埃及既反叛又长期依附帝国的矛盾。", figures: ["乌贾哈雷桑涅塞特"], place: "孟菲斯与塞易斯", state: "波斯第二十七王朝", sources: ["乌贾哈雷桑涅塞特自传铭（《古代波斯铭文选》对读）", "希罗多德《历史》3.28—3.30", "《剑桥古代史》第4卷"], tags: ["行省税制", "合作祭司", "双轨治理"] }, related: [] },
  { id: "world--b522--p01", track: "world", year: -522, yearApprox: true, dim: "politics", weight: 3, title: "大流士一世即位", summary: "冈比西斯暴亡后，七人合谋者之一登位平乱。", detail: { background: "冈比西斯死于叙利亚归途，传闻玛古僧（行僧）伪称其弟司美尔迪斯据位，行省纷纷自立。", process: "大流士与六人诛伪王，随后两年东征米底、玛尔吉亚那与巴比伦的两度叛乱，贝希斯敦楔形铭以三语自述其「以阿胡拉·马兹达之恩」得国（自叙铭文，属王室正统叙事）。", impact: "即位危机被转化为帝国整顿的契机：省制、税额定、军队常设与官方铭文体系皆在其手中成型，波斯由部族联合成领土帝国。", figures: ["大流士一世", "冈比西斯二世"], place: "波斯波利斯与巴比伦", state: "波斯帝国", sources: ["贝希斯敦铭（第一栏自述）", "希罗多德《历史》3.61—3.89", "《伊朗剑桥史》第2卷"], tags: ["大流士", "平乱", "正统叙事"] }, related: [] },
  { id: "world--b520--s01", track: "world", year: -520, yearApprox: true, dim: "science", weight: 3, title: "贝希斯敦铭刻", summary: "崖壁长铭以三种楔形文字记同一篇王颂。", detail: { background: "帝国需以各族可读之文告宣示王权，官方书吏有对照翻译传统。", process: "崖壁铭文分波斯、埃兰、巴比伦三种文字（另有阿拉米语简本），共逾五百行，记谱系、平叛年月与地理名；今伊朗克尔曼沙一带高崖难近，抄本与照片成研究基础。", impact: "此铭与波斯波利斯碑群同罗林森等人在19世纪对读释解，直接促成楔形文字与古波斯语的破译，近代亚述学由此诞生。", figures: ["大流士一世", "罗林森（近代的摹拓与释读者）"], place: "贝希斯敦（今克尔曼沙赫附近）", state: "波斯帝国", sources: ["《波斯皇家铭文》（肯特校订本）", "英国考古院贝希斯敦摹拓档案", "《伊朗剑桥史》第2卷"], tags: ["贝希斯敦", "三语铭", "破译"] }, related: [] },
  { id: "world--b519--i01", track: "world", year: -519, yearApprox: true, dim: "institution", weight: 5, title: "波斯的行省制与贡银", summary: "三十余省定贡额、置督官与巡视，帝国可计而可征。", detail: { background: "希罗多德与波斯碑铭各列其省名，大流士改革整合居鲁士以来的征服区。", process: "每省设萨特拉庇（军事与民政分置）、定年贡（如印度省以金计、巴比伦省以银与麦计，希腊文表列总数约一万四千六十他连得，为后世学者折算），置王使「国王之眼」巡按，驿道传令（希罗多德书其驿传之速）。", impact: "这套以定额贡、分权监察与驿传为骨架的行政体系，为亚历山大与罗马的近东治理提供模板，也是「帝国」一词的制度原型。", figures: ["大流士一世", "不可考的省督与王使"], place: "苏萨、波斯波利斯与诸省", state: "波斯帝国", sources: ["希罗多德《历史》3.89—3.95", "波斯波利斯设制碑铭（《波斯皇家铭文》）", "《伊朗剑桥史》第2卷（行政章）"], tags: ["行省制", "贡赋", "监察"] }, related: [] },
  { id: "world--b518--a01", track: "world", year: -518, yearApprox: true, dim: "art", weight: 3, title: "波斯波利斯的营建", summary: "帝国以同一石台建起万国朝贡的礼仪之都。", detail: { background: "大流士自选法尔斯的拉赫马特山麓为基地，「居鲁士之城」帕萨尔加德嫌狭。", process: "台基凿岩填筑，阿帕达纳厅七十二柱（存十三），阶壁浮雕以二十余族系贡使列队，工匠铭文记埃及、伊奥尼亚、迦勒底匠人同工（工酬以银与酒计，见防御档案泥板）。", impact: "其建筑语汇融合两河、埃及与希腊因素，成为波斯王权「万邦来朝」形象的标准像；亚历山大焚宫后遗址犹为帝国记忆的坐标。", figures: ["大流士一世", "不可考的各族工匠"], place: "波斯波利斯（今伊朗设拉子东北）", state: "波斯帝国", sources: ["波斯波利斯发掘与浮雕图录", "工役档案「要塞表」泥板（芝加哥大学校订）", "《伊朗剑桥史》第2卷"], tags: ["波斯波利斯", "贡使浮雕", "工匠档案"] }, related: [] },
  { id: "world--b516--e01", track: "world", year: -516, yearApprox: true, dim: "economy", weight: 3, title: "御道与驿传", summary: "从苏萨到萨尔迪斯的官道设一百余驿馆。", detail: { background: "帝国军政文书与贡物运输需可靠路线，旧亚述官道为其雏形。", process: "希罗多德记此道长「王里一万三百九十」，设一百一十一驿馆，「雨雪寒暑之夜」驿马不换程，七日可达；考古在其沿线见关隘、桥与要塞（今土耳其与伊朗路段实测里数与文献有出入）。", impact: "驿道使政令、商队与军队可跨大陆调度，也带动沿线市镇、铸币与阿拉米文公文流通，为后世罗马官道提供可比之例。", figures: ["大流士一世", "不可考的驿卒"], place: "苏萨至萨尔迪斯（小亚细亚段）", state: "波斯帝国", sources: ["希罗多德《历史》5.52—5.54", "沿途考古调查简报", "《波斯帝国的道路与行政》研究综述"], tags: ["御道", "驿传", "行政地理"] }, related: [] },
  { id: "world--b515--x01", track: "world", year: -515, yearApprox: true, dim: "explore", weight: 3, title: "斯基拉克勘印度河与出洋", summary: "波斯命克里特人率船队探印度河入海之路。", detail: { background: "大流士欲知印度东北境与东方海岸，并取印度木与商路。", process: "希罗多德记斯基拉克自帕克图雅（印度河上游）下行至海口，再西航凡三十月至红海，其书（已佚，转引于《地理志》）为此事主要来源；印度河下游的波斯据点与税籍见于碑铭（地名比定有争）。", impact: "这是有文献可考的最早从印度洋通红海的航海记录之一，波斯的印度洋航线由此并入，后来的托勒密与阿拉伯航路承其余绪。", figures: ["斯基拉克", "大流士一世"], place: "印度河下游至红海", state: "波斯帝国", sources: ["希罗多德《历史》4.44", "斯特拉波《地理志》15.1.16（转引斯基拉克）", "《伊朗剑桥史》第2卷"], tags: ["印度河", "勘航", "印度洋"] }, related: [] },
  { id: "world--b513--x01", track: "world", year: -513, yearApprox: true, dim: "explore", weight: 3, title: "大流士的斯基泰远征", summary: "浮桥渡博斯普鲁斯，大军入草原而不得决战。", detail: { background: "斯基泰人拒纳贡并扰色雷斯，波斯欲消北患、索多瑙河诸部之贡。", process: "希罗多德记以船桥渡海峡（米利都人的工法，并向色雷斯人征船），沿途置驿六十处、军进至波尔息斯提涅斯与「王坟」一带；斯基泰以退却、填井、驱牛群疲之，波斯军粮尽而退，仅取斯基泰的属部（地名与路线学界多存疑）。", impact: "虽未取胜，此役把色雷斯与马其顿压入波斯属邦体系，也为后来薛西斯远征留下浮桥与粮道之成例。", figures: ["大流士一世", "斯基泰诸王"], place: "博斯普鲁斯至黑海北岸", state: "波斯帝国与斯基泰诸部", sources: ["希罗多德《历史》4.80—4.141", "黑海北岸与色雷斯考古调查", "《波斯在黑海北岸》研究综述"], tags: ["斯基泰", "浮桥", "远征"] }, related: [] },
  { id: "world--b510--p01", track: "world", year: -510, yearApprox: true, dim: "politics", weight: 3, title: "斯巴达逐雅典僭主", summary: "克列奥梅尼率伯罗奔尼撒军入卫城，僭政终结。", detail: { background: "许庇尔科斯与波斯、色萨利结姻，雅典贵族与德尔菲神谕屡促斯巴达「解放」一城。", process: "希罗多德记斯巴达两度出征，第一次夜袭败退，第二次围卫城数日而以计诱其出走；僭主家族北去西吉昂、后又通波斯（其子后随薛西斯入雅典）。", impact: "僭政倒台后贵族复争再起，正是这一真空使克里斯提尼的改革得以成行，雅典「自由即治国」的政治记忆由此开端。", figures: ["克列奥梅尼一世", "许庇尔科斯"], place: "雅典卫城", state: "斯巴达与雅典", sources: ["希罗多德《历史》5.63—5.66、6.123", "亚里士多德《雅典政制》20章", "《剑桥古代史》第4卷"], tags: ["僭主放逐", "斯巴达干涉", "雅典自由"] }, related: [] },
  { id: "world--b509--i01", track: "world", year: -509, yearApprox: true, dim: "institution", weight: 5, title: "罗马共和国的建立", summary: "王既放逐，罗马以同权二年执政官代王权。", detail: { background: "传说塔克文家族暴虐（卢克丽霞案后订立的瓦莱里乌斯法），贵族与平民联合废王。", process: "李维记其立两执政官、任一年、彼此可否决，「执政官」之号由「统帅军权」而来；布鲁图斯与科尔拉丁努斯为首任，后以瓦莱里乌斯法许平民就大职（部分制度为后世追记，年代学界视为半传说）。", impact: "「王」在罗马从此成为禁忌词，同僚制、任期制与元老院协商构成共和骨架，其模式为近代分权与任期思想反复征引。", figures: ["布鲁图斯", "塔克文·苏佩布（被逐之王）"], place: "罗马", state: "罗马共和国", sources: ["李维《建城以来史》2.1—2.8", "普鲁塔克《波普利科拉传》", "《剑桥古代史》第7卷第1分册（共和初期章）"], tags: ["废王", "执政官", "同僚制"] }, related: [] },
  { id: "world--b508--e01", track: "world", year: -508, yearApprox: true, dim: "economy", weight: 3, title: "罗马与迦太基的第一约", summary: "新建的共和国与商业大国划出海上界线。", detail: { background: "迦太基控西地中海商站，罗马无舰队但需粮与盐路安全。", process: "波利比乌斯所录约文：罗马人不得越「美丽角」以西贸易，不得取利比亚与撒丁之民，迦太基人则不犯拉丁姆与希腊盟友之地（约文年代与文本真伪学界有辨）。", impact: "此约为后来两次布匿战争的边界论据，也说明共和国初立即以条约处理海上利益，其外交习惯影响整个地中海史。", figures: ["不可考的罗马使节", "不可考的迦太基富商政府"], place: "罗马与迦太基", state: "罗马共和国与迦太基", sources: ["波利比乌斯《历史》3.22—3.26", "《剑桥古代史》第7卷第2分册（迦太基章）", "布匿条约研究综述"], tags: ["航海条约", "势力线", "布匿"] }, related: [] },
  { id: "world--b508--i01", track: "world", year: -508, yearApprox: true, dim: "institution", weight: 5, title: "克里斯提尼的部落重组", summary: "以地域德谟代血族部落，雅典民主的制度底座成形。", detail: { background: "贵族依四部族与亲缘分配官职，僭主倒台后党争又起；克里斯提尼转求平民支持。", process: "改革设阿提卡一百三十余德谟、划三一区为十部落，五百人会议由各部落按名册抽签选出，十将军由部落各举一人；又设陶片放逐之制以防个人僭政（亚里士多德《雅典政制》20—22章条分缕析）。", impact: "政治身份从宗族改系于住址与册籍，异邦人与底层得入会议与法庭，「德谟」自治与国家治理合一，民主由此可运行而非口号。", figures: ["克里斯提尼"], place: "雅典与阿提卡", state: "雅典城邦", sources: ["亚里士多德《雅典政制》20—22章", "希罗多德《历史》5.66、6.131", "《雅典德谟名录》碑铭研究"], tags: ["德谟", "十部落", "抽签制"] }, related: [] },
  { id: "world--b506--i01", track: "world", year: -506, yearApprox: true, dim: "institution", weight: 3, title: "五百人会议与轮值主席团", summary: "常设的议事会取代四百人，每季抽签轮掌城事。", detail: { background: "十部落体制需一个能常年筹备公民大会议程的机构。", process: "五百人会议（布勒）分十组「主席团」轮流当值约三十五天，掌议案、财政与使节；会议所在议事厅与档案石板（今存议员名录碑）遗址在雅典市集北侧（考古定位与复原）。", impact: "轮值与抽签使多数公民一生可数次亲历政务，形成希腊式的「治人与被治轮换」政制观，为此后伯里克利时代的津贴制铺垫。", figures: ["不可考的雅典首任议员"], place: "雅典市集议事厅", state: "雅典城邦", sources: ["亚里士多德《雅典政制》43—49章", "雅典议事厅与名录碑发掘简报", "《雅典政制史》研究综述"], tags: ["布勒", "轮值", "抽签"] }, related: [] },
  { id: "world--b500--s01", track: "world", year: -500, yearApprox: true, dim: "science", weight: 3, title: "巴比伦天文日志与周期", summary: "数百年连续观测，辑为可推算之日月食周期。", detail: { background: "自新巴比伦起，神庙逐日记录月出、行星与价格，形成连续「天文日志」传统。", process: "前6—前5世纪的泥板以「沙尔」周期（十八年又十一日）推日月食，另有以六十年为节的会合周期表，另有系统的「目标文本」定各行星首见日（抄本多为后世，但数据源在此期）。", impact: "这套周期算法经希腊天文学转入西方可推算的天文学，托勒密与后来的历法皆用其法；黄道十二宫之名亦成于斯。", figures: ["不可考的巴比伦观测书吏"], place: "巴比伦与乌鲁克", state: "波斯治下的巴比伦尼亚", sources: ["大英博物馆天文日志泥板藏目", "《巴比伦天文学史》专著综述", "《巴比伦数学天文泥板》校订本"], tags: ["天文日志", "沙尔周期", "黄道十二宫"] }, related: [] },
  { id: "world--b499--p01", track: "world", year: -499, yearApprox: true, dim: "politics", weight: 3, title: "爱奥尼亚起义", summary: "纳克索斯败后，米利都阿里斯塔戈拉斯举兵叛波。", detail: { background: "波斯以希腊僭主治爱奥尼亚，赋税与兵役日重；阿里斯塔戈拉斯失宠于王廷。", process: "其先怂恿大流士取纳克索斯不克（前500年前后），遂于米利都弃僭职、号召诸城逐僭主，遣使求援；斯巴达拒之，雅典与埃雷特里亚出二十艘船，前498年与雅典军同焚萨迪斯（希罗多德卷5记其详）。", impact: "起义把雅典拖入与波斯的直接冲突，大流士以「雅典人」为复仇之名；萨迪斯之焚成为后来马拉松远征的官方理由。", figures: ["阿里斯塔戈拉斯", "大流士一世"], place: "米利都与萨迪斯", state: "爱奥尼亚诸城与波斯帝国", sources: ["希罗多德《历史》5.29—5.105", "《波斯与希腊的战争》研究综述", "米利都考古简报"], tags: ["爱奥尼亚起义", "焚萨迪斯", "雅典介入"] }, related: [] },
  { id: "world--b494--i01", track: "world", year: -494, yearApprox: true, dim: "institution", weight: 3, title: "第一次平民撤离与保民官", summary: "罗马平民退出城邦，换得人身不可侵犯的护民之职。", detail: { background: "债奴法与外战兵役（维伊与埃奎人）使平民负担过重，贵族独享分地。", process: "李维记前494年平民退至阿尼奥河北的「圣山」，贵使谈判后许设两名平民保民官、其人身 sacrosanct、可否决长官令与召集平民会议（制度细节为后世追记，学界认为多为渐进形成）。", impact: "保民官与平民会议成为共和国特有的「否决性」机构，此后两百年的土地、债务与官职之争皆以此为其合法工具。", figures: ["米尼乌斯·阿格里帕（传说中的谈判者）", "不可考的首批保民官"], place: "罗马与圣山", state: "罗马共和国", sources: ["李维《建城以来史》2.23—2.33", "《罗马史》（狄奥尼修斯）6.80—6.89", "《罗马共和国的冲突》研究综述"], tags: ["平民撤离", "保民官", "人身神圣"] }, related: [] },
  { id: "world--b494--m01", track: "world", year: -494, yearApprox: true, dim: "military", weight: 3, title: "拉德海战与起义的平定", summary: "腓尼基与塞浦路斯联舰破爱奥尼亚舰队于米利都外海。", detail: { background: "起义诸城出船三百余艘，波斯以海上强的腓尼基人应战，狄欧尼修斯建议退守米利都海路。", process: "希罗多德记因萨摩斯人先退出阵，联军溃于拉德岛附近，波斯随后取米利都，焚城、徙民于阿米斯与苏萨一带，阿波罗神庙与议事厅未毁（其说据其转述）。", impact: "起义失败使波斯重掌爱琴海东岸，米利都的哲学与诗学人才西散；大流士随即转向惩罚雅典与埃雷特里亚，希波战争进入希腊本土地段。", figures: ["狄欧尼修斯（福凯亚将领）", "达乌里塞斯（波斯将领）"], place: "拉德岛与米利都外海", state: "波斯帝国与爱奥尼亚", sources: ["希罗多德《历史》6.6—6.22", "米利都与拉德岛水下考古简报", "《波斯与希腊的战争》研究综述"], tags: ["拉德", "米利都陷落", "起义终结"] }, related: [] },
  { id: "world--b492--m01", track: "world", year: -492, yearApprox: true, dim: "military", weight: 2, title: "玛尔杜尼乌斯的第一次远征", summary: "波斯陆海并进取色雷斯，舰队绕阿索斯遇风暴覆没。", detail: { background: "大流士遣其婿玛尔杜尼乌斯整军，先定陆路以避海风险。", process: "希罗多德记其过赫勒斯滂、以武力与联姻服马其顿与色雷斯诸部；运船队绕阿索斯岬时「西风起，船碎于海岸者三百艘，人畜沉没无数」（数字与细节为其所闻，属后世转述）。", impact: "陆军虽成，波斯失去海运补给能力，远征雅典推迟；阿索斯与色雷斯自此成为希腊—波斯冲突的地理背景。", figures: ["玛尔杜尼乌斯"], place: "色雷斯与阿索斯岬", state: "波斯帝国", sources: ["希罗多德《历史》6.43—6.45", "色雷斯与马其顿考古调查", "《波斯与希腊的战争》研究综述"], tags: ["色雷斯", "风暴", "远征受挫"] }, related: [] },
  { id: "world--b490--m01", track: "world", year: -490, yearApprox: true, dim: "military", weight: 4, title: "马拉松战役", summary: "雅典步兵击退波斯登岸军于马拉松湾。", detail: { background: "达提斯与阿耳塔夫列斯率军渡爱琴，取埃雷特里亚后拟携其僭主希庇亚斯在阿提卡登陆。", process: "据希罗多德与考古（今马拉松战场遗址与殉葬冢），雅典一万名重装步兵与普拉提亚千人列阵，以两翼强、中央薄的方阵冲入波斯翼侧，波斯军登船退走；雅典一方阵亡一百九十二人（冢上碑名可查）。", impact: "此役成为雅典「以公民步兵胜东方大军」的建国神话，马拉松冢与墓地即其纪念物；大流士的报复计划与薛西斯的远征由此而起。", figures: ["米尔提亚德斯", "达提斯", "卡利马科斯"], place: "马拉松平原（阿提卡东北）", state: "雅典城邦与波斯帝国", sources: ["希罗多德《历史》6.94—6.137", "马拉松冢与殉葬坑发掘简报", "《希波战争》研究综述"], tags: ["马拉松", "方阵", "登陆战"] }, related: [] },
  { id: "world--b487--i01", track: "world", year: -487, yearApprox: true, dim: "institution", weight: 3, title: "陶片放逐法的首次施行", summary: "雅典以六千片陶票放逐一人，十年不改财产权。", detail: { background: "制度传设自克里斯提尼，但行用四十余年间未尝一试；马拉松后党争以阿里斯提德与忒米斯托克烈为轴。", process: "公民在集市设投票区，以陶片（希腊文语汇「放逐」即由此，今出土陶片逾百枚，多刻人名）书所欲逐者，满六千票则其人出境十年（今考古所得陶片多刻「阿里斯提德」名）。", impact: "此法把「过于突出者」的裁制权交给公民集体，成为雅典防范僭政的独特工具，亦常被用于党争，其利弊为后世政治思想反复讨论。", figures: ["阿里斯提德（首位被逐者）", "忒米斯托克烈"], place: "雅典集市放逐区", state: "雅典城邦", sources: ["亚里士多德《雅典政制》22章", "普鲁塔克《阿里斯提德传》", "雅典出土放逐陶片研究"], tags: ["陶片放逐", "六千票", "党争"] }, related: [] },
  { id: "world--b483--c01", track: "world", year: -483, yearApprox: true, dim: "culture", weight: 3, title: "佛陀入灭与舍利分供", summary: "拘尸那揭罗的遗言与舍利分配决定僧团走向。", detail: { background: "佛教传统（斯里兰卡与往世书系统）以入灭年在前544至前400之间，此取其一说，学界多推在前5世纪末。", process: "巴利《大般涅槃经》记佛陀于拘尸那揭罗双树间说「以法为师」，舍利由八国分取起塔，摩揭陀与释迦族诸国遣使争分（塔与舍利供养之制由此）。", impact: "舍利塔崇拜使僧团获得稳定的施主与场所，为后来的第一次结集与阿育王分舍利建八万四千塔之说铺路，佛教传播的物质网络由此形成。", figures: ["释迦牟尼", "阿难（多闻第一弟子）", "大迦叶"], place: "拘尸那揭罗与王舍城", state: "恒河平原诸邦", sources: ["《长部·大般涅槃经》", "《摩诃僧祇律》对应段", "印度考古调查拘尸那揭罗简报"], tags: ["入灭", "舍利塔", "结集前史"] }, related: [] },
  { id: "world--b482--e01", track: "world", year: -482, yearApprox: true, dim: "economy", weight: 3, title: "劳里昂银矿与两百艘战舰", summary: "雅典以新矿之银造舰队，矿与税成民主的财政。", detail: { background: "波斯再征之兆已显，雅典与埃伊纳争海权久；旧矿与新脉之利多归佃户。", process: "据希罗多德与《雅典政制》，前483年矿业租约收入大增（记其得银一百塔兰特），忒米斯托克烈提议全数造舰（一百余艘三列桨船，另请富人认捐装备与训练），矿场奴隶与自由工匠分工采冶（今矿址遗迹与洗矿池密集成区）。", impact: "此举使雅典的海军由府库与租金供养，公民水手成为帝国权力的基础；矿与舰的关系也塑造了雅典财政与帝国贡金并行的结构。", figures: ["忒米斯托克烈", "不可考的劳里昂矿工"], place: "劳里昂与比雷埃夫斯", state: "雅典城邦", sources: ["希罗多德《历史》7.144—7.145", "亚里士多德《雅典政制》22章（矿业租约）", "劳里昂矿业考古调查"], tags: ["银矿", "舰队", "公共财政"] }, related: [] },
  { id: "world--b481--s01", track: "world", year: -481, yearApprox: true, dim: "science", weight: 3, title: "赫勒斯滂浮桥与阿索斯运河", summary: "波斯以两道船桥渡海峡，并于地峡凿运河通船。", detail: { background: "薛西斯为免舰队重蹈阿索斯风暴之险，命工程跨越博斯普鲁斯并开地峡水道。", process: "希罗多德记以三百余船并列、以纸莎草与亚麻缆系锚，上铺木板覆土；阿索斯地峡运河宽可两船并行、岸道可策马（工程规模学界视为夸大，但遗址与地名有考古线索）。", impact: "这组工程显示古代国家可动员跨大陆的土木与后勤能力，其「以船为梁」之法在罗马与后来的奥斯曼军事工程中反复使用。", figures: ["薛西斯一世", "不可考的埃及与腓尼基工程师"], place: "赫勒斯滂与阿索斯地峡", state: "波斯帝国", sources: ["希罗多德《历史》7.22—7.37", "博斯普鲁斯海峡考古与地质调查", "《波斯军队与后勤》研究综述"], tags: ["浮桥", "运河", "工程"] }, related: [] },
  { id: "world--b480--m01", track: "world", year: -480, yearApprox: true, dim: "military", weight: 4, title: "温泉关与阿尔特米西昂", summary: "希腊联军以寡当之于陆，同时于海面与波斯舰队相持。", detail: { background: "希腊在色摩比利（温泉关）与阿尔特米西昂设双线防，地峡诸邦则筑墙自守。", process: "据希罗多德与出土碑（今温泉关纪念铭文），斯巴达王列奥尼达率伯罗奔尼撒军与特斯皮亚、底比斯人守隘三日至四日，因埃菲阿尔忒斯引波斯「不死军」越山道，全军覆；同日海战因风暴与冲突未分胜负（希腊方损失亦重）。", impact: "温泉关的牺牲成为希腊世界「为法而战」的原型叙事，而海军的未溃使希腊得以保存舰队，为萨拉米斯的决战留下本钱。", figures: ["列奥尼达", "薛西斯一世", "玛尔杜尼乌斯"], place: "色摩比利隘口与阿尔特米西昂", state: "希腊联军与波斯帝国", sources: ["希罗多德《历史》7.175—7.233", "温泉关考古调查与铭文", "西蒙尼德斯的墓志铭（《希腊抒情诗残篇》）"], tags: ["温泉关", "隘口战", "殉国叙事"] }, related: [] },
  { id: "world--b480--d01", track: "world", year: -480, yearApprox: true, dim: "disaster", weight: 3, title: "波斯舰队遇风暴于阿索斯", summary: "萨拉米斯前的秋风暴碎波斯运粮船无数于塞耳裴多恩。", detail: { background: "薛西斯舰队自多卡斯转向阿索斯湾停泊，补给船队随后。", process: "希罗多德记「秋风起，泊于塞耳裴多恩附近之船相击碎，沉没船与人以万计」（数字为其所闻），希腊方面未经一战而得损彼大半辎重，波斯随后把舰队移入法莱隆以靠陆。", impact: "风暴使波斯海军无法独立维持长期封锁，其后续决战被迫切近岸作战，间接促成萨拉米斯海峡中的失败；此例常被引为战争中的气象变量。", figures: ["薛西斯一世", "不可考的波斯海军将领"], place: "塞耳裴多恩与阿索斯湾", state: "波斯帝国", sources: ["希罗多德《历史》8.12—8.14", "爱琴海古气候与洋流研究综述", "《波斯军队与后勤》研究综述"], tags: ["风暴", "补给船", "海难"] }, related: [] },
  { id: "world--b480--m02", track: "world", year: -480, yearApprox: true, dim: "military", weight: 5, title: "萨拉米斯海战", summary: "雅典主导的舰队以冲角击溃波斯舰队于海峡。", detail: { background: "雅典弃城，联军退至萨拉米斯与科林斯地峡；忒米斯托克烈以密使诱波斯船入狭水。", process: "据希罗多德与后来考古（今萨拉米斯岛东岸与法莱隆湾水下遗物），波斯船（其数古典记一千余、今学界推为六百左右）入峡后不能回转，希腊三列桨船以撞角断桨破之，自晨至暮，波斯退，薛西斯整军北归（王留守玛尔杜尼乌斯于色萨利）。", impact: "此役保存了希腊本岛的独立，确立雅典的海权，为其后提洛同盟与帝国财政奠基；地中海的东西权力线在一条海峡中被决定。", figures: ["忒米斯托克烈", "薛西斯一世", "阿里斯提德"], place: "萨拉米斯海峡", state: "希腊联军与波斯帝国", sources: ["希罗多德《历史》8.60—8.96", "埃斯库罗斯《波斯人》（同时代悲剧）", "萨拉米斯与法莱隆水下考古简报"], tags: ["萨拉米斯", "海战", "冲角"] }, related: [] },
  { id: "world--b479--m01", track: "world", year: -479, yearApprox: true, dim: "military", weight: 4, title: "普拉提亚战役", summary: "希腊重装步兵击溃波斯陆军与其希腊附庸于玻俄提亚。", detail: { background: "薛西斯北归后，玛尔杜尼乌斯越冬于色萨利，复取雅典废城，希腊联军在普拉提亚山麓集结。", process: "希罗多德记联军以斯巴达王保萨尼阿斯统万余重装步兵与希洛随军，波斯军含底比斯等希腊附庸；战斗中玛尔杜尼乌斯阵亡，波斯营寨被破（数字与细节后世有增饰）。", impact: "波斯在欧陆的军事存在终结，希腊本土再未受东方帝国的大规模征服；此后希腊反攻爱奥尼亚，「报复与解放」成为提洛同盟的旗帜。", figures: ["保萨尼阿斯", "玛尔杜尼乌斯"], place: "普拉提亚（玻俄提亚）", state: "希腊联军与波斯帝国", sources: ["希罗多德《历史》9.15—9.71", "普拉提亚战场与祭所考古简报", "《希波战争》研究综述"], tags: ["普拉提亚", "陆军决战", "反攻"] }, related: [] },
  { id: "world--b479--m02", track: "world", year: -479, yearApprox: true, dim: "military", weight: 2, title: "米卡列海战", summary: "希腊舰队焚波斯残舰于萨摩斯对面，爱奥尼亚再叛。", detail: { background: "波斯舰队冬泊库麦，春渡至米卡列山脚，与米利都的守军相依。", process: "希罗多德记雅典将领桑提波斯率船北上，希腊水手登岸击波斯营，腓尼基船先逃、爱奥尼亚人反戈（其叙事含希腊方战果夸大，数字以古典记法为准）。", impact: "此役使爱奥尼亚诸城重归希腊阵营，波斯的舰队势力退出爱琴海东部；「米卡列与普拉提亚同日」被希腊人视为神意的印证。", figures: ["桑提波斯", "列欧提基达斯"], place: "米卡列山与爱奥尼亚海岸", state: "希腊联军与波斯帝国", sources: ["希罗多德《历史》9.90—9.107", "米卡列与爱奥尼亚考古调查", "《波斯与希腊的战争》研究综述"], tags: ["米卡列", "登陆战", "爱奥尼亚光复"] }, related: [] },
];
